window.__D("text/torat-chaim/c035",{"p":[[2300550130,"במ\"א (וכמ\"ש בזהר ע\"פ כי על שולח\"ן המל\"ך<sup data-n=\"6749\">45</sup> כו') וכמ\"ש מצפו\"ן זה\"ב יאתה כו' (ואע\"פ שהעוש\"ר שרשו בדע\"ת<sup data-n=\"6750\">46</sup> והוא בחי' מזב\"ח הזה\"ב<sup data-n=\"6751\">47</sup> שבאמצע בין מנורה לשולחן<sup data-n=\"6752\">48</sup> שהקטורת שע\"ג מזבח הזהב מעשר\"ת<sup data-n=\"6753\">49</sup> כו', מ\"מ יותר יש שרש לעושר בצפון מבדרום וכמ\"ש בשמאל\"ה עושר<sup data-n=\"6754\">50</sup> בקו השמאל דבג\"ה<sup data-n=\"6755\">51</sup> וקאי על בחי' החכ' דאור\"ך ימי\"ם בימינה<sup data-n=\"6756\">52</sup> בחי' ריבוי החסדים שנק' ימים<sup data-n=\"6757\">53</sup> בקו ימין שלה והוא בבחי' חח\"נ<sup data-n=\"6758\">54</sup>, בשמאל\"ה דחכמ\"ה עוש\"ר וכבו\"ד כמ\"ש כבו\"ד חכמי\"ם ינחלו<sup data-n=\"6759\">55</sup> כו') וכמ\"ש במ\"א דבני חיי ומזוני<sup data-n=\"6760\">56</sup> לאו בזכות\"א היכל החסד תליא, אלא במזל\"א שהוא בחי' גבור\"ה כו'). והנה כל הכלים האלה שבמשכן עד מזבח החיצון שהוא בחי' המל'<sup data-n=\"6761\">57</sup> כו' הכל הוא בבחי' התלבשות האור בכלי דוקא, כמו אור החכמה בכלי הארון ובחי' אור החסד באור דמנורה להאיר באור חסד עליון (כי החסד נק' אור<sup data-n=\"6762\">58</sup> וכמ\"ש וירא אלקי' את האור כי טו\"ב<sup data-n=\"6763\">59</sup> וטו\"ב וחס\"ד א' הוא<sup data-n=\"6764\">60</sup> כמ\"ש כי טו\"ב חסד\"ך מחיים<sup data-n=\"6765\">61</sup> כו') בכלי המנורה כו', ואור הגבורה בשולחן וכיוצא בכל פרטי הכלים שבתוך המשכן. אבל בחי' היריעות הפרושות ע\"ג המזבח הן הנה לנגד בחי' אורות מקיפים העליונים המקיפים וסובבים מלמעלה שבלתי מוגבלי' ומתלבשים בכלי, וכך גם ענין הקרשים העומדי' להקיף מן הצדדים לכל הכלים שבמשכן. ולזה סידר להקדים תחלה כאן בפ' ויקהל לעשות המשכן ואהלו וקרשיו כו' שהן בחי' אורות מקיפי' ואח\"כ ארון ושולחן כו' שהן בחי' או\"פ, ובפ' תרומה תצוה הקדים לצוות על מעשה הארון ושולחן כו' בחי' או\"פ ואח\"כ לעשות היריעות והקרשים בחי' או\"מ כו' (ובגמ' אמרו דזהו פלוגתא שבין משה ובצלאל<sup data-n=\"6766\">62</sup>, למשה הי' הציווי לעשות הכלים תחלה ובצלאל אמר לו כלום אדם עושה כלים קודם לבנין בית אלא בונה בית ואח\"כ מכניס הכלים לתוכו וא\"ל משה בצ\"ל א\"ל היית וידעת<sup data-n=\"6767\">63</sup>, דהיינו שכיוון אל האמת להיות כי בהמשכה שמלמעלה למטה הרי תחלה בחי' מקיפים ואח\"כ בחי' כלים. וז\"ש בצ\"ל א\"ל בחי' הארת המקיף שנק' צ\"ל א\"ל היית ע\"כ אתה עושה <span data-k=\"pg\">1150</span> ּ בחי' המקיפים תחלה, וסברת משה הי' להיפך לעשות כלים תחלה שהוא כפי ההכנה מלמטה למעלה<sup data-n=\"6768\">64</sup> כמ\"ש במ\"א. ובזה מתורץ הקושי' הנ\"ל שבפ' תרומה תצוה היינו בציווי אל משה, ובפ' זו הוא מדבר בעשי' דבצלאל וכמו בפ' כי תשא שמדבר בעשי' דבצלאל הקדים ג\"כ המשכן לארון כו' וד\"ל).",[["6749","45","<b>כי על שולח\"ן המל\"ך</b>: נסמן לעיל פ' תרומה שז, ג."],["6750","46","<b>שהעוש\"ר שרשו בדע\"ת</b>: ראה שער האמונה כה, ב ובהערה 41."],["6751","47","<b>בדע\"ת. . מזב\"ח הזה\"ב</b>: ראה גם לקמן שצ, ג. לקלו\"י הערות לזהר לך ע' נב."],["6752","48","<b>מזב\"ח הזה\"ב. . לשולחן</b>: יומא לג, ב."],["6753","49","<b>שהקטורת. . מעשר\"ת</b>: יומא כו, א."],["6754","50","<b>בשמאל\"ה עושר</b>: משלי ג, טז."],["6755","51","<b>בקו השמאל דבג\"ה</b>: נסמן לעיל פ' יתרו רסט, ג הערה 19."],["6756","52","<b>דאור\"ך ימי\"ם בימינה</b>: משלי שם."],["6757","53","<b>החסדים שנק' ימים</b>: ראה פרדס (שער עה\"כ) שכ\"ג מערכת יום. מאמרי אדה\"א שמות ח\"א ע' קמא. וש\"נ. נ\"ך ע' קכט. תו\"ח בראשית יד, ב."],["6758","54","<b>בקו ימין. . חח\"נ</b>: נסמן לעיל שם."],["6759","55","<b>כבו\"ד חכמי\"ם ינחלו</b>: משלי ג, לה."],["6760","56","<b>דבני חיי ומזוני</b>: נסמן לעיל פ' תצוה שיט, ג."],["6761","57","<b>מזבח החיצון. . המל'</b>: נסמן לעיל פ' יתרו רסט, סע\"ג ואילך."],["6762","58","<b>החסד נק' אור</b>: נסמן לעיל פ' תצוה שיט, א."],["6763","59","<b>וירא אלקי' את האור כי טו\"ב</b>: בראשית א, ד."],["6764","60","<b>וטו\"ב וחס\"ד א' הוא</b>: ראה תו\"ח בראשית ח, ג ובהערה 49."],["6765","61","<b>כי טו\"ב חסד\"ך מחיים</b>: תהלים סג, ד."],["6766","62","<b>פלוגתא שבין משה ובצלאל</b>: ראה ברכות נה, א."],["6767","63","<b>בצ\"ל א\"ל היית וידעת</b>: ברכות שם. ראה גם לעיל פ' תרומה שי, ב. לקמן תלא, ב."],["6768","64","<b>וסברת משה. . מלמטה למעלה</b>: ראה גם לעיל פ' תרומה שי, א ואילך. ובהנסמן בריש המאמר שם."]]],[2300550162,"<b>והנה</b> להבין כל הנ\"ל בבאר היטב, הנה להבין כללות ענין כלי המשכן שהן בבחי' או\"פ והיריעות שהן בחי' או\"מ כנ\"ל, צריך להקדים ענין הידוע בב' מדרגות כלליות הנמשך מעצמו' א\"ס ב\"ה בחי' סובב כ\"ע ובחי' ממלא כ\"ע<sup data-n=\"6769\">65</sup> בלשון הזהר ובלשון המקובלים הוא בחי' אור מקיף הכללי ובחי' אור<sup data-n=\"6770\">67</sup> פנימי<sup data-n=\"6771\">66</sup> הכללי, כי בחי' מל' דא\"ס שלפני בחי' הצמצום הראשון הנק' מקום פנוי וחלל ריקן<sup data-n=\"6772\">68</sup> כו' כמ\"ש בע\"ח נק' מקיף הכללי ובחי' הקו וחוט שנמשך בבחי' מעלה ומטה באבי\"ע כו' נק' בחי' או\"פ כללי כי הוא מקור כל האו\"פ<sup data-n=\"6773\">69</sup> כו' וזהו בכללות ההשתל'. וכמו\"כ הוא בפרטי פרטות ההשתל' בכל עולם בפרט יש ב' מדרגות הללו דהיינו שנמשך אור השפע בב' אופנים הללו בבחי' סובב וממלא בחי' מקיף ופנימי, אלא שהוא בפרט לאותה המדרגה הפרטי' בלבד כו' וכידוע. והנה בחי' מקיף וסובב הנ\"ל יש לו עוד שם בלשון הגמ' והוא הנק' מזל\"א כמו שאמרו גבי חבירי דניאל במ\"ש דחרדה גדולה נפלה עליהם<sup data-n=\"6774\">70</sup> אע\"פ שלא ראו את המראה כלל דפריך בגמ' אי לא חזי אמאי איבעות ומשני דאע\"ג דאינהו לא חזו מזלייהו חזי, ולכאו' אין התירוץ הזה מובן דאיך יפול החרדה מצד בחי' מזלייהו בלבד אם לא ראו שום מראה גם לא בעין השכל כו'. אך הענין הוא כידוע שעצמות הנפש ממש בלתי מלובשת כלל בכלי הגוף כי רק מבחי' כח החכמה שבנפש מתחיל ראשית גילוי ההתפשטות בכלי המוח כו', אבל עצם הנפש עצם אור פשוט מובדל ומושלל בערך מהיות גם בחי' מקור ושרש לבחי' אור החכמה שבכלי המוח, כי גם מה שמאיר אור החכמה מן הנפש אינו אלא גילוי הארה מצומצמת מאד לגבי עצמותה כידוע, וע\"כ גם בחי' אור המקיף על החכמה הוא בבחי' ההעלם בלתי נרגש בכלי ההשגה כלל וכלל והוא הנק' מזלא, פי' מזל\"א לשון מפעיל<sup data-n=\"6775\">71</sup> שמאיר מלמעלה בבחי' ההעלם למעלה מכלי ההשגה ולפעמים יאיר בגילוי, והוא אשר תפול החרדה שהוא בחי' הביטול במציאות למעלה מן הטעם וההשגה מבלי ירגיש דבר בכלי מוחו כלל רק שיחרד ויתבטל בלא טעם מפני הארת בחי' מזלא הזה כמו בחבירי דניאל שבכלי<sup data-n=\"6776\">72</sup> השגתם הי' קטן מהכיל להשיג מראה הנבואה. וז\"ש דאינהו לא חזו בעין השכל כלום, אבל בחי' אור המקיף שבהעלם על כלי ההשגה שנק' מזל\"א חז\"ו פי' שהאיר האור במזלייה\"ו בבחי' גילוי, ע\"כ מפני שהרגישו האור בבחי' מקיף שלהם נפלה חרדה גדולה עליהם למעלה מן הטעם שהוא",[["6769","65","<b>סובב. . ממלא כ\"ע</b>: זהר (רע\"מ) פינחס רכה, א."],["6770","67","<b>אור מקיף. . אור פנימי</b>: ראה לעיל פ' וארא נז, ב הערה *7."],["6771","66","<b>סובב. . ממלא. . אור מקיף. . אור פנימי</b>: ראה גם מאמרי אדה\"א שמות כאן ע' תרסא. דברים ח\"ג ע' א'נג. הנחות תקע\"ז ע' שכז."],["6772","68","<b>הצמצום. . מקום פנוי וחלל ריקן</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א, ענף ב."],["6773","69","<b>הקו וחוט. . מקור כל האו\"פ</b>: ראה גם לעיל פ' שמות כד, א. וש\"נ."],["6774","70","<b>דחרדה גדולה נפלה עליהם</b>: דניאל י, ז. ראה מגילה ג, א. לעיל פ' בא צט, ג. וש\"נ."],["6775","71","<b>מזל\"א לשון מפעיל</b>: ראה גם לעיל פ' בא קלג, ב. וש\"נ."],["6776","72","<b>שבכלי</b>: כ\"ה בגוכתי\"ק."]]],[2300550194,"בחי' ביטול במציאות, משא\"כ דניאל שהשיג את המראה בכלי ההשגה לא נתבטל כו', אבל חביריו מפני שלא השיגו בבחי' או\"פ כ\"א במזלייה\"ו בלבד ע\"כ חרדה גדולה נפלה עליהם וד\"ל.\n<b>והדוגמא</b> מזה יובן למעלה בבחי' אוא\"ס עצמו שנק' בחי' <span data-k=\"pg\">תקעה</span> ּ סובב ומקיף הכללי כנ\"ל שהוא ע\"ד הנ\"ל בענין מזל\"א כו' דהיינו שהוא מובדל ומרומם בערך מכל ההשתלשלו' דקו וחוט (כמו עד\"מ עצמות הנפש שמושללת לגמרי מכוחותיה) גם מהיות בחי' מקור למקור גם להתהוות בחי' חכ' שנק' ראשית<sup data-n=\"6777\">73</sup> וגם לבחי' חכמה הקדומה דא\"ק וכמ\"ש לית מחשבה תפיסא בך<sup data-n=\"6778\">74</sup> אפי' מחשבה דא\"ק כו'), וההארה שמאיר מעצמות אוא\"ס הוא בבחי' מקיף בהעלם ע\"י בחי' הצמצום שנק' מקום פנוי כו' אז דוקא נמשך אור ומקור להיות בחי' חכמה והוא בחי' הקו הנ\"ל שהוא מקור כל האו\"פ כו', רק לפעמים יאיר אור מקיף וסובב הזה הכללי בבחי' גילוי מן ההעלם ואעפ\"כ הוא בא בבחי' מקיף למעלה מכלי קבלת הנאצלים גם למעלה מבחי' אור החכ' הקדומה הנ\"ל, וכמו דמיון הארת בחי' מזל\"א שמאיר לפעמים בגילוי אבל הוא למעלה מן ההשגה דחכמה רק הוא בא בבחי' ביטול המציאות כמו החרדה, ועד\"ז הי' במ\"ת בהארת קול השופר דכתי' ויחרד כל העם<sup data-n=\"6779\">75</sup> כו' מפני שאז הי' בחי' גילוי עצמות אוא\"ס שלפני הקו כו' כמ\"ש וירד ה'<sup data-n=\"6780\">76</sup> כו' אנכ\"י מי שאנכ\"י<sup data-n=\"6781\">77</sup> כמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> ה' בחכמה<sup data-n=\"6782\">78</sup> כו'. פי' בחכמה כלומר בשביל מציאת החכמה מעצמות המאציל שהוא מרומם בערך מאד כנ\"ל הוצרך להיות ע\"י שם הוי' יו\"ד ה\"א כו'. וגם להיות אור א\"ס מאיר בבחי' חכמה דאצי' שהיא בחי' ראשית גילוי אור ומקור הראשון לכל האצי' וכמ\"ש בע\"ח דאור אבא שרש כל האצי'<sup data-n=\"6783\">79</sup>, אעפ\"כ בהיות שאין ערך לחכמה עם עצמות המאציל הוצרך לבא בבחי' ד' אותיות הללו עד שיתהווה אור החכמה מאין ליש וכמ\"ש והחכמה מאין תמצא<sup data-n=\"6784\">80</sup>, וזהו מ\"ש הוי' בחכמ\"ה ע\"י שם הוי' מתלבש אור א\"ס בחכמה. וענין שם הוי' ידוע שהיו\"ד הוא בחי' הצמצום והה\"א בחי' ההתפשטו'<sup data-n=\"6785\">81</sup> כי צורת היו\"ד אינו אלא נקודה א' שזה מורה בחי' העדר ההתפשטו' והגילוי רק כנקודה בעלמא, אך מ\"מ קצת גילוי<sup data-n=\"6786\">82</sup> אור יש בו רק שהוא מצומצם מאד כמו עד\"מ הברק כו' וכמ\"ש במ\"א, כך בחי' גילוי אור דחכמה מן ההעלם דעצמו' אוא\"ס אינו בא אלא בבחי' נקודה בלבד והוא",[["6777","73","<b>חכ' שנק' ראשית</b>: נסמן לעיל פ' יתרו רסד, ב."],["6778","74","<b>לית מחשבה תפיסא בך</b>: ת\"ז בהקדמה (יז, א)."],["6779","75","<b>ויחרד כל העם</b>: יתרו יט, טז."],["6780","76","<b>וירד ה'</b>: שם יט, כ. ראה גם מאמרי אדה\"ז תק\"ע ע' לד. מאמרי אדה\"א נ\"ך ע' תמה."],["6781","77","<b>אנכ\"י מי שאנכ\"י</b>: נסמן לעיל פ' יתרו רנד, ג."],["6782","78","<b>ה' בחכמה</b>: משלי ג, יט."],["6783","79","<b>דאור אבא שרש כל האצי'</b>: ראה ע\"ח (שער סדר אבי\"ע) שמ\"ז, פ\"ב."],["6784","80","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["6785","81","<b>שהיו\"ד. . הצמצום והה\"א בחי' ההתפשטו'</b>: ראה אגה\"ת פ\"ד."],["6786","82","<b>היו\"ד. . קצת גילוי</b>: ראה גם לעיל פ' בשלח קנ, ב. וש\"נ."]]],[2300550226,"הבא עכ\"פ בבחי' אור פנימי בחכמה (שהוא התלבשות אור בכלי מוגבל שהרי היו\"ד עכ\"פ נחשב מכלל אותיות שהן בחי' כלים<sup data-n=\"6787\">83</sup> כידוע), אבל בחי' קוצו של יו\"ד שאינו בכלל אות אלא הוא רק כמו תג קטן ומצומצם מאד ע\"ג היו\"ד הנה הוא בחי' אור מקיף דחכמה שהוא בבחי' ההעלם ע\"ג האור המתגלה בבחי' פנימי באות יו\"ד דחכמ\"ה כו'. וזהו ההפרש בין בחי' שם הוי' בניקוד קמ\"ץ ושם הוי' בניקוד פת\"ח<sup data-n=\"6788\">84</sup>, כנודע שיש ב' הויות, א' בקמץ מורה על בחי' הסתימות וההעלם כמו הקמ\"ץ שקומץ השפתיים וסוגרם וסותמם מבלי יתגלה כלום, והפתח הוא להיפך שפותח את השפתים שמורה על בחי' ההתגלות אור לחוץ דוקא וכמ\"ש פי\"ה פתח\"ה בחכמ\"ה<sup data-n=\"6789\">85</sup> מפני שהחכמה שנק' ראשית הגילוי אור בבחי' או\"פ כנ\"ל הוא בחי' שם הוי' בפתח<sup data-n=\"6790\">86</sup> כו' (ומ\"ש אד' שפת\"י <span data-k=\"pg\">1152</span> ּ תפת\"ח<sup data-n=\"6791\">87</sup> היינו ע\"י הארת אור החכמה גם בדבור שנק' פ\"ה וז\"ש פי\"ה פתח\"ה בחכמה כו' משום דאבא יסד ברתא<sup data-n=\"6792\">88</sup> כידוע), כי פתח לשון פתח שנפתח ונגלה האור לחוץ והיינו בחי' ראשית גילוי אור דחכמה שהוא ראשית גילוי והתפשטות אור באצי' כנ\"ל. אבל למעלה מבחי' הגילוי אור דחכמה שהוא בבחי' קוצו של יו\"ד הנ\"ל שנק' בחי' מקיף דחכמה בהעלם דוקא ואינו בא בבחי' גילוי והתפשטו' באצי' כלל, הוא בחי' שם הוי' בקמ\"ץ שמורה על בחי' הסתימות וההעלם דוקא כנ\"ל והוא בחי' כת\"ר שבחכמה כידוע שבכלל הקמ\"ץ בכת\"ר<sup data-n=\"6793\">89</sup> שהוא אור הנעלם והפת\"ח בחכמה מטעם הנ\"ל. ואע\"פ שבחי' ההעלם דחכמה אינו מתלבש בכלי בבחי' או\"פ וא\"כ איך יש בו שם הוי', הנה אעפ\"כ יש גם לבחי' המקיף הנעלם בחי' אותיות הוי' רק שהוא בבחי' ההעלם והסתימות דוקא, שהרי לגבי עצמות המאציל ממש גם בחי' ההעלם דאצי' נק' בחי' גילוי אור מצומצם בלבד מאחר שעצמות אוא\"ס פשוט בתכלית כו' ונק' סתימ\"ו דכל סתימי\"ן<sup data-n=\"6794\">90</sup> כו', וכמאמר דאפי' אור צח כו' אוכ\"ם הוא<sup data-n=\"6795\">91</sup> לגבי עילת העלות כו' דהיינו אפי' בחי' אור חכמה הקדומה שנק' שכל הנעלם מכל רעיו\"ן<sup data-n=\"6796\">92</sup> אפי' למעלה מהאצי' כו', והיינו כנ\"ל דעצמות אוא\"ס מובדל בערך לגמרי גם מהיות גם בחי' מקור דמקור לחכמה כו' רק ע\"י צמצום הנק' מקו\"פ כו' וד\"ל. וז\"ש נפלאותי\"ך ומחשבותי\"ך שהוא בחי' סתימ\"ו דכל סתימי\"ן הנ\"ל שהוא נפל\"א ונעל\"ם בעצמות, הנה בא אלינו בבחי' גילוי ע\"י ריבוי צמצומי', ע\"כ גם כי אגיד\"ה ואדבר\"ה להמשיך<sup data-n=\"6797\">*94</sup> אותם מן ההעלם לגילוי עצמו מספ\"ר<sup data-n=\"6798\">93</sup>, פי' שהן בלי גבול בבחי' א\"ס ממש להיות שרשם מלמעלה מכל ההשתלשלו' גם מהיות להם",[["6787","83","<b>אותיות שהן בחי' כלים</b>: ראה שער היחוד והאמונה ספ\"ד. לעיל פ' שמות כה, ג. וש\"נ."],["6788","84","<b>הוי' בניקוד קמ\"ץ. . פת\"ח</b>: ראה גם מאמרי אדה\"א שמות כאן ע' תרסב. וש\"נ."],["6789","85","<b>פי\"ה פתח\"ה בחכמ\"ה</b>: משלי לא, כו."],["6790","86","<b>שהחכמה. . בפתח</b>: ראה ת\"ז ת\"ע קכט, ב [וכן צ\"ל במאמרי אדה\"א דבסמוך]. לעיל פ' שמות מז, ג. מאמרי אדה\"א דברים ח\"ג ע' א'מב. וש\"נ."],["6791","87","<b>אד' שפת\"י תפת\"ח</b>: תהלים נא, יז."],["6792","88","<b>דאבא יסד ברתא</b>: נסמן לעיל פ' תשא שפג, ד."],["6793","89","<b>הקמ\"ץ בכת\"ר</b>: ראה ת\"ז ת\"ע (קכט, ב). פרדס (שער הנקודות) שכ\"ח, פ\"ה. מאו\"א בערכו סי\"ח. מאמרי אדה\"ז תקס\"ו ע' כג. תו\"ח בראשית מב, ד ובהערה 10. מאמרי אדה\"א ויקרא ח\"ב ר\"ע תנג. במדבר ח\"ב ע' שצג וע' תקפה. הנחות תקע\"ז ע' עב ובהנסמן בהנ\"ל."],["6794","90","<b>סתימ\"ו דכל סתימי\"ן</b>: ראה זהר בהקדמה ב, א. ועוד."],["6795","91","<b>אור צח כו' אוכ\"ם הוא</b>: ראה ת\"ז ת\"ע (קלה, ב). לעיל פ' שמות יב, ב הערה 548."],["6796","92","<b>שכל הנעלם מכל רעיו\"ן</b>: נסמן לעיל פ' תצוה שמא, ד."],["6797","*94","<b>אגיד\"ה. . להמשיך</b>: ראה גם מאמרי אדה\"ז תק\"ע כאן ע' מה. מאמרי אדה\"א דברים ח\"ג ע' תתנב. נ\"ך ע' תקמז ובהערה 27."],["6798","93","<b>נפלאותי\"ך ומחשבותי\"ך. . אלינו. . אגיד\"ה ואדבר\"ה. . עצמו מספ\"ר</b>: תהלים מ, ו."]]],[2300550257,"בחי' מקור למקור כנ\"ל בענין הוי' בקמ\"ץ שצריך לבא ג\"כ ע\"י צמצום דיו\"ד כו'. וז\"ש לעושה נפלאו\"ת לבדו<sup data-n=\"6799\">94</sup> דוקא דלא ידע להו בר איהו בלחודוהי<sup data-n=\"6800\">95</sup>, להיותן נפלאים ונעלמים בעצמותו והן למעלה מכל ההשתל' דקו וחוט הנ\"ל רק שבאי' ע\"י הצמצום דמקו\"פ כנ\"ל למטה בבחי' העלם, ולכך אמר עצמ\"ו מספ\"ר בבחי' גילוי או\"פ הנק' ספי' ומדה משום דבעצמות אוא\"ס הרי אמרו אנת הוא חד כו' עד ולאו מכל אינון מדו\"ת כלל<sup data-n=\"6801\">96</sup> וכמאמר לפני אח\"ד מה אתה סופ\"ר<sup data-n=\"6802\">97</sup> וזהו עצמו מספ\"ר וד\"ל.\n<b>והנה</b> ע\"ד כל הנ\"ל בבחי' סובב וממלא בכלל, ככה יובן בדרך פרט בכל פרטי הע\"ס דאצי' שנמשכי' מעצמות המאציל בבחי' מקיף ופנימי וכנ\"ל בבחי' התהוות החכמה שיש הוי' בקמץ שהוא בחי' מקיף דחכ' והוי' בפת\"ח כו', כך בכל ספי' יש בחי' מקיפים ופנימי' כו', ובחי' המקיפים דע\"ס נק' ע\"ס בלי מ\"ה<sup data-n=\"6803\">98</sup> בבחי' ההעלם בלי מהות גילוי דבר מה במציאות כו' ונק' ג\"כ ע\"ס הגנוזות<sup data-n=\"6804\">99</sup> כו'. וזהו שאמרו בעשרה לבושי' נתלבש הקב\"ה<sup data-n=\"6805\">100</sup> כו', שהע\"ס נק' בשם לבושים להקב\"ה שהוא עצמות המאציל, והענין הוא כמארז\"ל במקום גדולתו שם אתה מוצא ענוותנותו<sup data-n=\"6806\">101</sup> כו', פי' במקום גדולתו העצמי שהוא בחי' עצמות אוא\"ס המרומם לבדו כנ\"ל בערך ומתנשא לגמרי מהיות גם מקור למקור להשתלשלו' כנ\"ל שם אתה <span data-k=\"pg\">תקעו</span> ּ מוצא בחי' ענוה, שהוא בחי' הצמצום שצמצם אורו העצמי הנק' מקו\"פ כנ\"ל להאיר ולהמשיך בבחי' קו כו' ולבא בהתלבשות באורות הנאצלים שהוא בחי' ירידה גדולה מאד לגבי עצמות אוא\"ס הפשוט כנ\"ל ובחי' ירידה זאת נק' ענותנותו. ועד\"ז כך הוא כל השבחים שמשבחים לעצמו' א\"ס כמו בשם חכים היינו שירד וצמצם א\"ע להיות מקור לחכמה כי בעצמו מובדל בערך כנ\"ל ונק' חכים ולא בחכמה ידיעא<sup data-n=\"6807\">102</sup> כו' וכן במדת החסד ושאר הספי' כמ\"ש לך ה' הגדולה<sup data-n=\"6808\">103</sup> כו' כידוע ומבואר במ\"א. ועד\"מ מנפש בגוף שהנפש בעצמותה מובדלת בערך מכחות פרטיי' כמו רצון ושכל ומדות מחשבה דו\"מ רק שבהן מתלבשת בבחי' לבוש בלבד ואינן נחשבים מעצמותה כלל כו', וכך למעלה בחי' ע\"ס דאצי' נק' לבושי\"ן בלבד לגבי עצמו' אוא\"ס שבהן מתלבש ונגלה להיות נק' חכים ומבין וכה\"ג. וזהו שאמרו בעשרה לבושי\"ן נתלבש הקב\"ה וכמו בחכמה דכתי' ה' בחכמ\"ה כנ\"ל הרי נאמר בה עוטה אור כשלמ\"ה<sup data-n=\"6809\">104</sup> כו' וכן לבוש הבינה כו', וזהו שהע\"ס נק' בשם",[["6799","94","<b>לעושה נפלאו\"ת לבדו</b>: כ\"ה גם בשה\"א ל, ב. תהלים קלו, ד [בדילוג]. עב, יח [ושם: עושה]."],["6800","95","<b>דלא ידע להו בר איהו בלחודוהי</b>: ראה זהר ויקהל רי, ב. (אד\"ר) נשא קכט, ב. קמ, ב. (אד\"ז) האזינו רפח, א."],["6801","96","<b>אנת הוא חד. . כלל</b>: ת\"ז בהקדמה (יז, א-ב)."],["6802","97","<b>לפני אח\"ד מה אתה סופ\"ר</b>: נסמן לעיל פ' תרומה שיב, ד."],["6803","98","<b>ע\"ס בלי מ\"ה</b>: ס\"י פ\"א, מ\"ב."],["6804","99","<b>ע\"ס הגנוזות</b>: נסמן לעיל פ' יתרו רסה, ד."],["6805","100","<b>בעשרה לבושי' נתלבש הקב\"ה</b>: ראה ילקו\"ש ישעי' סס\"א (רמז תקו). מאמרי אדה\"א דברים ח\"ב ע' תרלא. וש\"נ. שה\"א כא, ב הערה 3."],["6806","101","<b>במקום גדולתו. . ענוותנותו</b>: נסמן לעיל פ' יתרו רנט, ב."],["6807","102","<b>חכים ולא בחכמה ידיעה</b>: ת\"ז בהקדמה (יז, ב)."],["6808","103","<b>לך ה' הגדולה</b>: דהי\"א כט, יא. ראה גם מאמרי אדה\"א בראשית ע' תס ואילך ובהנסמן בריש המאמר שם."],["6809","104","<b>עוטה אור כשלמ\"ה</b>: תהלים קד, ב."]]],[2300550287,"מדותי\"ו<sup data-n=\"6810\">105</sup> כמו מד\"ו ב\"ד לשון לבוש<sup data-n=\"6811\">106</sup> וד\"ל (אך בחי' המקיפי' דע\"ס נק' לבושי' להיותן בבחי' ההעלם למעלה מהגבלת אור בכלי כמו בחי' מקי\"ף דחכמה ע\"ז עוטה<sup data-n=\"6812\">*106</sup> אור כשלמ\"ה דוקא וכה\"ג, משא\"כ בחי' או\"פ דחכמה ע\"ז אמר ה' בחכמ\"ה שהוא הוי' בפת\"ח וכמאמר חכמ\"ה מוח\"א<sup data-n=\"6813\">107</sup> אור בכלי, ועד\"ז בכל הספי' ועד\"מ כחות הנפש שנק' לבושין לגבי עצמותה והמה מאירים בבחי' מקיף על כחות המתלבשים בכלי הגוף כו' וד\"ל. וזהו שיש בחי' מקיף ופנימי בפרט בכל ספי' כנ\"ל וד\"ל) (ויש בחי' מקיף בכלל עד\"מ הארה אחת הפשוטה שמאירה מן הנפש בכללות שכוללת ומקפת כל היו\"ד כחות בהשוואה א'<sup data-n=\"6814\">*108</sup> כו' וכמ\"ש במ\"א).\n<b>והנה</b> גם זה ידוע בפי' סובב בכלל הנ\"ל שאין הכוונה שהוא סובב ומקיף מלמעלה<sup data-n=\"6815\">108</sup> בלבד ואינו נמצא למטה כמו למעלה (שהרי אין האור האלקי בבחי' מקום גם בבחי' רוחני' דמקום עד רום המעלות דהיינו לא בבחי' מעלה ומטה), אלא נמצא למטה כמו למעלה ממש שהרי נאמר השמים וארץ אני מלא<sup data-n=\"6816\">109</sup> ואמר בזהר דלית אתר פנוי מיני'<sup data-n=\"6817\">110</sup> כו'. אך הכוונה בפי' סובב שאינו מאיר בתוך כל עלמין בבחי' הגילוי להיות מורגש בהן בהשגה לפי ערך המקבלים ממש בבחי' או\"פ כו', אבל נתפס ומלובש בתוך תוכם בכל פרט ופרט בבחי' ההעלם בלי הרגשת המקבל כמאמר איהו תפיס בכולהו עלמין<sup data-n=\"6818\">111</sup> ממש בדרך פרט כמ\"ש לית את\"ר כו' אבל לית מאן דתפיס בי' כלל כו'. ויובן זה עד\"מ הידוע מהארת הנפש בכחות שלה כמו הארת הנפש בכח החכמה, דמה שמאיר בבחי' גילוי ממש הוא בחי' התהוות מציאות החכמה מאין ליש כנ\"ל בענין הוי' בחכמ\"ה כו', ומה שמאיר בבחי' מקיף והעלם בלבד ואינו בא בגילוי אור חכמה היינו שאינו בא במורגש מציאת חכמה אבל ישנו בהעלם ממש ואדרבה ממנו מקור מוצא גילוי אור דחכמה תמיד מאין ליש והוא הנק' מזלא שהוא הארת הכת\"ר בחכמ\"ה כנ\"ל בענין חבירי דניאל דמזלייה\"ו חזו באריכות. וככה יובן למשכיל למעלה בכללות ענין סובב ומקיף הנ\"ל דמה שמאיר בבחי' <span data-k=\"pg\">1154</span> ּ גילוי אור שהוא בחי' הק\"ו שנמשך בחילוקי מדרגות בבחי' מעלה ומטה זה למטה מזה עד אין שיעור למטה כל זה נק' בחי' ממלא שאינו אלא זיו ואור מצומצם מן העצמות כנ\"ל, וז\"ש מלא כה\"כ זיו יקרי'<sup data-n=\"6819\">112</sup> כו' בכל עולם לפי מדרגתו כו' כידוע משא\"כ בחי'",[["6810","105","<b>שהע\"ס נק' בשם מדותי\"ו</b>: ראה שיעור קומה להרמ\"ק בתחלתו. ס' אלימה עין כל תמר ו פ\"א."],["6811","106","<b>מדותי\"ו כמו מד\"ו ב\"ד לשון לבוש</b>: צו ו, ג. ראה ס' אלימה שם. מאמרי אדה\"א שמות ח\"ב ע' שמב. וש\"נ."],["6812","*106","<b>ע\"ז עוטה</b>: כ\"ה בגוכתי\"ק. ובתו\"ח כאן ע\"ז אמר עוטה."],["6813","107","<b>חכמ\"ה מוח\"א</b>: זהר (רע\"מ) פינחס רלה, ב. ת\"ז בהקדמה (יז, א). ת\"ע (קכג, א)."],["6814","*108","<b>הארה. . מן הנפש. . היו\"ד כחות בהשוואה א'</b>: ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' קכב."],["6815","108","<b>בפי' סובב. . ומקיף מלמעלה</b>: ראה תניא פמ\"ח. מאמרי אדה\"ז תק\"ע כאן ע' מה. מאמרי אדה\"א הנחות תקע\"ז ע' רנז. וש\"נ. שערי אורה פ, א ואילך."],["6816","109","<b>השמים וארץ אני מלא</b>: ירמי' כג, כד [ושם: ואת הארץ — ראה בסמוך על יד הערה 115. שע\"ת יד, ג. וש\"נ. שם צג, ב]."],["6817","110","<b>דלית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז (צא, ב). ת\"ע (קכב, ב). שעה\"י קטז, א הערה 10."],["6818","111","<b>איהו תפיס בכולהו עלמין</b>: נסמן לעיל פ' יתרו רסב, א."],["6819","112","<b>מלא כה\"כ זיו יקרי'</b>: ישעי' ו, ג ובתרגום יונתן שם."]]],[2300550314,"עצמו' אוא\"ס שנק' סובב שמובדל בערך גם מהיות בחי' מקור למקור כנ\"ל אינו בא בבחי' מעלה ומטה אלא מקיף לכללו' ההשתלשלו' בהשוואה אחת<sup data-n=\"6820\">113</sup> כמ\"ש בע\"ח. אמנם אין הכוונה שמקיף מלמעלה בלבד כ\"א אדרבה שורה בתוך תוך כל עולם בפרט כמ\"ש דלית אתר פנוי מיני' כנ\"ל רק דלית מאן דתפיס בי', כמו שאינו בא בחי' אור מקיף דחכמה בגילוי במציאות החכ' רק בהעלם ואמנם הוא עיקר ומקור אל האו\"פ. וז\"ש כי ה' הוא האלקי'<sup data-n=\"6821\">114</sup> דבחי' ממלא מקבל תמיד גם בכל פרט מבחי' סובב, וזהו מ\"ש השמים ואר\"ץ אני מלא ממש רק שהוא בהשוואה א'<sup data-n=\"6822\">115</sup> בשמים וארץ מטעם הנ\"ל וד\"ל.\n<b>ואחר</b> כל הנ\"ל יובן ג\"כ שרש ענין המשכן והכלים והיריעות כו'. דהנה מבואר למעלה בענין כוונת המשכן בכלל שהוא להמשיך לבחי' עצמות אוא\"ס הפשוט שלפני הקו כו' דוקא כמ\"ש ועשו לי מקדש ושכנתי כו' מבחי' עצמותו והוא ע\"י המשכן וכליו דוקא להיות לו דירה בתחתונים בהם ועל ידם, והיינו מטעם המבואר למעלה בענין סובב וממלא בכלל ובפרט בע\"ס דאצי' שבחי' ירידת עצמות אוא\"ס הוא ע\"י התלבשותו בבחי' ע\"ס דאצי' שנק' בחי' כלים ולבושים לגבי עצמותו ית' שבהם ועל ידם מאיר ומתגלה למטה מטה בבחי' מקיפי' ופנימיי' בכל עולם בפרט כנ\"ל באריכות. אך הנה להבין דרך פרט ענין הכלים הארון כו' והיריעות שהמה בחי' או\"פ ואו\"מ בכלל כנ\"ל, הנה תחלה יש להוסיף ביאור בפי' אור א\"ס עצמו שהוא הנק' בחי' סובב הכללי כנ\"ל. דהנה גם בחי' עצמות אוא\"ס הנ\"ל אינו נק' רק בשם אור דא\"ס, דהיינו רק בחי' גילוי הארה וזיו בעלמא בלבד מבחי' עצמותו ומהותו ממש כי בחי' האור הוא רק בחי' גילוי והתפשטות העצם בלבד ואינו נחשב מבחי' העצמות כלל וכלל ונכלל ובטל בעצמות כביטול אור וזיו השמש במאור השמש עצמו כידוע ואור הזה הוא הנק' בשם אין סוף כלומר אין סוף להתפשטותו, אבל על בחי' העצמות ממש לא יתכן לקרות בשם א\"ס<sup data-n=\"6823\">116</sup> כי אין לשון זה דא\"ס נופל כ\"א על בחי' אור המתפשט בלבד (ובזה מתורץ הקושי' הידוע בספרי הקבלה למה נק' אין סוף ולא נקרא אין לו תחלה<sup data-n=\"6824\">117</sup> דאם הי' כינוי שם זה על העצמות שייך להקשות זה, אבל מאחר דקאי רק על בחי' ההתפשטו' אור שאין לו סוף הרי יש לו תחלה מן העצמות כמו דמיון אור המאיר שתחילתו הוא השמש, ומה שאין לו סוף מפני שהוא דומה אל העצם כידוע אין זה הכרח להכריח שאין לו",[["6820","113","<b>סובב. . מקיף. . בהשוואה אחת</b>: ראה גם ש\"א ע' נה."],["6821","114","<b>כי ה' הוא האלקי'</b>: ואתחנן ד, לה. לט. ראה גם לעיל פ' וארא עג, ב. וש\"נ."],["6822","115","<b>השמים ואר\"ץ אני מלא. . בהשוואה א'</b>: ראה גם לעיל פ' בשלח קסו, ג. וש\"נ."],["6823","116","<b>העצמות. . לא יתכן לקרות בשם א\"ס</b>: ראה גם בשם הרה\"מ בפלח הרמון לך מד, סע\"א. הנסמן בלקו\"ב לשעה\"י קעד, ד הערה 10. ד\"ה אדם כי יקריב (הב') לר\"ה יודפס בע\"ה בפלח הרמון לספר ויקרא. וש\"נ."],["6824","117","<b>למה נקרא אין סוף. . תחלה</b>: ראה לקו\"ת פקודי ז, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע רעט ואילך. תקס\"ז ע' כב. תקס\"ח ח\"א ע' שכ. שה\"א לו, א. וש\"נ. לעיל פ' וארא נג, ב. המשך תרס\"ו ע' קסה ואילך."]]],[2300550339,"תחלה כפי הכלל הידוע דכל שאין לו תכלה אין לו תחלה<sup data-n=\"6825\">118</sup> כו', דפי' תחל\"ה זה היינו מפני שקדם לו בחי' העצמות ולא שיש לו תחלה ממש שהרי ידוע דכמו שאור א\"ס למטה עד אין קץ למעלה עד אין שיעור<sup data-n=\"6826\">119</sup> כי אין לו תחלה בעצם מהותו מאחר שדומה אל העצמו' כו' למעלה <span data-k=\"pg\">תקעז</span> ּ מבחי' מעלה ומטה לגמרי כו' וד\"ל).\n<b>וזהו</b> שארז\"ל דעד שלא נברא העולם ונאצל<sup data-n=\"6827\">120</sup> כו' הי' הוא ושמו בלבד<sup data-n=\"6828\">121</sup>, פי' הוא בחי' העצמות ושמ\"ו הוא הנק' אור א\"ס או\"פ המאיר ומתפשט מן העצמות ונק' שמו, עד\"מ שמו של אדם שאינו נחשב מבחי' עצמותו כלל וכלל רק שנתפס ע\"י אותיות שמו לבא לידי התפשטות וגילוי עצמותו כשקוראין לו בשמו, כמו שיענה לקוראו בשמו לגלות פנימי' רצונו ושכלו או להזיזו כולו ממקום למקום וכה\"ג. וככה יובן למשכיל למעלה בבחי' גילוי אור המתפשט שהוא בחי' אותיות שמו העצמי, דהיינו להיות גם בחי' העצמות נתפ\"ס ונמש\"ך על ידו כמו ע\"י קריאת והמשכת שמ\"ו הגדו\"ל הזה בחי' מל' דא\"ס<sup data-n=\"6829\">122</sup> באבי\"ע (כידוע בפי' יהא שמי' רב\"א<sup data-n=\"6830\">123</sup> מברך לעל\"ם כו' וכמו קול דודי כו' מדל\"ג על ההרי\"ם<sup data-n=\"6831\">124</sup> כו' שניזוז ממקום למקום וכה\"ג וד\"ל). ופי' הוא ושמ\"ו בלב\"ד היינו שנכלל בחי' גילוי אור זה בהעצמות כמו שמו של האדם שנכלל בעצמותו כשאין קורא בשמו וקודם ההשתלשלו' לא הי' קורא בשמו כי לא הי' דבר חוץ מן העצמות אין עוד מלבדו<sup data-n=\"6832\">125</sup> רק הוא ושמ\"ו בלב\"ד וכמ\"ש בע\"ח דאוא\"ס זה הי' ממלא כל החלל<sup data-n=\"6833\">126</sup> כו' וד\"ל. והנה הגם שאח\"כ צמצם את בחי' אור זה העצמי ונעשה בחי' מקום פנוי וחלל כו' שהוא בחי' הסתלקות והתכללו' אור זה בעצמו'<sup data-n=\"6834\">127</sup> ממש כמ\"ש ביאור זה במ\"א, ואז נמשך האור רק דרך בחי' קו וחוט כו' להיות בחי' מעלה ומטה<sup data-n=\"6835\">128</sup> כידוע. הנה עכ\"ז גם עכשיו לאחר ההשתלשלו' דקו וחוט כו' הו\"א ושמ\"ו בלב\"ד כמו לפני הצמצום ממש באין שינוי כלל וכלל כמ\"ש אני הוי' לא שנית\"י<sup data-n=\"6836\">129</sup> דקאי על בחי' אוא\"ס הנק' שמ\"ו, דגם הוא אין בו שינוי מקודם הצמצום לאח\"כ וכמו שאו' את\"ה הו\"א משנברא<sup data-n=\"6837\">130</sup> כו', את\"ה היינו בחי' אותיות דאל\"ף עד תי\"ו וה' מוצאות<sup data-n=\"6838\">131</sup> שכוללים שמ\"ו הגדול הנ\"ל בחי' גילוי העצמות, והו\"א היינו בחי' העצמות שזהו כמ\"ש הו\"א ושמ\"ו בלב\"ד באין הפרש מקודם הבריאה לאח\"כ. וכל זה מטעם שכל עיקר מקור ההשתלשלו' דקו אינו רק בחי' הארה דהארה (אחר הצמצום הנק' מקו\"פ ) מעצמות אור א\"ס שנק' שמ\"ו",[["6825","118","<b>דכל שאין לו תכלה אין לו תחלה</b>: ראה חובת הלבבות שער היחוד פ\"ה. המשך תרס\"ו ע' כ."],["6826","119","<b>שאור א\"ס למטה. . למעלה עד אין שיעור</b>: נסמן לעיל פ' תצוה שכג, א."],["6827","120","<b>דעד שלא נברא העולם ונאצל</b>: ראה עבודת הקדש לר\"מ גבאי חלק היחוד פ\"ב."],["6828","121","<b>דעד שלא נברא. . הי' הוא ושמו בלבד</b>: ראה פדר\"א פ\"ג. לעיל פ' וארא נג, ב. וש\"נ."],["6829","122","<b>שמ\"ו הגדו\"ל. . מל' דא\"ס</b>: ראה גם לעיל פ' שמות ה, ג. וש\"נ."],["6830","123","<b>יהא שמי' רב\"א</b>: נוסח הקדיש. ראה גם לעיל פ' בשלח קעח, ד. וש\"נ."],["6831","124","<b>קול דודי. . ההרי\"ם</b>: שה\"ש ב, ח."],["6832","125","<b>אין עוד מלבדו</b>: ואתחנן ד, לה."],["6833","126","<b>דאוא\"ס. . ממלא כל החלל</b>: נסמן לעיל פ' יתרו רסב, א."],["6834","127","<b>צמצם. . והתכללו' אור זה בעצמו'</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תתקכא ואילך. ובהנסמן בריש המאמר שם."],["6835","128","<b>קו וחוט. . מעלה ומטה</b>: ראה גם לעיל פ' תרומה שיז, ג. וש\"נ."],["6836","129","<b>אני הוי' לא שנית\"י</b>: מלאכי ג, ו."],["6837","130","<b>את\"ה הו\"א משנברא</b>: תפלת השחר."],["6838","131","<b>את\"ה. . דאל\"ף עד תי\"ו וה' מוצאות</b>: ראה זהר בראשית טו, ב. (היכלות) פקודי רסא, א. שער היחוד והאמונה פ\"ב."]]],[2300550363,"כמ\"ש באור\"ך נראה או\"ר<sup data-n=\"6839\">132</sup> או\"ר של תולד\"ה<sup data-n=\"6840\">*133</sup> מפני הצמצום כו', ע\"כ אין זה עושה שינוי או מיעוט בעצמות שמ\"ו הגדו\"ל הנק' אוא\"ס עצמו כלל (וגם אם הי' בחי' הארה גמורה מאור זה בקו הנ\"ל אין עושה בו שינוי או מיעוט כלל כמו נר הדלוק שמדליקין ממנו כמה נרות ולא נחסר ונשתנה מאומה כמ\"ש בזהר כהאי בוצינא<sup data-n=\"6841\">133</sup> כו' וכמ\"ש במ\"א).\n<b>והנה</b> צריך נפש האלקי' שבאדם להעמיק היטב בכח חכמתו ובינתו ודעתו באריכות בטוב טעם ודעת להיות קרוב הדבר גם אל השכל האנושי בכל ענין הנ\"ל בבחי' אור א\"ס איך שהוא רק הארה והתפשטות בעלמא לגבי עצמותו ית' ממש, וגם הוא נק' סוב\"ב להקיף לכל ההשתלשלו' בהשוואה א' כנ\"ל בפי' השמים וארץ אני מלא ורק הארה דהארה ממנו שאחר הצמצום נעשה בחי' מקור הראשון לכל ההשתלשלו' דע\"ס מבחי' מקיפי' ופנימי' בד' עולמות אבי\"ע כידוע. וגם <span data-k=\"pg\">1156</span> ּ יתבונן היטב בבחי' הביטול וההתכללות דע\"ס דאצי' שנמשכי' ע\"י הקו בעצמות אוא\"ס כנ\"ל עד\"מ מכחות הנפש שכלולים בה כו' ולגבי העולמות הרי הן בחי' כח אלקי ממש בבחי' א\"ס שהרי אמרו דאיהו וחיוהי ח\"ד כו'. ובכללות יותר יתבונן דגם כל ציור קומת א\"ק שנמשך מראשית הקו עד בחי' עקביי' דא\"ק שמסתיים בסוף העשי'<sup data-n=\"6842\">134</sup> כידוע הרי עליו נאמר לכבודי בראתיו יצרתיו<sup data-n=\"6843\">135</sup> כו', כי כדוגמת אדה\"ר למטה נק' אדם קדמאה<sup data-n=\"6844\">136</sup> למעלה היינו בחי' אדם דבריא\"ה (ובחי' ע\"י וא\"א נק' אד\"ם דיצי' וז\"ש יצרתי\"ו וז\"א נק' אד\"ם דעשי'<sup data-n=\"6845\">137</sup> וז\"ש עשיתי\"ו כמ\"ש במ\"א). וביאור הדבר ידוע שבחי' מחשבה הקדומה כשעלה ברצונו ומחשבתו הפשוטה ונק' רצון קדום שרשה הוא בתחילת הארת הקו כו', ששם אמר צופ\"ה ומביט עד סוף כל הדורות בסקירה א'<sup data-n=\"6846\">138</sup>, פי' בחי' מחשבה כללית מקפת לכל פרטי ההשתלשלו' דע\"ס דאצי' ודבריאה ודיצי' ועשי' כולן נסקרי' בסקירה א' כו' (וכמ\"ש במ\"א בענין גם כל היצור לא נכחד ממך<sup data-n=\"6847\">139</sup> כו' שכל פרט ופרט לא נעדר בשרשו בכלל הכולל הכל שהוא בחי' א\"ק כו'). וגם הוא נק' אד\"ם דבריא\"ה פי' בריאה הוא יש מאין בכל מקום כידוע מטעם הנ\"ל שבחי' אור דקו הוא נק' אור של תולדה אחר ההעלם והצמצום שזהו יש מאין כו' וד\"ל.",[["6839","132","<b>באור\"ך נראה או\"ר</b>: תהלים לו, י. ראה גם לעיל פ' וארא ס, ב ובהערה 24."],["6840","*133","<b>או\"ר של תולד\"ה</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שמט ובהנסמן במראי מקומות לשם. תו\"ח ח\"ש קכח, ג. וישב רה, א. שה\"א קא, א. מאמרי אדה\"א במדבר ח\"ה ע' א'תתמג בשם הפרדס."],["6841","133","<b>כהאי בוצינא</b>: ראה גם לעיל פ' תצוה שכה, ג. וש\"נ."],["6842","134","<b>עקביי' דא\"ק שמסתיים בסוף העשי'</b>: ראה אגה\"ק ס\"כ (קלא, ב). הנסמן במאמרי אדה\"א ויקרא ח\"א ע' טו."],["6843","135","<b>לכבודי בראתיו יצרתיו</b>: ישעי' מג, ז [ושם: ולכבודי — ראה לעיל פ' בשלח קלג, ד. וש\"נ]."],["6844","136","<b>כדוגמת אדה\"ר. . אדם קדמאה</b>: ראה גם תו\"ח ח\"ש קכב, ב. מאמרי אדה\"א ויקרא ח\"א ע' טו. וש\"נ. דברים ח\"ג ע' תתצז. וש\"נ."],["6845","137","<b>אדם קדמאה. . אדם דבריא\"ה. . דיצי'. . דעשי'</b>: ראה גם לעיל פ' בשלח קמה, ג הערה 68."],["6846","138","<b>צופ\"ה ומביט. . בסקירה א'</b>: ראה ברכת זכרונות (מוסף לר\"ה). ר\"ה יח, א. לעיל פ' שמות מח, ב הערה 207."],["6847","139","<b>גם כל היצור לא נכחד ממך</b>: ראה ברכת זכרונות. שעה\"י קיט, ב. קכב, א ובהערה 3."]]],[2300550383,"<b>ועוד</b> יתבונן האדם בפרטות בבחי' היחוד דע\"ס דאצי' זע\"ז וכמאמר אנת הוא דמייחד לון ומקשר לון<sup data-n=\"6848\">140</sup> כו' כמ\"ש בע\"ח דמצד האורות יוכל להיות אור החסד בכלי הגבורה<sup data-n=\"6849\">141</sup> ואור הגבורה בכלי החסד כו' וכיוצא, מפני שהאורות מצד עצמם כלולים בעצמות אוא\"ס. וזהו דמקשר לון ומייחד לון שאמר ב' דברים קשר ויחוד, וההפרש כך הוא דהיחוד אינו אלא כשבאים ב' אורות בהתכללות יחד מצד בחי' התחלפות הכלי מזה לזה כמו אור החסד בכלי הגבורה וכה\"ג, ובזהר נק' זה היחוד לאכללא ימינא בשמאלא ושמאלא בימינא<sup data-n=\"6850\">142</sup> כו' דזהו כללות כל התו\"מ<sup data-n=\"6851\">143</sup> כידוע, ובלשון המקובלים הוא יחוד מ\"ה וב\"ן או מ\"ד ומ\"ן דהגבורות דנוק' נעשו חסדי'<sup data-n=\"6852\">144</sup> וכו' וכיוצא. וכל זה בבחי' נקודי\"ם וברודי\"ם שע\"ס דאצי'<sup data-n=\"6853\">145</sup> הן באין כאו\"א בכלי בפ\"ע עכ\"פ ונק' נקודות זו למעלה מזו אז שייך בהן בחי' היחוד וז\"ש דמייחד לו\"ן כו'. אבל מ\"ש דמקש\"ר לון הוא בבחי' העקודי\"ם שכל הע\"ס היו כלולים זע\"ז וכולם הם כאור א' ממש בכלי א', כי פי' עקודי\"ם שעקודים ומקושרים כולן בכלי אחד<sup data-n=\"6854\">146</sup> כידוע, וזהו דמקשר לון בהתקשרות א' בעצמם וכלי א' לכולן הרי זהו למעלה מבחי' היחוד דלאכללא שמאלא בימינא שבבחי' הנקודים (ובלשון הפרד\"ס<sup data-n=\"6855\">147</sup> נק' העקודים בחי' ע\"ס הגנוזות בעצמות המאציל<sup data-n=\"6856\">148</sup> כמ\"ש במ\"א) (או יתפרש להיפך דהיחו\"ד הוא בעצם מפני הארת הקו דמייח\"ד לון והקש\"ר לקשור האור בכלי היפוכו ויתפרש ב' דברים הללו בין בבחי' נקודי\"ם וברודי\"ם וגם בעקודי\"ם יתפרש ע\"ש בחי' העקודים עצמו כו'). <span data-k=\"pg\">תקעח</span> ּ וכל זה רק מפני בחי' ביטול של הע\"ס מפני הארת הקו שלמעלה מהם עי\"ז מתייחדים לגמרי ומתקשרים כא' בג' מדרגות דעקודי' נקודי' ברודים שהוא בחי' אד\"ם דבריאה ודיצי' ועשי' הנ\"ל ולזה רמז באמרו וכל קומ\"ה לפניך לבד תשתחוו\"ה<sup data-n=\"6857\">149</sup> כו' כמ\"ש במ\"א).\n<b>והנה</b> כאשר יעמיק האדם מאד דעתו והשגתו בהתבוננו' פרטי' הנ\"ל וכיוצא בהן ויתן אל לבו היטב בכל פרטי ההתבוננו' כאלה אזי יתפעל בשכלו שבמוח ובהתפעלות הלב ויבא לבחי' ראי' שכלית בלבו לאסתכלא ביקרא דמלכא<sup data-n=\"6858\">150</sup> כמו בבחי' ראי' חושית ע\"ד שנא' לעתיד ונגלה כבוד הוי'<sup data-n=\"6859\">151</sup> וראו",[["6848","140","<b>אנת הוא דמייחד לון ומקשר לון</b>: ת\"ז בהקדמה (יז, א)."],["6849","141","<b>בע\"ח. . אור החסד בכלי הגבורה</b>: מובא בשם ע\"ח שער מטול\"מ — ראה שעה\"י קלא, א הערה 5. מאמרי אדה\"ז תקס\"ה ח\"א ע' ח. תקס\"ו ע' יב."],["6850","142","<b>לאכללא ימינא בשמאלא ושמאלא בימינא</b>: כ\"ה בכ\"מ. ראה זהר וארא כז, א. תו\"ח בראשית כו, א הערה 3. ולהעיר מברכות נה, ב זקפא דידא דימינא כו'."],["6851","143","<b>לאכללא. . כללות כל התו\"מ</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' כא. וש\"נ."],["6852","144","<b>דהגבורות דנוק' נעשו חסדי'</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תב. תו\"ח וירא קיב, א ובהנסמן להנ\"ל."],["6853","145","<b>וברודי\"ם שע\"ס דאצי'</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"ד. (שער המלכים) שי\"א, פ\"א. מאמרי אדה\"א דברים ח\"ד ע' א'רז. וש\"נ."],["6854","146","<b>עקודי\"ם. . בכלי אחד</b>: ראה גם לעיל פ' וארא נב, ד. וש\"נ."],["6855","147","<b>הפרד\"ס</b>: כ\"ה בכ\"מ. ראה לעיל פ' בא צ, א. וש\"נ."],["6856","148","<b>ע\"ס הגנוזות בעצמות המאציל</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' סד. דר\"מ נח, א. קפב, א. תו\"ח בראשית יז, ד ובהנסמן בהנ\"ל. פלח הרמון וירא סב, ד."],["6857","149","<b>וכל קומ\"ה. . תשתחוו\"ה</b>: ראה גם לעיל פ' בשלח קמו, ב. וש\"נ."],["6858","150","<b>לאסתכלא ביקרא דמלכא</b>: נסמן לעיל פ' תצוה של, ב."],["6859","151","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."]]],[2300550400,"כל בשר כו', עד שירגיש בנפשו בחי' גילוי אור א\"ס המאיר ומתגלה על נפשו האלקי' בשעה זו שמתפעל בנפשו ולבבו מהתבוננות דיחוד אוא\"ס ומבחי' ביטול והתכללות דע\"ס בעצמות המאציל כנ\"ל, וכמ\"ש אם ישים אליו לבו<sup data-n=\"6860\">152</sup> פי' אליו בעצמו דוקא ולא למדותי\"ו<sup data-n=\"6861\">153</sup> שהן ע\"ס כנ\"ל אזי בחי' רוח\"ו ונשמת\"ו של עצמות אוא\"ס אלי\"ו יאסו\"ף בבחי' המשכה וגילוי אור אלקי החופף על נפש\"ו כמ\"ש כבו\"ד ה' יאספ\"ך<sup data-n=\"6862\">154</sup> כו', והוא בחי' אור מקיף להקיף את נפשו בלי יוכל להפרד מאחדותו ית' להיות בבחי' יש ונפרד אפי' רגע כמ\"ש ה' צלך<sup data-n=\"6863\">155</sup> כי אתה ה' מחסי<sup data-n=\"6864\">156</sup> וכה\"ג דהיינו מ\"ש וימינו תחבקני<sup data-n=\"6865\">157</sup> כמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> מ\"ש בס\"י אם רץ לבך שוב<sup data-n=\"6866\">158</sup> כו' שבחי' התפעלות הנפש מהתבוננות דיחוד א\"ס וע\"ס כו' בתשוקה וכלות הנפש בשכלו ולבו כנ\"ל נק' בחי' רצוא לשון מרוצה כשלהבת העולה כו' שהוא התנתקות אור הנפש מן הכלי ליכלל בעצמות אוא\"ס כמ\"ש אם ישי\"ם אלי\"ו לב\"ו כו' וכמו בכל לבי דרשתי\"ך<sup data-n=\"6867\">159</sup> כו' וכיוצא ומה שמאיר ומתגלה על נפשו מלמעלה למטה נק' בחי' שוב<sup data-n=\"6868\">160</sup> כמ\"ש במ\"א באריכות. אך הנה לכאורה יש לחקור בטעם תשוקת הנפש להכלל בעצמות אוא\"ס מאליה בלי טעם כו' (כי ענין ההתבוננות אינו טעם להכריח ההתפעלות רק שהוא בחי' ראי' בלבד ועד\"מ בן המתבונן בנפשו על אביו שהוא מרחוק שמתפעל ומכ\"ש שמתפעל בראייתו אותו ואם לא הי' רואהו לא הי' מתפעל באהבה שאין לומר בהתבוננו' ראי' זו שנק' טעם להתפעלות). אך הענין הוא דנר הוי' נשמת אדם<sup data-n=\"6869\">161</sup> חלק ה' ממש<sup data-n=\"6870\">162</sup> ונק' אד\"ם אדמ\"ה לעליו\"ן<sup data-n=\"6871\">163</sup> כי בצלם אלקים ממש היא וכמ\"ש ויברא ה' אלקי' את האד\"ם בצלמ\"ו<sup data-n=\"6872\">164</sup> כו' וע\"כ ממילא תכלה הנפש האלקי' ליכלל במקור חוצבה להיות בבחי' אד\"ם העליון שלימותא דכולא<sup data-n=\"6873\">165</sup>, והיינו אדמ\"ה לעליו\"ן להיות בדומה לאד\"ם העליון ובפרט ע\"י המשכת גילוי אוא\"ס בנפשו דכמו שהוא למעלה מאיר על נפשו למטה וכמארז\"ל ויקרא לו אל<sup data-n=\"6874\">166</sup> כו' הקב\"ה קרא ליעקב א\"ל<sup data-n=\"6875\">167</sup> כו' אני יחיד בעליונים ואתה יחיד בתחתונים<sup data-n=\"6876\">168</sup> וכה\"ג והיינו מטעם הנ\"ל דבחי' אד\"ם אדמ\"ה לעליו\"ן וד\"ל.",[["6860","152","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["6861","153","<b>אליו. . ולא למדותי\"ו</b>: ראה גם לעיל פ' וארא עז, א. וש\"נ."],["6862","154","<b>כבו\"ד ה' יאספ\"ך</b>: ישעי' נח, ח."],["6863","155","<b>ה' צלך</b>: תהלים קכא, ה."],["6864","156","<b>כי אתה ה' מחסי</b>: תהלים צא, ט."],["6865","157","<b>וימינו תחבקני</b>: שה\"ש ב, ו. ח, ג. ראה גם לעיל פ' וארא סב, ב. תו\"ח נח סא, ד."],["6866","158","<b>בס\"י אם רץ לבך שוב</b>: פ\"א, מ\"ח. הנסמן לעיל פ' בשלח קסד, ג הערה 22."],["6867","159","<b>בכל לבי דרשתי\"ך</b>: תהלים קיט, י."],["6868","160","<b>שמאיר ומתגלה. . שוב</b>: ראה ש\"א פט, ב."],["6869","161","<b>דנר הוי' נשמת אדם</b>: משלי כ, כז."],["6870","162","<b>חלק ה' ממש</b>: האזינו לב, ט. ראה גם מאמרי אדה\"א דברים ח\"ג ע' תשמג. וש\"נ."],["6871","163","<b>אד\"ם אדמ\"ה לעליו\"ן</b>: נסמן לעיל פ' יתרו רסב, א."],["6872","164","<b>ויברא. . האד\"ם בצלמ\"ו</b>: כ\"ה בגוכתי\"ק. בראשית א, כז [בהוספת תיבת ה' — ראה גם שע\"ת קז, ד הערה 16]."],["6873","165","<b>שלימותא דכולא</b>: ראה ת\"ז בהקדמה (יז, ב). עבודת הקדש ח\"א רפ\"ח."],["6874","166","<b>ויקרא לו אל</b>: וישלח לג, כ."],["6875","167","<b>הקב\"ה קרא ליעקב א\"ל</b>: מגילה יח, א."],["6876","168","<b>אני יחיד בעליונים ואתה יחיד בתחתונים</b>: ראה גם תו\"ח נח עה, ג. מאמרי אדה\"א קונטרסים ע' רלד. וש\"נ."]]],[2300550417,"<b>אמנם</b> הנה ידוע מארז\"ל דנתאוה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"6877\">169</sup> דהיינו בבחי' כלים מכלים שונים כמו בתו\"מ המלובשי' בעניני' גשמיי' כו', ולזה אמרו בע\"כ את\"ה ח\"י<sup data-n=\"6878\">170</sup> כו' כי אע\"פ שתכלה הנפש ותשתוקק מאד לצאת מכלי הגוף החומרי ליכלל <span data-k=\"pg\">1158</span> ּ בעצמו' אוא\"ס, אך בע\"כ אתה חי בגוף כדי להמשיך אוא\"ס בתו\"מ בכלים גשמיי' דוקא. והטעם הוא כי אע\"פ שמתגלה ומאיר על נפשו מבחי' אוא\"ס ונק' אדם אדמה לעליון ע\"י ההתפעלות במס\"נ כנ\"ל, מ\"מ הרי הניצוץ אלקי מוסתר ומלובש בחומריות הגוף ולא יוכל אור ה' להאיר כמו שהוא אם לא ע\"י הזדככות החומר לגמרי מכל וכל. אבל בתו\"מ הנה אור ה' מתלבש בבחי' לבוש בלבד ואין הלבוש מסתיר ומכסה על האור כלל אחר שאין לו שייכות וערך עמו כלל כמו שאין הלבוש והבית עושה גרעון בגופו של אדם כו', ואדרבה בבחי' לבושי' גשמיי' דתו\"מ יוכל אור האלקי להתלבש כמו שהוא למעלה ממש כי הרי נמצא למטה כמו למעלה וה\"ז עד\"מ כאדם שתופס למלך ע\"י הלבוש כך אע\"פ דלית מאן דתפיס בי' כנ\"ל, אבל בתו\"מ הוא נתפס ומלובש כו'. ולזאת יתבונן האדם בתפלה שאין בחי' רצוא הנ\"ל עיקר רצון ה' כמ\"ש הסיבי עיניך כו', שהמה הרהיבוני<sup data-n=\"6879\">171</sup> הרחיבוני<sup data-n=\"6880\">172</sup> בעצמות כו' שהוא ביטול העלול לגבי העילה, עד שהכל יוכלל בעצמות אוא\"ס שזהו כמו שהוא קודם ההשתלשלו', ואין זה עיקר הכוונה של עצמות המאציל שנתאווה הקב\"ה להיות לו דירה בתחתונים דוקא שהוא להיפך בחי' ירידת אור האלקי והתלבשותו למטה בבחי' יש ודבר כו'. ע\"כ ישים האדם אל לבו בתפלה שבחי' השוב שהוא בחי' המשכת אוא\"ס למטה הוא עיקר רצון המאציל ולזאת ישים כל תשוקת לבבו אחר בחי' הרצוא, וז\"ש אם רץ לבך שוב כו'. וכמו שאנו אומרים והאר עינינו בתורתיך<sup data-n=\"6881\">173</sup> ודבק לבינו במצותיך, וגם בק\"ש אחר מס\"נ בחי' רצוא באמרו בכל לבבך ובכל נפשך אמר בחי' שוב והיו הדברים האלה<sup data-n=\"6882\">174</sup> כו' ודברת בם<sup data-n=\"6883\">175</sup> כו' שהוא מצות ת\"ת להמשיך אוא\"ס בחכמה כי אורייתא מח\"ע נפקת וראשית התלבשות אוא\"ס הוא בחכמה<sup data-n=\"6884\">176</sup> דוקא כמ\"ש ה' בחכמה כנ\"ל להיות כי החכמה הוא כח מ\"ה<sup data-n=\"6885\">177</sup> בחי' ביטול ואין אוא\"ס שורה רק בבחי' אין כו' כמ\"ש במ\"א וד\"ל. וזהו הוי כל צמא לכו למים<sup data-n=\"6886\">178</sup> צמא בבחי' רצוא הנ\"ל בצמאון ותשוקת הלב ילך אחר התפלה וימשיך אוא\"ס בתורה שנק' מים<sup data-n=\"6887\">179</sup> וכמו מים שמשיבים",[["6877","169","<b>דנתאוה הקב\"ה. . בתחתונים</b>: ראה תניא רפל\"ו. לעיל פ' וארא ע, ג הערה 67."],["6878","170","<b>בע\"כ את\"ה ח\"י</b>: ראה אבות ספ\"ד. תניא ספ\"נ. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שסו. תקע\"א ע' קפא. לקמן תיד, א."],["6879","171","<b>הסיבי עיניך כו' שהמה הרהיבוני</b>: שה\"ש ו, ה [ושם: שהם — ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' צא (נוסחא שני')]."],["6880","172","<b>הרהיבוני הרחיבוני</b>: בסה\"מ תרמ\"ט ע' רנח מציין: כ\"ה בבאוה\"ז פ' אחרי [עז, א ולהצ\"צ ע' שסו]. וראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשפט. מאמרי אדה\"א דברים ח\"ב ע' תלז בהערה."],["6881","173","<b>והאר עינינו בתורתיך</b>: ברכת ק\"ש (שחרית). ראה גם לעיל פ' שמות ז, ג. מאמרי אדה\"א קונטרסים ע' שעה."],["6882","174","<b>והיו הדברים האלה</b>: ואתחנן ו, ו. ראה גם לקמן פ' פקודי תמח, ב. וש\"נ."],["6883","175","<b>ודברת בם</b>: שם ו, ז."],["6884","176","<b>וראשית התלבשות אוא\"ס הוא בחכמה</b>: ראה גם תניא פל\"ה בהג\"ה. לעיל פ' שמות ז, ד. וש\"נ."],["6885","177","<b>החכמה הוא כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["6886","178","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."],["6887","179","<b>בתורה שנק' מים</b>: ב\"ק יז, א. ראה גם מאמרי אדה\"א שמות ח\"א ע' קפב. וש\"נ."]]],[2300550434,"נפש הצמא כך הגילוי אלקות שבתורה משיב ומרווה צמאונה שבתפלה, וע\"כ האומר אין לי אלא תורה<sup data-n=\"6888\">180</sup> בלי צמאון הרי אינו משיב לנפשו אור האלקי בבחי' שוב כלל ע\"כ אפי' תורה אין לו כו' ולהיפך בצמאון שבתפלה בלי תורה ה\"ז כמי שאינו חפץ רק להיות בצמאון וכשמגיע למים אינו שותה שאינו צמאון אמיתי כלל וד\"ל.\n<b>וזהו</b> וכלים מכלים שונים<sup data-n=\"6889\">181</sup> ואז דוקא ויין מלכות רב כיד המלך כו', דלכאורה אין הפשט מובן דהל\"ל להזכיר תחלה שיין מלכות רב ואח\"כ להזכיר רבוי הכלים מכלים כו' ולמה שינה הסדר להזכיר הכלי הטפל תחלה לעיקר שהוא היין שבתוך הכלי כו', ואיך אמר תחלה והשקות בכלי זהב וכלים מכלים שונים ואח\"כ ויין מלכות רב כיד המלך כו'. אך הענין הוא יובן בהקדים תחלה בחי' התוהו והתיקון, דהנה מבואר בע\"ח <span data-k=\"pg\">תקעט</span> ּ דבחי' אורות דתהו הי' האור בריבוי והכלים במיעוט<sup data-n=\"6890\">182</sup> לכן נסתלקו האורות והכלים נפלו למטה לפי שלא יכלו הכלים [להכיל את האור כי רב הוא כו' ומזה הי' סיבת השבירה כידוע, ובחי' התיקון היינו שיהא בחי' ריבוי הכלים<sup data-n=\"6891\">183</sup> ] מכלים שונים ומיעוט האור ועי\"ז דוקא יהי' קיום לאורות שלא יסתלקו מן הכלים, אבל במיעוט הכלי וריבוי האור אין קיום לאור בכלי ומסתלק והכלי נופל ונשבר כו'. וביאור כל זה יובן למעלה באצי' כמו למטה בעבודה שבלב זו תפלה<sup data-n=\"6892\">184</sup> שאם ע\"י בחי' הרצוא הנ\"ל הוא בא אור האלקי בתגבורת אור חזק ורב מאד ואין לו בחי' כלי להתאחז ולהתיישב בו כפי ערכו רק במיעוט בהכרח שיסתלק ויתבטל לגמרי כו', והכלי הוא כלי השגת הנפש המקבל אור האלקי ע\"י בחי' רצוא כנ\"ל שקטן מהכיל האור הגדול הזה כו' וע\"כ ממילא יפול הנופל מיד להיות כלי אור נפשו מתפזרים בפיזור הנפש במדריגות הנמוכות בעניני הבלי העולם כו'. ואמנם אם אחר בחי' רצוא הנ\"ל יעשה ויכין בחי' ריבוי כלים מכלים שונים להכיל האור האלקי המתגלה בנפשו בתוכם להתיישב בהם, דהיינו ע\"י לימוד התורה בשיתא סדרי משנה<sup data-n=\"6893\">185</sup> שהן ריבוי כלים מכלים שונים להתלבש בהן בחי' גילוי אוא\"ס כו' אזי יש קיום נצחי להאור האלקי בנפשו בלי יסתלק",[["6888","180","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["6889","181","<b>וכלים מכלים שונים</b>: נסמן לקמן הערה 195."],["6890","182","<b>אורות דתהו. . והכלים במיעוט</b>: ראה ע\"ח שער הכללים פ\"א. (שער שביה\"כ) ש\"ט, פ\"ו. מאמרי אדה\"א דברים ח\"ד ע' א'תעו. וש\"נ. לעיל פ' בשלח רמה, ב."],["6891","183","<b>ובחי' התיקון. . ריבוי הכלים</b>: ראה גם מאמרי אדה\"א דברים שם. וש\"נ. שעה\"י קלא, א ובהערה 4."],["6892","184","<b>בעבודה שבלב זו תפלה</b>: ראה תענית ב, א. לעיל פ' בשלח קסב, א הערה 13."],["6893","185","<b>בשיתא סדרי משנה</b>: ראה במדב\"ר פי\"ב, יז. פי\"ג, טוטז. לעיל פ' שמות ג, א. וש\"נ."]]],[2300550450,"כל היום. ולזה עיקר מצות ת\"ת לעשות בחי' כלים רבים להשראת גילוי אוא\"ס בחכ' ובזאת תתקיים אור האלקי בנפשו, וכמו\"כ ע\"י מצות מעשיות שנק' רמ\"ח אברים דמלכא<sup data-n=\"6894\">186</sup> כידוע וזהו הנק' בחי' התיקון למעלה בריבוי הכלים כו', וזהו וירא אלקי' את האור כי טו\"ב ואמרו כי טוב לגנו\"ז דהיינו לגנוז האור בכלי<sup data-n=\"6895\">187</sup> דוק\"א בכדי שיתקיים מטעם הנ\"ל וד\"ל.\n<b>ויובן</b> זה בתוס' ביאור עד\"מ חבית המלאה ביותר שכאשר פותחין הנקב שבה יוצא בתגבורת השפע ביותר ואז בכדי שלא יושפך על הארץ מפני ריבוי השפע בקילוח חזק מאד ממהרין להביא כלים רבים בכדי להפסיק הקילוח שלא יקלח בבת אחת בתגבורת חזק אלא יתחלק לכמה כלים מכלים שונים ובזה לא יושפך ויאבד אפי' טפה א' כו'. וכך יובן עד\"מ מבחי' תגבורת אורות דתהו שלא יכילם הכלים עיקר בחי' התיקון שלא יפלו מהם ניצוצות למטה בנוג\"ה כו' ע\"י בחי' ריבוי הכלים מכלים שונים שנעשים ע\"י שם מ\"ה דתיקו\"ן וכמ\"ש במ\"א שז\"ש אשר ברא אלקי' לעשו\"ת<sup data-n=\"6896\">189</sup> לתק\"ן<sup data-n=\"6897\">188</sup> כו' וד\"ל. ולמטה היינו בחי' התלבשות אוא\"ס בריבוי כלים מכלים שונים כמו בשיתא סדרי משנה ששרשן למעלה המה בחי' ריבוי הכלים למדות עליונות סדר מועד הוא בחי' כלי החסד<sup data-n=\"6898\">190</sup> דזו\"נ כו', והמה מתחלקי' לס' מסכתות<sup data-n=\"6899\">191</sup>, שנק' ס' מלכות<sup data-n=\"6900\">192</sup> וברייתות נק' שמונים פלגשים<sup data-n=\"6901\">193</sup> וההלכות נק' עלמות שאין להם מספר<sup data-n=\"6902\">194</sup> כמ\"ש במ\"א, וה\"ז עד\"מ כנתינת ריבוי הכלים תחת קילוח החבית המלאה כו' וד\"ל. וזהו מ\"ש והשקות בכלי זהב<sup data-n=\"6903\">195</sup> וכלים מכלים שונים ואז ויין מלכות רב כו', פי' לאחר בחי' תיקון ריבוי הכלים מכלים שוני\"ם דוקא אז יש קיום לאור הרב ג\"כ כנ\"ל, כי מתחלק בחלקי' רבים כו' ואז דוקא יי\"ן מלכו\"ת רב שנמשך ונשפע ריבוי אור ושפע בלי גבול כלל כיד המלך ולא ילך לאיבוד חוצה כלל. והענין למעלה שרש היין בחי' בינ\"ה<sup data-n=\"6904\">196</sup> שהוא <span data-k=\"pg\">1160</span> ּ עלמא דאתכסיא<sup data-n=\"6905\">197</sup> כי יי\"ן בגימ' סו\"ד<sup data-n=\"6906\">198</sup> ולזה נכנס יי\"ן יצא סו\"ד<sup data-n=\"6907\">199</sup> מן ההעלם לגילוי הוא בבחי' אורות דתהו שהוא בבחי' ס\"ג דבינה<sup data-n=\"6908\">201</sup> דנקודי' ששם הי' השבירה<sup data-n=\"6909\">200</sup> בכלים<sup data-n=\"6910\">202</sup> כידוע. וז\"ש ויי\"ן מלכו\"ת ר\"ב בבחי' ריבוי אור כיד המלך פי' המל\"ך סתם הוא בחי' מלך מלכי המלכים<sup data-n=\"6911\">203</sup>",[["6894","186","<b>מצות. . רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["6895","187","<b>כי טוב לגנו\"ז. . האור בכלי</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' רלט. הנחות תקע\"ז ע' שסו. תו\"ח נח עג, ד הערה 23."],["6896","189","<b>לעשו\"ת לתק\"ן</b>: נסמן לעיל פ' יתרו רסו, ג."],["6897","188","<b>אשר ברא אלקי' לעשו\"ת לתק\"ן</b>: בראשית ב, ג. ראה ד\"ה זה במאמרי אדה\"ז תקס\"ב ח\"ב ע' תפ וע' תפג. בהערה הבאה."],["6898","190","<b>סדר מועד. . החסד</b>: במאמרי אדה\"ז תקס\"ה ח\"ב ע' תרמז ומאמרי אדה\"א במדבר ח\"ב ע' תתכד: (סדר) מועד חסד שבגבורה. אבל במאמרי אדה\"ז על מארז\"ל ע' תנא [מקביל למאמרי אדה\"ז הנ\"ל]: ומועד בחי' גבו' שבחס'. וראה גם לקמן תלט, ד."],["6899","191","<b>לס' מסכתות</b>: ראה גם לעיל פ' שמות ג, א. וש\"נ."],["6900","192","<b>ס' מלכות</b>: שה\"ש ו, ח."],["6901","193","<b>וברייתות נק' שמונים פלגשים</b>: שה\"ש שם. ראה גם לעיל פ' שמות ט, ב. וש\"נ."],["6902","194","<b>וההלכות נק' עלמות שאין להם מספר</b>: ראה שה\"ש שם. זהר (רע\"מ) פינחס רטז, א. לעיל פ' שמות ט, ב. מאמרי אדה\"ז תקס\"ח ח\"ב ס\"ע תריט ואילך. תק\"ע ע' ז (ובהנסמן לריש המאמר שם). ע' יח ואילך (ובהנסמן לריש המאמר שם). מאמרי אדה\"א נ\"ך ע' תב. וש\"נ."],["6903","195","<b>והשקות בכלי זהב</b>: אסתר א, ז."],["6904","196","<b>היין בחי' בינ\"ה</b>: ראה זהר נשא קכז, א. מאמרי אדה\"א ויקרא ח\"א ע' לג. וש\"נ. בראשית ע' תקעא."],["6905","197","<b>בינ\"ה שהוא עלמא דאתכסיא</b>: ראה זהר ויצא קנח, א. לעיל פ' בשלח קלה, ג הערה 141."],["6906","198","<b>יי\"ן בגימ' סו\"ד</b>: ראה ערובין סה, סע\"א."],["6907","199","<b>נכנס יי\"ן יצא סו\"ד</b>: ערובין שם. ראה גם תו\"ח ויחי רלו, ב."],["6908","201","<b>ס\"ג דבינה</b>: ראה לעיל פ' וארא פד, ד הערה 806 והערה 810."],["6909","200","<b>דתהו. . ששם הי' השבירה</b>: ראה ע\"ח (שער דרושי נקודות) ש\"ח, פ\"א. תו\"ח נח סד, ב הערה 10."],["6910","202","<b>השבירה בכלים</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתפא. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. לעיל פ' בשלח רמה, ב."],["6911","203","<b>מלך מלכי המלכים</b>: ברכות כח, ב. ועוד."]]],[2300550465,"כו' שהוא עצמות המאציל וי\"ד המלך הוא י\"ד החזק\"ה<sup data-n=\"6912\">204</sup> מבחי' גבורה דע\"י שהן בחי' ה\"ג דבוצינא קרדוניתא<sup data-n=\"6913\">205</sup> כו' ולא יכלו הכלים להכיל, אך ע\"י שם מ\"ה החד\"ש דא\"ק<sup data-n=\"6914\">206</sup> נעשה בחי' ריבוי הכלים להכיל האור החזק הזה. וז\"ש והשקו\"ת בכל\"י זה\"ב דוקא וכמ\"ש ושם אשת\"ו מהיטבא\"ל בת מטר\"ד בת מ\"י זה\"ב שהוא בחי' כל\"י מ\"ה דתיקו\"ן שנק' הד\"ר<sup data-n=\"6915\">207</sup> כו' ועל ידו נעשה ריבוי הכלים דוקא, וזהו וכלי\"ם מכלי\"ם שוני\"ם ואז ויי\"ן מלכו\"ת דאימ\"א ר\"ב לבא בריבוי ההתחלקות למקבלים כמו שהוא למעלה וזהו כי\"ד המל\"ך וד\"ל (ובזה יובן בטוב טעם יותר מ\"ש האומר אין לי אלא תור\"ה דהיינו רק עד\"מ נתינת הכלים תחת קילוח החבית כנ\"ל דאפי' תורה אין לו שהרי לא נשפך בהם מאומה כשאין לו בחי' גילוי אוא\"ס ע\"י התפלה בבחי' רצוא כו' וד\"ל).\n<b>וזהו</b> ענין המשכן והכלים והיריעות, שהן ג' מדרגות כלים שהמה הארון ושולחן וכה\"ג והיריעות והקרשים וכלל המשכן שהוא מקיף וסובב לכל ליריעות ולכלים שתחתם. וביאור כל זה הנה מבואר למעלה בענין הכלים הארון וכפורת ושולחן ומנורה כו', שהן בחי' כלים לע\"ס דאצי' הארון הוא בחי' כלי החכמה והשולחן ומנורה בחי' חו\"ג (ומזבח הזהב בדע\"ת או בת\"ת<sup data-n=\"6916\">208</sup> כו') וכיוצא בזה בשאר הכלים, ובחי' היריעות הן הנה בחי' אורות מקיפי' דע\"ס הנ\"ל כמ\"ש למעלה באריכות שיש לכל ספי' וספי' בחי' או\"פ ובחי' או\"מ בפרט. ובזה יובן הטעם מה שנצטוה משה לעשות הכלים והיריעות כולן בבחי' מדה ושיעור דוקא כמו הארון אמתיים וחצי ארכו<sup data-n=\"6917\">209</sup> ואמה וחצי רחבו ואמה וחצי קומתו, והכפורת ג\"כ אמתיים וחצי ארכו<sup data-n=\"6918\">210</sup> כו', והשולחן אמתיים ארכו ואמה רחבו ואמה וחצי קומתו<sup data-n=\"6919\">211</sup>, והמנורה בציורה<sup data-n=\"6920\">212</sup> מדוקדקת בכל פרטי' וגם גביעיה וקנותיה במספר דוקא וכן נרותי' שבעה דוקא, וכן מזבח הזהב אמה ארכו ואמה רחבו ואמתיים קומתו<sup data-n=\"6921\">213</sup>, ומזבח החיצון ה' אמות אורך וה' אמות רוחב וג' אמות קומתו<sup data-n=\"6922\">214</sup> כו', הרי נזכר אורך ורוחב וקומה שהוא גדרי השטח במדה קצובה בכל הכלים. והיינו לפי שכל בחי' הכלים הללו הן הנקראי' בחי' כלים מקבלי\"ם לאורות דע\"ס דאצי' למעלה וכל בחי' מקבל אור מגביל האור בתוכו, וע\"כ צריך להיות גדרי הכלי באורך ורוחב וקומה לפי המדה דוקא ולא יוסיף ולא יגרע אפי' כמלא נימא כו'. וכמו\"כ בחי' היריעות הן הנה בחי' כלים פשוטים ולא מקבלי', והיינו להיותן בחי' כלים לאורו' המקיפי' דע\"ס דאצי' למעלה ע\"כ גם המה באין במדה",[["6912","204","<b>יד החזק\"ה</b>: בא יג, ט."],["6913","205","<b>גבורה דע\"י. . ה\"ג דבוצינא קרדוניתא</b>: ראה שער היחוה\"א ספ\"ד. וראה גם בליקוט פי' וכו' שם."],["6914","206","<b>שם מה החד\"ש דא\"ק</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"ב ואילך."],["6915","207","<b>ושם אשת\"ו מהיטבא\"ל. . זה\"ב. . הד\"ר</b>: וישלח לו, לט. ראה ע\"ח (שער שביה\"כ) ש\"ט, פ\"ח. (שער התיקון) ש\"י, פ\"ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתפא. מאמרי אדה\"א ויקרא ח\"ב ע' תרס."],["6916","208","<b>ומזבח הזהב. . בת\"ת</b>: ראה ע\"ח (שער ציור עולמות) שמ\"ג, פ\"א. מאמרי אדה\"ז תקס\"ד ס\"ע סט. לעיל פ' משפטים שז, ג. לקמן תיב, ב. תכ, ג. תלד, א. תמ, א."],["6917","209","<b>הארון אמתיים וחצי ארכו</b>: תרומה כה, י."],["6918","210","<b>והכפורת. . וחצי ארכו</b>: תרומה שם, יז."],["6919","211","<b>והשולחן. . ואמה וחצי קומתו</b>: שם כה, כג."],["6920","212","<b>והמנורה בציורה</b>: תרומה שם, לא ואילך."],["6921","213","<b>מזבח הזהב. . ואמתיים קומתו</b>: תצוה ל, ב."],["6922","214","<b>ומזבח החיצון. . וג' אמות קומתו</b>: תרומה כז, א."]]],[2300550480,"ושיעור דוקא כמ\"ש אורך היריעה הא'<sup data-n=\"6923\">215</sup> כ\"ח באמה ורוחב ד' באמה, כי בבחי' כלים פשוטי' אין בהם רק בחי' אורך ורוחב בלבד כי אין בהם בחי' תוך לקבלה כלל כו', להיות כי בחי' אור המקיף הוא אור פשוט בלתי מתקבל ונקבל<sup data-n=\"6924\">*216</sup> רק הארתו מתפשטת מלמעלה. ואמנם גם לו יש שיעור להתפשטותו ע\"כ יש שיעור ג\"כ לכלים שלהם שהן היריעות, שאם לא יהיו לפי המדה הצריכה באורך או יותר או פחות לא ישכון בהם בחי' אורות המקיפי' <span data-k=\"pg\">תקפ</span> ּ כלל וכן אם יפחות ברוחב או יוסיף, כי כך עלה ברצון עצמות המאציל ליתן שיעור ומדה כזאת דוקא למקיפי' ע\"פ מאמר קו המדה שמודד לכל האורות וכלים מקיפי' ופנימי' כידוע ומבואר בזוהר בענין משחתא<sup data-n=\"6925\">216</sup> כו' (וכמ\"ש במ\"א באריכות), וע\"כ גם במספר יש קצבה להיות עשר יריעות עשר ולא תשע כו', וכמו\"כ בכלים דמשכן ע\"פ מאמר קו המדה ניתן שיעור ומדה ומספר קצוב מטעם זה וד\"ל (והקרשים הן ג\"כ בחי' מקיפי' אלא שהן נמשכי' ויורדי' מלמעלה למטה, ולמעלה הוא הנק' שיורי אור מקיפי' שמהן נעשה בחי' היכלות<sup data-n=\"6926\">217</sup> כו', ויש להן מדה ג\"כ כמ\"ש אורך הקרש האחד יו\"ד אמות<sup data-n=\"6927\">218</sup> דוקא כי כל ספי' נחלק ליו\"ד כו'). ומדריגה השלישית שלמעלה מבחי' הכלים והיריעות הנה הוא בחי' עצמות אוא\"ס שלמעלה מבחי' הקו והחוט (המודד לכל האו\"מ ופנימי' כו') אלא הוא אוא\"ס פשוט בלתי מוגבל במקיף ופנימי ונק' בחי' מקיף הכללי שמקיף לכל ההשתלשלו' דקו וחוט במקיפי' ופנימי' בהשוואה א' ממש, והיינו למטה בחי' גילוי שכינה במשכן דרך כלל לסבב ולהקיף על היריעות והכלים שבתוכם בהקפה כללית בהשוואה א' מבלי הפרש כלל בין מקיף לפנימי ולמעלה נק' סובב כ\"ע בהשווא' א' כידוע וע\"ז אמר ועשו לי מקדש ושכנתי בתוכם, דקאי על כלל המשכן כאשר כבר הוקם ביריעות וכלים כו' וד\"ל.\n<b>ועם</b> כל הנ\"ל יובן ג\"כ שרש ענין הטעם במה שבפ' תרומה תצוה נצטווה משה תחלה על מעשה המשכן וכליו ואח\"כ בפ' כי תשא אחר שאמר ראה קראתי בשם בצלאל כו' ועשו כל אשר צויתיך<sup data-n=\"6928\">219</sup> את אהל מועד ואת הארון<sup data-n=\"6929\">220</sup> כו' אח\"כ מיד נצטוה על מצות השבת דהא סמוך לי' מיד אמר אך את שבתותי תשמורו כו'. דהנה מבואר למעלה בעיקר ענין כוונת המאציל בהמשכת הקו בבחי' או\"מ ופנימי כו' להיות בחי' ירידת והמשכת עצמות א\"ס הפשוט מאיר ונתפס ומלובש למטה מטה בעולמות, שזהו בחי' ירידה מעצמותו דוקא מפני שנתאוה הקב\"ה להיות לו דירה בתחתונים דוקא ולזה הי' הכוונה ג\"כ בכל עשיית המשכן",[["6923","215","<b>אורך היריעה הא'</b>: תרומה כו, ב."],["6924","*216","<b>ונקבל</b>: אוצ\"ל: ונגבל."],["6925","216","<b>בזוהר בענין משחתא</b>: ראה זהר בראשית יח, ב. פקודי רלג, א. ביאה\"ז פקודי נז, ב."],["6926","217","<b>שיורי אור מקיפי'. . היכלות</b>: מובא בשם הע\"ח בביאוה\"ז פקודי נח, ג. סידור שער התפילה כא, סע\"א. מאמרי אדה\"א במדבר ח\"ג ע' תתקצז. וש\"נ."],["6927","218","<b>אורך הקרש האחד יו\"ד אמות</b>: תרומה כו, טז. ויקהל לו, כא [ושם: עשר אמות אורך הקרש. . האחד]."],["6928","219","<b>ועשו כל אשר צויתיך</b>: תשא לא, ו [בהשמטת תיבת את — ראה לעיל בפנים על יד הערה 12]."],["6929","220","<b>את אהל מועד ואת הארון</b>: תשא שם, ז."]]],[2300550495,"בכלים ויריעות שהמה לנגד ע\"ס מקיפי' ופנימיי' כנ\"ל, להיות בחי' גילוי הארת והמשכת סובב כ\"ע הנ\"ל למטה בכלל מלמעלה למטה בהשראה במקיפי' ופנימי' דיריעות וכלים כמ\"ש ושכנת\"י בתוכ\"ם כו' וכנ\"ל. אך הנה שרש בחי' השבת הוא להיפך מזה ממש כי שרש בחי' השבת הוא דוקא בחי' העלאת האור מלמטה למעלה דוקא היפך בחי' הירידה וההמשכה מלמעלה למטה (והוא הנק' בחי' אור חוזר מלמטה למעלה בחי' עליות העולמות) כמשי\"ת בסמוך. ולזה הטעם אחר שנצטווה על מעשה המשכן שהוא בחי' הירידה וההמשכה מלמעלה למטה מיד נצטווה על בחי' ההעלא' מלמטה למעלה שהוא מצות השבת ולכך מיד אחר מצות המשכן סמיך לי' פ' מצות השבת אך את שבתותי תשמורו כו' כנ\"ל.\n<b>ולהבין</b> כל זה בתוס' ביאור יש להקדים הטעם למה בחי' השבת הוא בחי' ההעלאה מלמטה למעלה דוקא <span data-k=\"pg\">1162</span> ּ בבחי' אור חוזר כו'. דהנה מבואר במ\"א באריכות ע\"פ ששת ימים עשה ה'<sup data-n=\"6930\">221</sup> כו' וביום הז' שבת וינפש כו', בענין בחי' השביתה ממלאכה למעלה באלקות דודאי אין לו גוף ולא דמות הגוף<sup data-n=\"6931\">222</sup> רק שדברה תורה בלשון בנ\"א<sup data-n=\"6932\">223</sup>, אך הענין הוא עד\"מ ממלאכה שאדם התחתון עושה שהוא בחי' ירידת כחות נפשו והתפשטותם למטה במלאכה שהוא עושה, אם מלאכת מחשבת או מלאכה גשמי' כמו מלאכת מחשבת שכל וחכמה להתחכם באיזה ציור מלאכה או בכתיבה וכה\"ג שזהו ירידת וצמצום כח השכל עצמו מכמו שהוא בכלי המוח שהוא שם בבחי' אור שכל רוחני ובחשבו בשכלו באופן איזה ציור מלאכה הרי מתלבש השכל הרוחני בעשי' גשמית (מלבד שגם אותו השכל שמתחכם איך לעשות גם הוא ירד מאור וכח השכל עצמו כמו קודם שהתחכם, כי התחכמות זו נק' שכל שבעשי' ואין לו לדמות לעצם כח השכל הרוחני, וגם להשיב לשואלו דבר חכמה באיזה חכמה שתהי' היא בחי' ירידה מעצמות כח חכמתו כו' וכמ\"ש במ\"א). וא\"כ הרי מיד ששובת ונח בשכלו מלהתחכם בציור אופן המלאכה ה\"ז בחי' אור חוזר שחוזר בחי' אור התחכמות זאת שמלובשת בעשי' זו אל מקורה העצמי שהוא כח החכמה שבנפשו ונכללת שם ממש, ועד\"ז בשאר הכחות כמו כח התפשטות הפועל בידיו בפעולה ומלאכה גשמי' מיד ששובת ונח ממלאכתו חוזר אור וכח זה המלובש בפעולה אל עצם כח הפועל שביד כו', ועד\"ז כל פרטי הכחות שבנפש חוזרי' המה לעצמותם בגמר מלאכה. וגם בחי' התענוג של הנפש המלובש ברצון בשעה שעושה במלאכתו אם מלאכת מחשבת או שאר",[["6930","221","<b>ששת ימים עשה ה'</b>: תשא לא, יז. ראה סידור ענייני סעודת שבת קעד, א. מאמרי אדה\"א שמות כאן ע' תרסה. וש\"נ."],["6931","222","<b>אין לו גוף ולא דמות הגוף</b>: ע\"פ פיוט יגדל."],["6932","223","<b>שדברה תורה בלשון בנ\"א</b>: ברכות לא, ב. ראה תו\"ח וירא צח, ב."]]],[2300550509,"מלאכה ג\"כ חוזר אל עצם כח התענוג שבנפשו בגמר המלאכה דוקא, כי הרי התענוג הזה הי' מצומצם ונעלם כל זמן עסקו במלאכה ברצון ושכל ומעשה המלאכה עד שנגמרה המלאכה אז גם התענוג חוזר אל מקור חוצבו שהוא עצמות כח התענוג ההיולי (כי כמו שהתחכמות החכמה בחי' התפשטות הארה בלבד מן עצם כח השכל, כך התפשטות התענוג בדבר פרטי אינו אלא התפשטות אור בעלמא בעצם כח התענוג). וזה התענוג העולה בבחי' אור חוזר בגמר המלאכה הוא מלבד אותו התענוג שמקבל מחמת טוב המלאכה כשנגמרה כפי מחשבתו ורצונו ונשלמה כפי כוונתו דוקא שהוא בא לאחר שלימות המלאכה שלא הי' עדיין זה התענוג קודם התחלתו במלאכה כי לא ידע אז אם תושלם כרצונו, ונמצא הוא תענוג חדש אמנם הוא בחי' שלימות אור אותו התענוג הראשון שבו התחיל כו', והיינו דמיון להבין ענין נעוץ תחלתן בסופן<sup data-n=\"6933\">224</sup> כו'.\n<b>ובכ\"ז</b> יובן למעלה במ\"ש ששת ימי\"ם עשה ה' כו', פי' הוא בחי' וי\"ו יומין עילאין<sup data-n=\"6934\">225</sup> דאצי' שהן בחי' המדות דאצי' שבתוכם מלובש בחי' חו\"ב דאצי' עד\"מ הנ\"ל מירידת שכל האדם במדותיו לעשות מלאכת מחשבת או מלאכה גשמי' כו', וכל יום יש לו המשכה מיוחדת מבחי' המוחין העליונים דאו\"א כו' וביום הא' בחי' החסד <span data-k=\"pg\">תקפא</span> ּ דז\"א וביום הב' בחי' גבורה כו' כידוע שהן הנק' ששת ימי בראשית למעלה שמתחדש בכל יום מאין ליש מאצי' לבי\"ע כמ\"ש כי אלף שנה<sup data-n=\"6935\">226</sup> כיום אתמול<sup data-n=\"6936\">227</sup> כו' כמ\"ש במ\"א. ובבחי' גמר מלאכת ה' מבחי' המדות דאצי' ביום הו' שהוא בחי' יסוד כו' אז נאמר ויכולו השמים והארץ כו' וישבות<sup data-n=\"6937\">228</sup> כו' כאדם ששובת ונח ממלאכתו כנ\"ל, כך חוזרים כל בחי' אורות וכחות האלקי' שמתפשטי' בעולמות מאין ליש אל בחי' עצמות אור א\"ס שבחו\"ב ומדות דאצי' דהא אמרו דאיהו וחיוה\"י ח\"ד כו', וז\"ש כי בו שב\"ת וינפ\"ש<sup data-n=\"6938\">229</sup> בבחי' אור חוזר אל העצמות ממש, ולזה אמרו דבראשי\"ת נמי מאמ\"ר הו\"א<sup data-n=\"6939\">230</sup> כו' לפי שגם בחי' ירידת אור החכמה שנק' בראשי\"ת<sup data-n=\"6940\">231</sup> כידוע בוי\"ו יומין המתלבשים להמשיך שפע מאין ליש בבי\"ע חוזר אל עצמות אור החכמה שבעצמות אוא\"ס כו' וד\"ל. וגם בחי' התפשטות הארת אור העונג הפשוט שבעצמות אוא\"ס הפשוט (שנק' שעשועי המלך בעצמותו<sup data-n=\"6941\">232</sup> כו') חוזר אל העצמות התענוג מירידתו והתלבשותו ברצון להאציל ולברוא כו' באמצעות בחי' חו\"ב ומדות דאצי' כו' כמובן מתוך משל הנ\"ל, וזהו מלבד אותו אור שלימות התענוג שנשלם דוקא בגמר המלאכה דו' יומין דחול כמ\"ש וירא אלקי' את כל אשר עשה והנה טוב מאד<sup data-n=\"6942\">233</sup>",[["6933","224","<b>נעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["6934","225","<b>ששת ימי\"ם. . וי\"ו יומין עילאין</b>: תשא לא, יז. זהר ויחי רמז, א. אמור צד, רע\"ב. מאמרי אדה\"א דברים ח\"א ע' רז. וש\"נ."],["6935","226","<b>כי אלף שנה</b>: תהלים צ, ד [ושם: שנים בעיניך — אבל כ\"ה בגוכתי\"ק. לעיל פ' וארא נג, סע\"ב. לקמן (תיז, ג) תכה, ד. שה\"א ס, ב. שעה\"י קמד, א. מאמרי אדה\"א נ\"ך ע' שצח. וש\"נ]."],["6936","227","<b>כי אלף שנה כיום אתמול</b>: ראה מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ. ח\"ג ע' תתה. וש\"נ."],["6937","228","<b>ויכולו השמים. . וישבות</b>: בראשית ב, א. ב."],["6938","229","<b>כי בו שב\"ת וינפ\"ש</b>: חיבור שני כתובים בראשית ב, ג. תשא לא, יז. ראה גם הנסמן לעיל פ' בשלח רט, ד הערה 12."],["6939","230","<b>דבראשי\"ת נמי מאמ\"ר הו\"א</b>: בראשית א, א. ר\"ה לב, א."],["6940","231","<b>החכמה שנק' בראשי\"ת</b>: ראה תרגום ירושלמי לבראשית א, א. מאמרי אדה\"א בראשית ע' א. וש\"נ."],["6941","232","<b>שעשועי המלך בעצמותו</b>: נסמן לעיל פ' תרומה שיח, ב."],["6942","233","<b>וירא. . והנה טוב מאד</b>: בראשית א, לא."]]],[2300550523,"שהוטב בעיניו תשלום המלאכה שהיא כפי שעלה ברצונו הפשוט וכפי כוונתו בפנימי' הרצון והתענוג כו' כמובן ממשל קבלת התענוג מגמר המלאכה באדם למטה כנ\"ל וד\"ל.\n<b>אך</b> הנה גם בחי' שלימות אור התענוג מגמר המלאכה שמשלים לאור העונג שעלה בתחלה כשהתחיל במלאכה כו' מפני שנעוץ תחלתן בסופן דוקא כנ\"ל, הנה גם הוא אינו אלא בחי' הארה פרטית בלבד העולה מפרט אותה המלאכה כשהוטבה בעיניו במה שגמרה כפי רצונו כו', אך לאחר שכבר הוטבה בעיניו מאד הרי הוא בכל עצמותו ממש בשעשועי' גדולים דהיינו בבחי' עצם התענוג הפשוט שבנפשו כו', הרי עלה בחי' התענוג הפרטי הזה שמשלימות הפעולה בעצמות התענוג הפשוט כו'. וכך למעלה בחי' התענוג העליון שמשלימות הבירורים דוי\"ו יומין דחול ע\"י ירידת הו\"ק עם בחי' המוחין דאו\"א כנ\"ל, אחר שחוזרין אל עצמותם כנ\"ל גם הוא עולה בתענוג הפשוט שבעצמות אוא\"ס שהרי כל עצמות אוא\"ס משתעשע בבחי' שעשועים עצמיי' מזה התענוג העולה בבחי' או\"ח, וז\"ש והנה טוב מאד טוב הוא בחי' עונג הפרטי משלימות הבירורי' דוי\"ו יומין שנשלמו בתכלית כפי הרצון הקדום ומאד הוא עצמות התענוג כו'. וז\"ש אז תתענג על הוי'<sup data-n=\"6943\">234</sup> כי שם הוי' ידוע דיו\"ד בחכמה וקוצו של יו\"ד בכת\"ר<sup data-n=\"6944\">235</sup> כו' והתענוג שבחכמ\"ה נק' בחי' עד\"ן<sup data-n=\"6945\">236</sup>, אבל בחי' התענוג שבכת\"ר למעלה מבחי' עד\"ן <span data-k=\"pg\">1164</span> ּ והוא בקוצ\"ו של יו\"ד והיינו בחי' הארת עתיקא דלכך אומר דא היא סעודתא דעתיקא<sup data-n=\"6946\">237</sup> כמ\"ש במ\"א בפי' מאמר הזוהר בענין ג' סעודות השבת באריכות, אך גם בחי' אור התענוג שבכתר גם הוא עולה ונכלל בעצמות התענוג הפשוט כי אינו אלא הארת עונג פרטי משלימות המלאכה בלבד דהיינו ענין נעוץ תחלתן בסופן כנ\"ל וד\"ל.\n<b>והנה</b> יש עוד בחי' תענוג הבא מחמת השביתה מן המלאכה בלבד כי כאשר האדם שובת ונח מיגיעתו במלאכה גשמית וינוח אז חוזרת נפשו אליו במנוחה ונק' נייחא דרוחא ונפשא<sup data-n=\"6947\">238</sup> כו' אזי מתענג מאד, כידוע דהמנוחה מן המלאכה הוא תענוג גדול יותר מן הטיול ושארי תענוגי', וגם המנוחה מן המלאכה רוחני' כמו השפעת שכל לתלמיד להשיב לשואלו שזהו ירידה מכח עצמו' שכלו כנ\"ל כאשר שובת ונח מטרדתו זו שמטריד לכח שכלו להשפיל א\"ע כו', או כשינוח בכח שכלו מלהתפשט ולירד לעיין ולפקח באיזה התחכמות ציור וכתיבה וכה\"ג כנ\"ל (וגם המנוחה מטרדת עומק עיון שכלו באיזה מושכל שלמעלה מכלי השגתו יקרא יותר תענוג נפלא כשנח ממנו, להיות שכח שכלו עולה למעלה מעלה ביותר מכפי השגתו",[["6943","234","<b>אז תתענג על הוי'</b>: ישעי' נח, יד."],["6944","235","<b>דיו\"ד בחכמה וקוצו של יו\"ד בכת\"ר</b>: נסמן לעיל פ' תצוה שס, א."],["6945","236","<b>והתענוג שבחכמ\"ה נק' בחי' עד\"ן</b>: ראה גם סידור ענייני סעודת שבת קעג, סע\"ב ואילך. לעיל פ' שמות כו, ג. מ, א. וראה גם לעיל פ' בשלח קמא, ב ובהערה 98."],["6946","237","<b>אומר דא היא סעודתא דעתיקא</b>: סידור אדה\"ז סדר קידוש ליום השבת. ראה זהר יתרו פח, א-ב. סידור סדר סעודת שבת קצט, ג."],["6947","238","<b>נייחא דרוחא ונפשא</b>: נסמן לעיל פ' יתרו רסו, א."]]],[2300550536,"להשיג עומק המושג שזה יותר טרדא מירידתו להשיב לתלמיד השואל וממילא הוא תענוג גדול יותר מצד השביתה והמנוחה, מלבד תענוג המצאת העומק של השכל מצד עצם השכל ההוא שהתענוג מלובש בשכל<sup data-n=\"6948\">239</sup> מצד השכל כמ\"ש במ\"א וד\"ל). ואמנם הנה בחי' התענוג ההוא שמן המנוחה הוא בחי' עונג כללי שוה ומשוה קטן וגדול<sup data-n=\"6949\">240</sup> דהיינו שנמצא בהשווא' א' בכל הכחות של הנפש בכח השכל הרוחני כמו בכח הפעולה הגשמי', שהרי ענין המנוחה אחת היא בין כשינוח מן הפעולה שחוזר כח הפועל אליו או כשינוח מהמשכת והשפעת טרדת השכל שתנוח דעתו עליו, אע\"פ שהדעת רוחני והכח הפועל המניע גשמי אעפ\"כ בחזרתם אל עצמות הנפש תענוג אחד להם. כי עיקר התענוג הוא רק החזרת התפשטות כחות הנפש אל עצמותה ואין עיקר הענין אלא שבאה הנפש אל בחי' עצמותה שזהו הנק' מנוחה כידוע, וא\"כ מה חילוק יש בין החזרת כח השכל להחזרת כח הפעולה שניהם שוין לענין המנוחה שנק' מנוחת הנפש להיות בבחי' עצמותה, וע\"כ התענוג מן המנוחה בשניהם שוה אע\"פ שזה רוחני וזה גשמי וד\"ל.\n<b>ועפי\"ז</b> יובן למעלה ג\"כ במ\"ש כי בו שבת וינפ\"ש שחוזרים כל האורות העליוני' אל עצמו' אוא\"ס ממש כנ\"ל שבזאת המנוחה יש בחי' תענוג גדול מצד בחי' השביתה והמנוחה מן ההתפשטות בלבד, ולמעלה נק' בחי' נייחא דרוח\"א ונפש\"א בבחי' מדות ודבור ועוד למעלה מעלה גם בהחזרת חו\"ב וגם בהחזרת אור התענוג העליון משלימות הבירורים כנ\"ל, הנה בחי' צד ההחזרה אל העצמות נק' מנוח\"ה לחי\"י העולמי'<sup data-n=\"6950\">241</sup> כו' בכלל, וז\"ש כי בו שבת וינפ\"ש שבא כביכול אל בחי' עצמותו ממש. ובזה שוה בחי' החזרת אור היותר עליון כמו התענוג והחכמה עם <span data-k=\"pg\">תקפב</span> ּ החזרת אור היותר תחתון כמו בחי' המלאכה בפועל המעשה למעלה כמ\"ש ויאמר אלקים ויה\"י כן<sup data-n=\"6951\">242</sup> בפו\"מ כו' שהוא מקור השפעת סוף עולם העשי' כידוע, והוא בחי' שבת האמיתי שכולל כל הארת הקו בהשוואה א' מריש כל דרגין עד סוף כל דרגין. וז\"ש וישבו\"ת ביום השביעי שיום הז' הוא כעונג העולה בבחי' או\"ח בפרט משלימות הבירורים הפרטים כנ\"ל, אבל וישבות ביום הז' הוא בחי' מנוחה לחיי העולמים שהוא למעלה גם מבחי' עצמות התענוג שמשתעשע משלימות הבירורים כנ\"ל בפי' טוב מאד, כי אין דומה לעצמו' אוא\"ס ממש כלל אפי' בחי' התענוג העצמי שמשתעשע בכל עצמותו משלימות המלאכה וכה\"ג וד\"ל. ונמצא מובן מכל הנ\"ל עכ\"פ בשרש בחי' השבת שהוא בחי' עליות כל העולמות דאבי\"ע אל בחי' עצמות אוא\"ס ממש כמו שהוא בעצמותו כביכול כו', וזהו היפך כוונת עצמות אוא\"ס בירידת וצמצום עצמותו ע\"י בחי'",[["6948","239","<b>שהתענוג מלובש בשכל</b>: ראה גם לעיל פ' יתרו רסז, ג ובהנסמן שם."],["6949","240","<b>שוה ומשוה קטן וגדול</b>: ע\"פ (פיוט לימים נוראים) האוחז ביד מדת משפט."],["6950","241","<b>מנוח\"ה לחי\"י העולמי'</b>: סוף תמיד."],["6951","242","<b>ויאמר אלקים ויה\"י כן</b>: בראשית א, ט [בדילוג]. ועוד. וראה גם רמב\"ן ואוה\"ח שם (א, ז)."]]],[2300550549,"מקו\"פ כו' להאיר דרך קו וחוט ולהתמשך מטה מטה בע\"ס בבחי' מקיפי' ופנימי' במספר ומדה קצובה עד שנתהוו גם ג' עולמות הנפרדים בי\"ע כנ\"ל. ולזה הטעם ציוה ה' בפ' תרומה תצוה על המעשה של המשכן והכלים והיריעות להיות בחי' ירידת הארת אוא\"ס למטה בבחי' כלים ולבושים מקיפי' ופנימי' דיריעות וכלי המשכן כנ\"ל באריכות, שזהו ממש כמו ענין וי\"ו יומין דחול כו' וימ\"ב כנ\"ל, וענין כוונה זאת כדי להיות לו דירה בתחתונים ע\"י המשכן וכליו כנ\"ל. ואמנם מיד שנגמר מלאכת המשכן וכל כליו ה\"ז ממש כמו שנגמר כל מלאכת וי\"ו יומין דחול בוימ\"ב למעלה שמיד נעשה בחי' או\"ח אל העצמות, והוא עליות כל העולמות כנ\"ל וגם אפי' בחי' התענוג שמלובש בזה כו' כנ\"ל, כך מיד בגמר מלאכת המשכן חוזר הכל אל בחי' העצמו' ממש והוא ענין מצות השבת ממש כנ\"ל שהוא דוקא מיד אחר תשלום כל המלאכה שנק' בירורים ומחמת בחי' המנוחה כנ\"ל, וזהו שמיד אחר מצות מעשה המשכן נצטווה על מצות השבת כנ\"ל וד\"ל.\n<b>ומעתה</b> עדיין יש להבין למה כאן בפ' ויקהל הזהיר תחלה על מצות השבת ואח\"כ על מעשה המשכן כמבואר בפרשה ולמה שינה הסדר מכמו שנצטוה תחלה כו' כנ\"ל. אך בהכרח לומר ששינה משה מכפי הסדר שנצטווה הוא לעשות המשכן תחלה ולבנ\"י הזהיר תחלה על השבת כו' וזה פלאי לכאורה, וגם יש להבין מה ששינה הסדר להזהיר לבנ\"י על היריעות והקרשים תחלה שהן לנגד בחי' מקיפים ואח\"כ על הכלים שהן בחי' או\"פ כנ\"ל, ובפ' תרומה הרי הקדים לצוות למשה על בחי' הכלים ארון וכפורת וכו' ואח\"כ יריעות וקרשים, ולמה שינה מכמו שנצטווה הוא בעצמו (וגם בפ' כי תשא שאמר ראה קראתי בשם בצלאל כתיב ועשו את האוהל והארון<sup data-n=\"6952\">243</sup> כו' והיינו כמו הסדר שהזהיר לבנ\"י ולא כמו שצוה למשה). ולהבין טעם שינוי הסדר בב' ענינים הללו, יש להקדים תחלה את הידוע אשר בין הציווי הזה דבפ' תרומה תצוה אל משה ובין הציווי הזה של משה לבנ\"י בפ' ויקהל הפסיק הענין בפ' כי תשא בסיפור מעשה דחטא העגל<sup data-n=\"6953\">244</sup> שנעשה קודם ירידת משה מן ההר <span data-k=\"pg\">1166</span> ּ בלוחות הראשונות שהרי ע\"י חטא העגל נשתברו לוחות הראשונות כידוע.\n<b>והנה</b> בלוחו\"ת הראשונות נא' חרו\"ת על הלוחות<sup data-n=\"6954\">245</sup> כו' וארז\"ל חירות ממה\"מ חירו\"ת משעבוד מלכיות<sup data-n=\"6955\">246</sup> כו' כידוע,",[["6952","243","<b>ועשו את האוהל והארון</b>: תשא לא, ו. ז [ושם: ועשו. . את אהל מועד ואת הארון]."],["6953","244","<b>בפ' כי תשא. . דחטא העגל</b>: פל\"ב."],["6954","245","<b>חרו\"ת על הלוחות</b>: תשא לב, טז."],["6955","246","<b>חרו\"ת. . חירות ממה\"מ חירו\"ת משעבוד מלכיות</b>: ראה שמו\"ר פל\"ב, א. פמ\"א, ז. זהר בראשית לז, ב."]]],[2300550562,"והענין הוא להיות כי ע\"י הארת אוא\"ס בלוחות הראשונות לא הי' שום יניקה ואחיזה לחיצוני' כלל כי נתברר כל בחי' הרע דנוג\"ה כמו לעתיד דכתי' ואת רוח הטומאה אעביר<sup data-n=\"6956\">247</sup> כו' ובלע המות<sup data-n=\"6957\">248</sup> כו', וז\"ש חירות ממה\"מ כי שרש המות נמשך מעה\"ד טו\"ר כידוע וזהו חירות מסט\"א לגמרי, וע\"כ היו יכולין אז לעשות את המשכן וכליו ויריעות בחי' או\"פ ומקיפי' להיות כלי ומכון לאוא\"ס בלי יתערב זר בהם כלל וכמ\"ש ה' בדד ינחנו<sup data-n=\"6958\">249</sup> כו' משום שנאמר וכבוד\"י לאחר לא אתן<sup data-n=\"6959\">250</sup> כו'. אך לאחר חטא העגל הנה כתיב ויתנצלו בנ\"י<sup data-n=\"6960\">251</sup> את עדים מהר חורב שהוא בחי' ב' כתרי\"ם<sup data-n=\"6961\">252</sup> שקשרו בראש כאו\"א שלא הי' אחיזה ויניקה לחיצונים בהם כלל, ולאחר שהורד עדים זה נמשך עליהם מסט' דחויא בישא ובלשון הגמ' נק' זוהמא של נחש הקדמוני<sup data-n=\"6962\">253</sup> וישראל שעמדו בהר סיני פסקה זוהמתן<sup data-n=\"6963\">254</sup> ולאחר חטא העגל חזר להם<sup data-n=\"6964\">255</sup> ושלט בהם אילנא דמותא<sup data-n=\"6965\">256</sup> כו' מבחי' עה\"ד טו\"ר כו'. ולהיות כן לא הי' ביכולתם לעשות המשכן וכליו להיות רק בחי' כלי לאוא\"ס בלבד מאחר שיש בהם אחיזה לסט\"א הרי יכולים גם החיצוני' להתערב בכלים דמשכן וכתי' וכבוד\"י לאחר לא אתן טהור עינים<sup data-n=\"6966\">257</sup> כו' ולא יוכל להיות גילוי אוא\"ס כלל במשכן וכליו בבחי' או\"פ ואו\"מ כנ\"ל. ואע\"פ שעלה משה להר אח\"כ עם שני לוחות האחרוני'<sup data-n=\"6967\">258</sup> לא הי' עי\"ז חירות לגמרי מסט\"א כמו ע\"י לוחות הראשוני'<sup data-n=\"6968\">259</sup> כידוע, הנה לזאת בפ' ויקהל ציוה משה לבנ\"י תחלה על מצות השבת ואח\"כ על מעשה המשכן בכדי שע\"י מצות השבת יוכלו לעשות המשכן וכליו להשראת אוא\"ס בלי יתערב זר מן החיצוני' בהם כלל. והטעם הוא בהיות מבואר למעלה בשרש ענין השבת שהוא בחי' העלאה מלמטה למעלה בבחי' או\"ח אל בחי' עצמות התענוג הפשוט שבעצמות אוא\"ס ממש כנ\"ל באריכות, והוא למעלה מעלה מכל עיקר ומקור ההשתלשלו' לגמרי דהיינו בבחי' סובב הכללי דקמי' כחשיכה כאורה<sup data-n=\"6969\">260</sup> כו' ושם נא' אם צדקת מה תתן לו ואם רבו<sup data-n=\"6970\">261</sup> פשעיך מה תעשה לו כו', וע\"כ א' בזוהר דחייבי הגיהנם שובתין ונייחין בשבת<sup data-n=\"6971\">262</sup> משום דבשבת עולין כל העולמות בעצמות התענוג וכמ\"ש למעלה בענין אז תתענג על ה' כו' וכמאמר כל דינין מתעברין מינה<sup data-n=\"6972\">263</sup> כו', ובעליי' גדולה כזו שם אין מקום ליניקו' החיצוני' כלל משום שבשבת נא' אות היא ביני ובין בנ\"י<sup data-n=\"6973\">264</sup> דוקא ולא יש חלק לסט\"א בו כלל, לפי שענין השבת הוא בחי' אור החוזר בעצמותו ממש ושרש נשמת ישראל עלו בעצמות אוא\"ס דוקא כמ\"ש כי חלק הוי' עמו<sup data-n=\"6974\">265</sup> כידוע, וז\"ש",[["6956","247","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["6957","248","<b>ובלע המות</b>: נסמן לעיל פ' יתרו ערב, א."],["6958","249","<b>ה' בדד ינחנו</b>: האזינו לב, יב."],["6959","250","<b>וכבוד\"י לאחר לא אתן</b>: ישעי' מב, ח. מח, יא."],["6960","251","<b>ויתנצלו בנ\"י</b>: תשא לג, ו."],["6961","252","<b>עדים. . ב' כתרי\"ם</b>: שבת פח, א."],["6962","253","<b>ובלשון הגמ' נק' זוהמא של נחש הקדמוני</b>: ראה שבת קמו, א. בחיי שמיני יא, ל."],["6963","254","<b>וישראל. . פסקה זוהמתן</b>: ראה שבת קמו, רע\"א."],["6964","255","<b>ולאחר חטא העגל חזר להם</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שלד ובהנסמן במ\"מ לשם. תקס\"ו ע' קס."],["6965","256","<b>ושלט בהם אילנא דמותא</b>: ראה זהר במדבר קיט, א."],["6966","257","<b>טהור עינים</b>: חבקוק א, יג."],["6967","258","<b>שעלה משה. . לוחות האחרוני'</b>: תשא פל\"ד."],["6968","259","<b>לוחות האחרוני'. . כמו. . הראשוני'</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' קסה."],["6969","260","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["6970","261","<b>אם צדקת. . ואם רבו</b>: איוב לה, ז. ו. [ושם: ורבו — ראה גם לעיל פ' וארא סד, א. וש\"נ]."],["6971","262","<b>דחייבי הגיהנם שובתין ונייחין בשבת</b>: ראה זהר יתרו פח, ב. מאמרי אדה\"א דברים ח\"ג ע' א'קיח. וש\"נ."],["6972","263","<b>כל דינין מתעברין מינה</b>: ראה זהר תרומה קלה, רע\"ב."],["6973","264","<b>אות היא ביני ובין בנ\"י</b>: תשא לא, יז [בהיפך הסדר — ראה עץ הדעת טוב להרח\"ו ר\"פ ויקהל (ד\"ה או). מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשצא. מאמרי אדה\"א שמות ח\"א ע' רלח. ח\"ב כאן ע' תרסח. דברים ח\"א ע' רצ. לקו\"ת ראה כא, ג]."],["6974","265","<b>כי חלק הוי' עמו</b>: האזינו לב, ט."]]],[2300550575,"בינ\"י ובין בנ\"י דוקא וכמ\"ש בזוהר פ' יתרו<sup data-n=\"6975\">266</sup> באריכות ע\"ש. וע\"כ ע\"י מצות השבת דוקא יכלו בנ\"י לעשות המשכן וכליו בבחי' או\"פ ואו\"מ להשראת אא\"ס בלי יתערב זר שם כלל וכלל מבחי' נוג\"ה, כי אחר ההעלא' דשבת יוכל להיו' ההמשכה מלמעלה למטה ג\"כ לסט' דקדושה לבד ולא <span data-k=\"pg\">תקפג</span> ּ להיות יניקה לחיצוני' כלל בכלים דמשכן, כי מפני עליות העולמות דשבת כבר בטלה יניקו' החיצונים, משא\"כ קודם שנצטוו על השבת שלא היו יכולים לעשות המשכן וד\"ל. אבל בפ' תרומה תצוה שהי' הציווי של ה' למשה עדיין קודם חטא העגל ע\"כ הי' להיפך, שתחלה צוה לו על המשכן בבחי' המשכה וירידה למטה כי אין מקום ליניקו' החיצונים למטה מפני שחירות ממ\"ה כו' כנ\"ל ע\"י לוחות הראשונות ואח\"כ נצטווה משה על השבת בבחי' העלאה דאו\"ח כמו בגמר מלאכה דוי\"ו יומין דחול כנ\"ל, משא\"כ לאחר חטא העגל לא הי' יכולת להיות הציווי על המשכן תחלה כ\"א על השבת תחלה מטעם הנ\"ל וד\"ל.\n<b>ובכל</b> זה יובן ג\"כ התירוץ לקושי' השני' למה שינה הסדר לצוות לבנ\"י על היריעות קודם לכלים ובפ' תרת\"צ הרי נצטווה משה לעשות הכלים תחלה כנ\"ל. כי בפ' תרת\"צ הי' הציווי קודם החטא דעגל שהי' חירות מסט\"א לגמרי כנ\"ל, לכך נצטווה ג\"כ כסדר והילוך ההעלאה מלמטה למעלה שיהי' כלי לבחי' או\"פ תחלה ואח\"כ כלי לבחי' מקיפים כמו עד\"מ הבנין שעושין היסוד תחלה כו', מאחר שלא יש יניקה לחיצונים למטה בבחי' כלים דקדושה כלל גם בחיצוניו' הכלים דאו\"פ כו'. וזה ידוע כי בבחי' הילוך המדרגה מלמטה למעלה מתחלה נמשך א\"פ ואח\"כ א\"מ כידוע, אבל בפ' ויקהל שהציווי לבנ\"י הי' אחר חטא העגל לא היו יכולי' לעשות המשכן בלתי קבלת מצות שבת תחלה שהוא תכלית ההעלאה בעצמות אוא\"ס כנ\"ל, ומשם נמשך ויורד כסדר ההילוך וההמשכה מלמעלה למטה בעשיית המשכן, ובבחי' ההמשכה מלמעלה למטה ממדרגה עליונה כזאת הרי בחי' המקיפי' נמשכי' תחלה ואח\"כ בחי' או\"פ כידוע, וע\"כ צוה משה להם על היריעות והקרשים תחלה ואח\"כ על הכלים (ועולה זה בסגנון א' עם ענין פלוגתא דמשה ובצלאל<sup data-n=\"6976\">267</sup> כנ\"ל וכמ\"ש במ\"א) וד\"ל.\n<b>אך</b> הנה עדיין יש להבין דלכאורה אינו מובן טעם הנ\"ל דהלא ידוע בחשבון המ' יום<sup data-n=\"6977\">268</sup> בעלייתו וירידתו שנית בלוחות האחרונות הרי אותו היום שנצטווה בפ' ויקהל<sup data-n=\"6978\">269</sup> על מצות",[["6975","266","<b>בזוהר פ' יתרו</b>: פח, ב."],["6976","267","<b>פלוגתא דמשה ובצלאל</b>: ברכות נה, א."],["6977","268","<b>בחשבון המ' יום</b>: ראה בארוכה בסדר הדורות ב\"א תמ\"ח פיסקא ”בס' פ\"ר פ' עקב\". ואילך."],["6978","269","<b>שנצטווה בפ' ויקהל</b>: במאמרי אדה\"א שמות כאן ע' תרס הלשון: שיום אשר צוה להם ענין השבת שנאמר בפ' ויקהל."]]],[2300550586,"השבת לא הי' יום השבת אלא בא' מימות החול דוקא, וא\"כ מאי נפקותא בזה שהקדים להם מצות השבת מאחר שציווי זה ביומין דחול הוא ובימות החול אין עליות העולמות כלל אדרבה בחי' ירידה והתלבשו' מלמעלה למטה כנ\"ל, ואם בשביל חטא העגל לא היו יכולים לעשות המשכן א\"כ מה הועיל לזה ציווי דשבת אם אינו ביום השבת (ואולי גם אם הציווי דשבת אינו בשבת מ\"מ אם קיימו מצות השביתה בשבת אח\"ז מיד הי' יכול להיות ציווי דמעשה המשכן אחר זה השבת מיד, ומי מכריח לומר שציווי דמשכן הי' תיכף באותו יום שצוה על השבת מתחלה אולי הי' איזה ימים הפסק בנתיים דהיינו שיום השבת הפסיק ביניהן, ובזה אתי שפיר הכל ולק\"מ ודו\"ק). אך הענין יובן בהקדים מאמר רז\"ל כל העוסק בתורת עולה כאלו הקריב עולה<sup data-n=\"6979\">270</sup>, ולכאורה זה פלא גדול דהלא קרבן העולה אינו אלא ע\"י הכהן<sup data-n=\"6980\">271</sup> ובקידוש ידים תחלה<sup data-n=\"6981\">273</sup> וביום<sup data-n=\"6982\">272</sup> ואיך הישראל שאינו כהן ולומד בלילה במס' זבחים בהלכות עולה יהי' כאלו מקריב קרבן עולה ממש, ואי משום שנא' ונשלמה פרים שפתינו<sup data-n=\"6983\">274</sup> אטו בדבור תליא מלתא, שהרי האומר הרי עלי<sup data-n=\"6984\">275</sup> לא הקריב <span data-k=\"pg\">1168</span> ּ עולה ממש רק שהפרישה בדבור בעלמא כידוע.\n<b>אך</b> הנה יש עוד להבין ענין הלשון שנאמרו בדברי רז\"ל במצות ת\"ת בלשון קריאה דוקא כמו הקורא בתורה<sup data-n=\"6985\">276</sup> כידוע, איך יפול לשון קריאה על ענין הלימוד כי הלימוד אינו מוכרח בקריאה בדבור דוקא, וגם לשון קורא בתור\"ה בבי\"ת דמשמע בתו\"ך התורה אינו מובן, דאדרבה ענין הלימוד הוא שהאדם מקבל לנפשו מחכמה שבתורה כתלמיד שלומד ומקבל מרבו שנק' לימוד, וקורא בתורה היינו שמשפיע האדם וממשיך בתורה הרי התורה בחי' מקבל ממנו כו'. אך הענין הוא דבאמת ענין קריאה בתורה היינו להמשיך בחי' גילוי אוא\"ס בחכמה שבתורה וכמ\"ש בע\"ח, וזהו עיקר הפי' בעוסק בתורה לשמ\"ה שהוא לשם התורה עצמה להמשיך בה אור א\"ס<sup data-n=\"6986\">277</sup> כו', כי ראשית גילוי והתלבשות אוא\"ס אינו אלא בחכמ\"ה<sup data-n=\"6987\">278</sup> דוקא ובחכמה שבתו' דוקא שנק' ה' קנני ראשי\"ת דרכ\"ו<sup data-n=\"6988\">279</sup> כו'. דהנה בכל פ' ופ' שבתורה נא' וידבר ה' אל משה לאמר<sup data-n=\"6989\">280</sup> דהיינו בחי' המשכת וגילוי אוא\"ס בחכמה שבתורה ע\"י משה ששרש נשמתו מאור החכמה<sup data-n=\"6990\">281</sup> מבחי' מ\"ה דחכמ\"ה כמ\"ש ונחנו מ\"ה<sup data-n=\"6991\">282</sup> כו' ומשה משפיע וממשיך גילוי זה לבנ\"י, וזהו לאמ\"ר להמשיך ולהשפיע למטה במל' דאצי' שרש כנ\"י<sup data-n=\"6992\">283</sup> דלעילא. ולזה הטעם כאשר חוזר משה לצוות לבנ\"י ככל אשר צוה לו ה' הנה מצינו",[["6979","270","<b>כל העוסק בתורת עולה כאלו הקריב עולה</b>: ראה מנחות קי, א. לקו\"ש ערב פסח כרך לב ע' 37 וש\"נ."],["6980","271","<b>קרבן העולה. . ע\"י הכהן</b>: ויקרא פ\"א."],["6981","273","<b>ובקידוש ידים תחלה</b>: כ\"ה בגוכתי\"ק. ובמאמרי אדה\"א שמות כאן ע' תרסט. ראה רמב\"ם הל' ביאת המקדש פ\"ה, ה\"א וה\"ג."],["6982","272","<b>קרבן העולה. . וביום</b>: צו, ז, לח. תו\"כ שם. זבחים צח, א."],["6983","274","<b>ונשלמה פרים שפתינו</b>: הושע יד, ג. ראה מאמרי אדה\"א במדבר ח\"ב ע' תקצד. וש\"נ. סה\"מ תרנ\"ה ע' לד."],["6984","275","<b>האומר הרי עלי</b>: ראה מנחות פי\"ג, מ\"ו. מ\"י."],["6985","276","<b>הקורא בתורה</b>: ברכות ט, ב. י, ב. ראה מאמרי אדה\"א שמות ח\"א ע' סא. וש\"נ. ע' סד."],["6986","277","<b>בע\"ח. . לשמ\"ה שהוא לשם התורה. . אור א\"ס</b>: ראה פע\"ח שער הנהגת הלימוד. לעיל פ' וארא פ, ד. וש\"נ."],["6987","278","<b>והתלבשות אוא\"ס. . בחכמ\"ה</b>: ראה גם לעיל פ' שמות ז, ד. וש\"נ."],["6988","279","<b>ה' קנני ראשי\"ת דרכ\"ו</b>: משלי יח, כב."],["6989","280","<b>בכל פ'. . וידבר ה' אל משה לאמר</b>: ראה גם לעיל פ' וארא נט, א ובהערה 30."],["6990","281","<b>משה ששרש נשמתו מאור החכמה</b>: ראה לקו\"ש שמות (כרך ו) ע' 244 ואילך. לעיל פ' שמות ד, ד."],["6991","282","<b>ונחנו מ\"ה</b>: בשלח טז, ז-ח."],["6992","283","<b>במל' דאצי' שרש כנ\"י</b>: ראה זהר בלק קצז, א."]]],[2300550597,"בכמה מקומות שהוא מפרש כל דבר ודבר בפרט שציוה לו ה' והל\"ל בקצרה ויעשו בנ\"י ככל אשר צוה ה' אל משה, וכמו בכאן שאומר משה לבנ\"י זה הדבר אשר צוה ה'<sup data-n=\"6993\">284</sup> כו' חוזר וכופל כל מעשה המשכן שנצטווה משה כבר למה לכתוב פרשה מיותרת הל\"ל וידבר משה אל בנ\"י ככל אשר צוה לו ה' כו'. וגם בעשי' דבצלאל שעשה כפי שציוה משה חזר וכפל להזכיר כל פרטי הכלים והיריעות והקרשים כו', והל\"ל ויעש בצלאל ככל אשר צוה משה כו'. אלא מוכרח לומר שיש בזה חילוקי מדרגות זו למעלה מזו שבחי' המשכת אוא\"ס בחכמה הוא הציווי מה' אל משה והציווי דמשה לבנ\"י בבחי' הדבור הוא למטה מזה הגילוי, ע\"כ חוזר לפרט הכל וצריך לכתוב פ' שלימה בפרטות ציווי זה בפ\"ע כי הוא בחי' המשכה מיוחדת בפ\"ע בבחי' הדבור מבחי' מ\"ה דחכמה דמשה לבנ\"י בחי' המל' כו'. ומכ\"ש בעשי' דבצלאל שהביא לידי מעשה ממש בכל הכלים והיריעות שהיא בחי' המשכה למטה מטה ממש בחיצוניו' ביותר, הוצרך לכתוב פ' שלימה באותיות מכל פרט ופרט הכלים בפ\"ע כי התורה נצחית היא<sup data-n=\"6994\">285</sup>, וגם עכשיו יש בחי' המשכן הרוחני באצי' ובבריאה ובחי' משה ממשיך שרש המשכן לבנ\"י למעלה במל' ומשם לבריא\"ה ששם הוא בחי' עשי' דבצלא\"ל בעולם הבריאה כמ\"ש בזוהר וד\"ל. ובכל זה יובן ענין מאמר הנ\"ל דכל העוסק בתורת עולה כאלו הקריב עולה ואע\"פ שישראל שאינו כהן לומד בתורת עולה בדבור בלבד כנ\"ל, כי מה שלומד דין הקרבן עולה הרי הוא ממשיך בשרש התורה כמו שהיא למעלה דמח\"ע נפק'<sup data-n=\"6995\">286</sup> שלמעלה מבחי' זמן ומקום כנ\"ל בפי' עוסק בתורה לשמה להמשיך אא\"ס בח\"ע שרש התורה למעלה, וע\"כ <span data-k=\"pg\">תקפד</span> ּ גם הישראל שקורא וממשיך א\"ס בבחי' חכמה זו שבדין קרבן עולה הרי זה כאלו הקריב עולה למעלה ששם הוא למעלה מבחי' זמן ומקום כו' וד\"ל. וזהו ג\"כ הטעם במצות ת\"ת שלומד מסכת שבת בחול<sup data-n=\"6996\">287</sup> שאין זמן השבת וכמו שמצוה ללמוד הלכות פסח במס' פסחים גם שלא בזמן חג הפסח או בסדר קדשים וטהרות גם עכשיו שאין בהמ\"ק או בח\"ל שאין הטהרות נוהג וכיוצא בזה וד\"ל.\n<b>ובכל</b> הנ\"ל יובן ג\"כ תירוץ לקושיא דלעיל דמצות השבת ציוה להם בא' מימות החול ומאי נפקותא בזה כו' כי הגם שהציווי זה הי' בימות החול מאחר שאמר בתורה ויאמר משה<sup data-n=\"6997\">*288</sup> אלה הדברים כו' ששת ימים כו' ה\"ז בחי' המשכת אוא\"ס בחכמה שרש התורה כמו שהיא למעלה בבחי' דיבור העליון שלמעלה מבחי' זמן ומקום א\"כ גם שהי' בחול נמשך להם עי\"ז בחי' אור חוזר דשבת כמו שהוא למעלה ממש שלמעלה מבחי'",[["6993","284","<b>זה הדבר אשר צוה ה'</b>: ויקהל לה, ד."],["6994","285","<b>התורה נצחית היא</b>: ראה תניא פי\"ז. לעיל פ' שמות א, א. וש\"נ."],["6995","286","<b>התורה. . דמח\"ע נפק'</b>: נסמן לעיל פ' יתרו רסח, ד."],["6996","287","<b>שלומד מס' שבת בחול</b>: ראה גם אוה\"ת שבועות ע' קנט. סה\"מ תרכ\"ז ע' שיב (בשולי הגליון). המשך תער\"ב ע' שמב. ולהעיר ממאמרי אדה\"ז תקס\"ט ר\"ע קל."],["6997","*288","<b>משה</b>: הוספת תיבת משה בהכתוב."]]],[2300550608,"זמן ומקום כנ\"ל בענין העוסק בתורת עולה כו' ועי\"ז היו יכולים לעשות אח\"כ המשכן וכליו בבחי' ירידת והמשכת אוא\"ס מלמעלה למטה כנ\"ל וד\"ל.\n<b>וזהו</b> ויקהל משה את כל עדת בנ\"י ויאמר אליהם אלה הדברים כו' ששת ימים כו' שהוא מצות השבת תחלה להיות בבחי' ההעלאה מלמטה למעלה בעצמות התענוג הפשוט להיות מתענגים על ה' כו' כנ\"ל, ואח\"כ ציוה להם על מעשה המשכן בבחי' ירידת וההמשכה מלמעלה למטה כו' מטעם הנ\"ל, אבל בציווי שנצטווה משה בפ' תרומה תצוה תחלה נצטווה על מעשה המשכן ואח\"כ על השבת כי אז הי' עדיין קודם חטא העגל כנ\"ל באריכות וד\"ל (וגם מלבד טעם חטא העגל כנ\"ל הנה ודאי יש הפרש בין הציווי אל משה לציווי דמשה לבנ\"י, כי שרש משה מבחי' יסוד אבא<sup data-n=\"6998\">288</sup> כו' ונק' שושבינא דמלכא<sup data-n=\"6999\">289</sup> להמשיך עצמות אוא\"ס מלמעלה למטה דוקא כמ\"ש במ\"א בטעם קריאת שם משה לשון משוי<sup data-n=\"7000\">290</sup> כי מן המים משיתיהו<sup data-n=\"7001\">291</sup> וכמ\"ש וגם דל\"ה דל\"ה לנו<sup data-n=\"7002\">292</sup> כו', ע\"כ נצטווה תחלה על מעשה המשכן שהוא בחי' אור ישר כנ\"ל ואח\"כ על השבת שהוא בחי' אור חוזר כנ\"ל. אבל בציווי דמשה לבנ\"י ששרשם במל' דאצי' שנק' מטרוניתא<sup data-n=\"7003\">293</sup> ששם בחי' אור חוזר קודם להיות שרש המל' מבחי' הגבורות<sup data-n=\"7004\">294</sup> דאו\"ח כידוע, ע\"כ הקדים לצוות להם על מצות השבת תחילה ואמר אליהם אלה הדברי' אשר ציוה ה' ששת ימי' כו' ואח\"כ ציוה להם על מעשה המשכן שהוא בחי' או\"י. וז\"ש ויאמר משה אל כל עדת בנ\"י זה הדבר אשר צוה ה' קחו מאתכם תרומה לה' זהב וכסף כו' וכל חכ\"ם לב בכם יעש\"ו את המשכ\"ן<sup data-n=\"7005\">295</sup> בבחי' או\"י אחר ההעלאה דשבת דבחי' או\"ח כי רוח אייתי רוח<sup data-n=\"7006\">296</sup> כו' וד\"ל). אך לפי זה הקושי' השני' אין לה תירוץ כי למה נצטווה משה על הכלים תחלה ולבנ\"י צוה על המשכן תחלה, הלא בבחי' או\"י מקיף קודם לפנימי ובבחי' או\"ח פנימי קודם למקיף כי מה שלא יוכל להתיישב בכלי יהי' בבחי' מקיף ונק' מקיף דאו\"ח, ומקיף דאו\"י הוא להיפוך שתחלה נמשך בחי' המקיף ומה שיוכל ממנו להתיישב בכלי נק' או\"פ שאחר ירידת המקיף כידוע אלא מוכרח לומר מטעם חטא העגל כנ\"ל וד\"ל).\n<b>ובכל</b> הנ\"ל יובן ג\"כ בטעם שינוי נוסח הכתובים בפ' מצות השבת שבפ' <span data-k=\"pg\">1170</span> ּ כי תשא בציווי ה' אל משה לנוכח הכתובים שבפ' מצות השבת כאן בפ' ויקהל, דבפ' כי תשא אמר את שבתותי תשמרו<sup data-n=\"7007\">297</sup> ב' שבתות שיש בכל שבת א' מלמטה למעלה בליל שבת והב' מלמעלה למטה ביום השבת כידוע בפי'",[["6998","288","<b>משה מבחי' יסוד אבא</b>: ראה לקו\"ש שמות (כרך ו) ע' 244 ואילך."],["6999","289","<b>משה. . שושבינא דמלכא</b>: נסמן לעיל פ' יתרו רסג, ב."],["7000","290","<b>משה לשון משוי</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע קכט ואילך. לעיל פ' וארא עט, ד. וש\"נ."],["7001","291","<b>כי מן המים משיתיהו</b>: שמות ב, י."],["7002","292","<b>וגם דל\"ה דל\"ה לנו</b>: שמות שם, יט. ראה לעיל פ' וארא פ, א."],["7003","293","<b>במל'. . שנק' מטרוניתא</b>: נסמן לעיל פ' תצוה שכג, ג."],["7004","294","<b>שרש המל' מבחי' הגבורות</b>: ראה גם לעיל פ' בשלח רמד, א. וש\"נ."],["7005","295","<b>וכל חכ\"ם. . המשכ\"ן</b>: השוה לעיל על יד הערה 6."],["7006","296","<b>רוח אייתי רוח</b>: נסמן לעיל פ' יתרו רנא, א."],["7007","297","<b>את שבתותי תשמרו</b>: תשא לא, יג. ראה גם מאמרי אדה\"א שמות ח\"א ע' רח. וש\"נ."]]],[2300550617,"וקראת לשבת ענג<sup data-n=\"7008\">298</sup> ובכאן לא אמר שבתותי. כי שם עיקר ענינו העלאה בעצמות התענוג משלימות המלאכה כנ\"ל שעלי' זו צורך ירידה כו', והיינו ב' שבתות כהלכתן בכל שבת<sup data-n=\"7009\">299</sup> כמ\"ש במ\"א, אבל כאן עיקר ענינו להעלות לכנ\"י למעלה ולהבדילם מסט\"א בעלי' זו מטעם חטא העגל כנ\"ל אין כאן אלא עלי' ולכך הזהיר לא תבערו אש<sup data-n=\"7010\">300</sup> לעורר פסולת מדה\"ד שרש הסט\"א, משא\"כ שם לא הזהיר ע\"ז כי הי' עדיין קודם חטא העגל כנ\"ל. וגם מ\"ש שם אות היא ביני כו' מטעם הנ\"ל בענין השביתה שהוא בעצמות כו' ולא יש חלק לסט\"א בו כלל ואז היו ישראל קודם חטא העגל שפסקה מהן זוהמא של נחש כו' בזמן מ\"ת כנ\"ל, משא\"כ כאן שהיו אחר החטא שחזר ונדבק בהם כנ\"ל בענין ויתנצלו בנ\"י את עדים כו' ע\"כ לא אמר כאן ביני ובין בנ\"י כו' כי לא הובדלו לגמרי עדיין מכל וכל. אך בבחי' נשמ\"ה יתיר\"ה<sup data-n=\"7011\">301</sup> שבאדם עדיין גם עכשיו נאמר בינ\"י ובין בנ\"י כמובן בזהר פ' יתרו וכמ\"ש במ\"א וד\"ל).",[["7008","298","<b>וקראת לשבת ענג</b>: ישעי' נח, יג. ראה גם מאמרי אדה\"ז תק\"ע ע' פו. לקו\"ת בשלח ב, א. אוה\"ת ישעי' כרך א ע' רעו ואילך."],["7009","299","<b>ב' שבתות כהלכתן בכל שבת</b>: ראה שבת קיח, ב. לעיל פ' בשלח רח, ד. וש\"נ."],["7010","300","<b>לא תבערו אש</b>: ויקהל לה, ג."],["7011","301","<b>נשמ\"ה יתיר\"ה</b>: ביצה טז, א. ראה זהר יתרו פח, ב. מאמרי אדה\"א בראשית ע' קה. וש\"נ. קונטרסים ע' שיח. וש\"נ. לקמן תכב, א."]]],[2300550067,"<b>ב\"ה</b>\n<span data-k=\"pg\">תקפה</span> ּ<b>ויקהל</b> משה<sup data-n=\"7012\">1</sup> את כל עדת בנ\"י<sup data-n=\"7013\">2</sup> כו', ויאמר משה אל כל עדת בנ\"י לאמר זה הדבר אשר צוה ה'<sup data-n=\"7014\">3</sup> כו' קחו מאתכם תרומה להוי' כל נדיב לבו יביאה<sup data-n=\"7015\">4</sup> את תרומת ה' כו'. והנה יש להבין תחלה בסדר פ' זו שא' קחו מאתכם תרומה להוי' כו', ואח\"ז יובן ראש הפ' במ\"ש ויקהל משה את כל עדת כו' אלה הדברים<sup data-n=\"7016\">5</sup> כו', ששת ימים תעשה<sup data-n=\"7017\">6</sup> כו'. דהנה יש להבין במ\"ש תרומה להוי' דמשמע מלשון זה דתרומ\"ה זו ענין העלאה והגבהה והוא שא' בזוהר ארמותא להוי'<sup data-n=\"7018\">7</sup> שזהו שמרומם ומגביה",[["7012","1","<b>ויקהל משה</b>: דרוש זה מיוסד על המאמרים דלהלן א) עד לקמן תיח, ג (פ\"כ) מיוסד על מאמר ד\"ה זה שנדפס במאמרי אדה\"ז תקס\"ב ח\"ב ע' שסא (וראשי פרקים נדפסו שם ע' תקפ). וראה גם המשך יו\"ט של ר\"ה תרס\"ו ס\"ע קי ואילך [כמצויין להלן במקומו בהערות, בפרטיות]. ב) מלקמן תיח, ג (פ\"כ) מיוסד על מאמר ד\"ה למה נסמכה פ' המשכן לפ' שבת — הנחת כ\"ק אדה\"א נדפסה במאמרי אדה\"ז תקס\"ג ח\"א ע' רלז. והנחת הר\"מ בן כ\"ק אדה\"ז נדפסה במאמרי אדה\"ז תקס\"ד ע' עח [ובפתיחא: להבין מארז\"ל למה נסמכה פ' שבת לפ' המשכן]. ג) מלקמן תכח, ב (פכ\"ז) ראה מאמר ד\"ה ואכלתם אכול ושבוע שנדפס במאמרי אדה\"ז תקס\"ז ע' רנא [מאמרי אדה\"א שמות ח\"א ע' קנא בהערה]. ד) מלקמן תלא, ב ד\"ה והנה מיוסד על ד\"ה ויקהל שנדפס במאמרי אדה\"ז תקס\"ה ח\"א ע' שלט ומקבילו בתו\"א ר\"פ ויקהל פו, ג. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם גם מפורט סימני האותיות הבאים לקמן בהמראי מקומות]."],["7013","2","<b>ויקהל משה את כל עדת בנ\"י</b>: ויקהל לה, א."],["7014","3","<b>ויאמר. . זה הדבר אשר צוה ה'</b>: ויקהל שם, ד."],["7015","4","<b>קחו מאתכם תרומה. . נדיב לבו יביאה</b>: שם לה, ה."],["7016","5","<b>אלה הדברים</b>: ויקהל לה, א."],["7017","6","<b>ששת ימים תעשה</b>: שם לה, ב."],["7018","7","<b>דתרומ\"ה. . בזוהר ארמותא להוי'</b>: לעיל בפ' יתרו רסח, ד: בזהר בפ' תרומה — ראה שם קמז, א."]]],[2300550099,"לשם הוי' עצמו למעלה ממנו כו', ואיך שייך לשון הגבהה והעלאה לשם הוי' שנשגב ומרומם לבדו מעצמו כמ\"ש אתה הוי' לבדך<sup data-n=\"7019\">8</sup> כו' וכתי' כי נשגב שמו לבדו<sup data-n=\"7020\">9</sup> ולמה צריך לרומם ולנשאות אותו. ועוד דאיך אמר כל נדיב לבו יביאה כו'. וגם מ\"ש ברישא קחו מאתכם תרומה דמשמע שמאתכם דוקא יקחו זאת התרומה שהוא בחי' הרוממות והתנשאות לרומם ולהעלות לשם הוי' ואיך הנברא בע\"ג ותכלית יהי' ביכולתו לרומם ולנשאות לשם הוי' שהוא בחי' סובב כ\"ע המתנשא מימו\"ע<sup data-n=\"7021\">10</sup> כו' (ומה שהמלאכי' נושאות הכסא<sup data-n=\"7022\">11</sup> דשם הוי' כמרכבה שנושא הרוכב כו' הרי א' בארון שנושאיו נשא<sup data-n=\"7023\">12</sup> כו'), (ומה שבכמה מקומות בכתובים נז' ענין ברכה בשם הוי' ממלאכים נבראי' ומנשמות כמו ברכו את ה' כל מלאכיו<sup data-n=\"7024\">13</sup> כו' וכן ואברכה שמך<sup data-n=\"7025\">14</sup> כו' וברכת את הוי'<sup data-n=\"7026\">15</sup> כו' הרי זהו בחי' ירידה והמשכה מלמעלה למטה שזה ביכולת הנבראי' לעורר ירידתו והמשכתו למטה בעולמות מאין ליש (ויש ברכה בראש שממשיכי' תוס' ברכה בשם הוי' עצמו למעלה כמו יהי שם הוי' מבורך<sup data-n=\"7027\">16</sup> כו'). אך הנה קושיא זו עצמה יש להקשות במ\"ש דוד ארוממך אלקי המלך<sup data-n=\"7028\">17</sup> כו' שזהו פלא גדול יותר איך יתכן שירומם וינשא למלך העליון שנק' מלך מרומם לבדו מתנשא מימו\"ע<sup data-n=\"7029\">18</sup> כו', שהוא רם ונשגב למעלה על כל ההשתלשלו' דאבי\"ע בבחי' סובב הכללי וגם בבחי' ממלא נק' המלך הקדוש<sup data-n=\"7030\">19</sup> מלך יחיד<sup data-n=\"7031\">20</sup> לבדו רק ע\"י צמצום נעשה מלך על עם כמ\"ש ה' מלך גיאות לבש<sup data-n=\"7032\">21</sup> כו', ואיך יקבל בחי' הרוממות והתנשאות מבחי' נפרד זולתו ובפרט מבע\"ג כנפש דוד שאמר ארוממך אלקי המלך שהוא המרומם אותו כו'. אך הנה כתיב<sup data-n=\"7033\">22</sup> ואלה דברי דוד האחרונים נאם כו' נאם הגבר הוקם על<sup data-n=\"7034\">23</sup> וארז\"ל שהקים עולה של תו\"מ<sup data-n=\"7035\">24</sup> כו', ויש להבין מהו ענין עולה של תורה כו', ומהו שהקים עול זה דמשמע שהקים והעלה והגביה אותו למעלה ומדרגה העליונה ביותר כו'.",[["7019","8","<b>אתה הוי' לבדך</b>: ישעי' לז, כ."],["7020","9","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג."],["7021","10","<b>המתנשא מימו\"ע</b>: נסמן בסמוך בהערה 18."],["7022","11","<b>שהמלאכי' נושאות הכסא</b>: ראה יחזקאל פ\"א. ראה גם לעיל פ' תצוה שמח, ד. וש\"נ. בשלח קעט, ב הערה 667."],["7023","12","<b>בארון שנושאיו נשא</b>: ראה סוטה לה, א. מאמרי אדה\"א בראשית ע' שעג. וש\"נ."],["7024","13","<b>ברכו את ה' כל מלאכיו</b>: תהלים קג, כ [בהוספת תיבות: ”את\" ”כל\" — ולהעיר מביאוה\"ז בלק צט, ד ואילך. קג, א]."],["7025","14","<b>ואברכה שמך</b>: תהלים קמה, א."],["7026","15","<b>וברכת את הוי'</b>: עקב ח, י."],["7027","16","<b>יהי שם הוי' מבורך</b>: תהלים קיג, ב."],["7028","17","<b>ארוממך אלקי המלך</b>: תהלים קמה, א."],["7029","18","<b>מלך מרומם לבדו מתנשא מימו\"ע</b>: ע\"פ ברכת יוצר."],["7030","19","<b>המלך הקדוש</b>: ברכות יב, ב. ראה גם לעיל פ' בא ק, ג. וש\"נ."],["7031","20","<b>מלך יחיד</b>: נוסח ברכת ישתבח."],["7032","21","<b>ה' מלך גיאות לבש</b>: תהלים צג, א. ראה גם לעיל פ' יתרו רנו, ד. וארא עה, א. וש\"נ."],["7033","22","<b>הנה כתיב</b>: מכאן (עד להלן: והוא כידוע שהרוח כלול) הועתק בהמשך תרס\"ו ס\"ע קי (בשינויים קלים)."],["7034","23","<b>ואלה דברי דוד האחרונים. . נאם הגבר הוקם על</b>: שמו\"ב כג, א [ושם: ונאם וכ\"ה בתרס\"ו כאן ס\"ע קי — ראה גם מאמרי אדה\"ז תקס\"ב כאן ע' שסא. שע\"ת עג, ג ובהערה 67]."],["7035","24","<b>שהקים עולה של תו\"מ</b>: במאמרי אדה\"ז תקס\"ב ובתרס\"ו: עולה של תורה. אבל כ\"ה גם לקמן תב, ד. תח, א. תיג, סע\"א. תטז, ב. תלג, ב. ובכ\"מ. בתרס\"ו כאן מציין: במד\"ר ס\"פ קרח. וראה גם מאמרי אדה\"א שמות ח\"א ע' רכה. וש\"נ."]]],[2300550131,"אך הנה כתיב<sup data-n=\"7036\">25</sup> נר הוי' נשמת אדם<sup data-n=\"7037\">26</sup> ולפעמים<sup data-n=\"7038\">27</sup> נר אלקים<sup data-n=\"7039\">28</sup> כו' שזהו כמו אור הנר שטבעו לעלות למעלה וגם לירד למטה וכך היא עולה ויורד תמיד וכך היא הנשמה הנמשל לנר היינו מה שהיא בבחי' רו\"ש תמיד כמו כל הנשמה תהלל י\"ה<sup data-n=\"7040\">29</sup> כו', וכן אמר בחיות ושרפים והחיות רו\"ש<sup data-n=\"7041\">30</sup> כו', וביאור הדבר יובן מאור הנר שבודאי א\"א לומר דמהות הנשמה הוא בבחי' אש ממש כאש השלהבת דאור הנר<sup data-n=\"7042\">31</sup> שהרי אמר ויפח באפיו נ\"ח<sup data-n=\"7043\">32</sup> נפיחה ברוח היא ולא באש, <span data-k=\"pg\">1172</span> ּ וכך ל' נשמה ענין נשימה<sup data-n=\"7044\">33</sup> כנשימה שבחוטם ואף וכמו רוח החיים בלב שעולה ויורד בדפיקו דליבא בבחי' רו\"ש ממש. אך באמת שרש ענין מהות הנשמה אינו רק בחי' רוח והבל כמ\"ש ויפח באפיו כו' וכמו והרוח תשוב אל האלקי'<sup data-n=\"7045\">34</sup> אשר נתנה, דמשמע שנתינה זו רוח היא וכמ\"ש אכן רוח היא באנוש<sup data-n=\"7046\">35</sup> ונשמת שדי תבינם ואמנם בחי' הרוח היא בלב והנשמה במוח, ויש בה מעלה יתירה שהיא בבחי' אור ממש ונק' נר הוי' והיינו בחי' הארה אלקי' ממש שנק' אור המאיר ונמשכת מבחי' אור האלקי העליון ולכך נק' נשמת שדי ממש בבחי' חלק אלוה ממש<sup data-n=\"7047\">36</sup>, והוא מה שתאיר באור ההשגה ובינה באלקות כחכם המאיר עיניו בשכל שהחו\"ב הן בבחי' אור המאיר כידוע. ושרש אור הפרטי' דנשמת אדם נמשך מאור הכללי שהוא מ\"ש כי הוי' אלקיך אש<sup data-n=\"7048\">37</sup> כו' שהוא שרש ומקור כל בחי' אור המאיר וכמו משל אש היסודי בד\"י שגבוה מכולן<sup data-n=\"7049\">38</sup> והאור הגשמי שרשו באש היסודי כידוע, ועכ\"ז עצם הנשמה היא בבחי' רוח והבל. והוא כידוע שהרוח כלול מאש ומים<sup data-n=\"7050\">39</sup> יחד וע\"כ יש ברוח בחי' העלאה והמשכה וירידה באו\"י ואו\"ח יחד שזהו התכללות דאש ומים, שטבע האש לעלות<sup data-n=\"7051\">40</sup> דוקא ולא לירד וטבע המים להתמשך למטה<sup data-n=\"7052\">41</sup> ולא לעלות מנמוך לגבוה כו' והממוצע הוא הרוח עד שהוא עושה מיצוע זה גם באש ומים, שהרי גם האש כלול מן הרוח ולכך יש בו ג\"כ עליי' וירידה, דודאי האש בלא רוח המנפח בו ומתערב ביסודו אינו מתפשט כלל וכלל עד שיכבה לגמרי, אך ע\"י הרוח יתפשט בעלי' למעלה ולצדדי', ומה שיש באש לעלות זהו ע\"י הרוח ג\"כ וגם מה שיש באש לירד היפוך טבעו זהו ע\"י הרוח.",[["7036","25","<b>אך הנה כתיב</b>: בתרס\"ו כאן ע' קיא: וילה\"ק תחלה מ\"ש."],["7037","26","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."],["7038","27","<b>ולפעמים נר אלקים כו'</b>: בתרס\"ו כאן ליתא."],["7039","28","<b>נר אלקים</b>: שאילתות שאילתא עט ובשאילת שלום שם מציין שכ\"ה בפסחים ז, ב. ח, א ארבעה פעמים. וכן ברש\"י ותוס' שם. עוד ברש\"י שבת ל, ב ד\"ה קרוי' נר. עוד שם ברש\"י קנא, ב ד\"ה זו נשמה. עוד ברש\"י מ\"ק כה, רע\"א ד\"ה לספר תורה. גם בפי' הרב מברטנורה ריש פסחים ורא\"ש שם. וראה גם ירושלמי שבת פ\"ב, סה\"ו (ובקרבן העדה וטוב ירושלים שם). תוספתא פסחים רפ\"א. תנחומא נח א. פסיקתא רבתי (פיסקא והי' בעת ההיא) פ\"ח, ב. מדרש תהלים פי\"ז, ח. שם פי\"ח, כט. יל\"ש תזריע רמז תקעא. ישעי' רמז תצט. אבן עזרא תהלים ע, ב. משלי יג, ט (וראה גם עה\"פ כאן). רד\"ק צפני' א, יב. חובת הלבבות בהקדמה. מגלה עמוקות אופן לט. שם אופן קץ. של\"ה (שער האותיות אות צ) עב, ב. תושב\"כ (צאן יוסף) שב, א. (ויקרא) שלח, א. (בהעלותך) שנג, ב. (וראה ג\"כ מאמר השני מד, א. פ' תרומה שכו, סע\"ב). מאמרי אדה\"ז תקס\"ב כאן ע' שסא, אתהלך לאזניא ע' צח."],["7040","29","<b>כל הנשמה תהלל י\"ה</b>: תהלים קנ, א."],["7041","30","<b>והחיות רו\"ש</b>: יחזקאל א, יד. ראה לקמן תח, ג. תיג, ד."],["7042","31","<b>ממש. . דאור הנר</b>: בתרס\"ו כאן ליתא."],["7043","32","<b>ויפח באפיו נ\"ח</b>: בראשית ב, ז."],["7044","33","<b>ל' נשמה ענין נשימה</b>: ראה גם לעיל פ' תצוה שיח, ד. וש\"נ."],["7045","34","<b>והרוח תשוב אל האלקי'</b>: קהלת יב, ז."],["7046","35","<b>אכן רוח היא באנוש</b>: איוב לב, ח."],["7047","36","<b>נשמת. . חלק אלוה ממש</b>: ראה לעיל פ' וארא נא, ד הערה 7."],["7048","37","<b>כי הוי' אלקיך אש</b>: ואתחנן ד, כד."],["7049","38","<b>אש. . שגבוה מכולן</b>: ראה לעיל פ' שמות ה, ד הערה 266."],["7050","39","<b>שהרוח כלול מאש ומים</b>: ראה זהר (רע\"מ) בא מג, ב. לעיל פ' שמות כח, א. וש\"נ."],["7051","40","<b>שטבע האש לעלות</b>: ראה רמב\"ם הל' יסודי התורה פ\"ד, ה\"ב. (וראה גם לקמן תח, סע\"ג). לעיל פ' בשלח רלט, ג. וש\"נ."],["7052","41","<b>וטבע המים להתמשך למטה</b>: ראה תענית ז, א."]]],[2300550163,"<b>וזהו</b> שאור הנר<sup data-n=\"7053\">42</sup> עולה ויורד תמיד, כי מה שעולה זהו עלייתו למקורו לאש היסודי כי כל דבר נמשך לשרשו<sup data-n=\"7054\">43</sup> והוא ע\"י בחי' רוח שבאש שמעלהו למעלה (לבחי' אויר הדק שמשם מקור יסוד הרוח שכלול באש היסודי (כמבואר בס' החקירה שאויר זה בלתי נשקל והוא עצם דק וחשוך<sup data-n=\"7055\">44</sup> כו' שממנו מקור התהוות האור ג\"כ (כמ\"ש במ\"א). וגם יש באש דאור הנר או שלהבת ולהב שיורד ונמשך ונאחז למטה דוקא<sup data-n=\"7056\">45</sup> בבחי' ירידה והוא לכלות דבר שנאחז בו או לשאוב השמן שבפתילה וזהו אש השחור שסמוך לפתילה, אך אש השחור הרי אין בו נענוע כ\"כ כמו באש הלבן שלא ינוח ומנענע בעלי' וירידה לנוח על הפתילה כו' (והיינו כשאש השורף מכלה אז אור הלבן עולה בלהב וכאשר ינוח בפתילה יורד אש הלבן וינוח למטה כו' כידוע).\n<b>וכך</b> יובן ממש בנשמה האלקי' שיש בה ב' מדרגות, הא' מה שעולה הנשמה הזאת כמו שעולה ניצוץ לגבי שלהבת ונמשך מאלי' וכאור הנר העולה למעלה כנ\"ל, כך נראה בטבע הניצוץ האלקי<sup data-n=\"7057\">46</sup> שיתעורר לעלות למעלה ליכלל ולידבק באור הוי' במס\"נ בכליון והסתלקות כמו כלתה נפשי<sup data-n=\"7058\">47</sup> כו' בעונג נכסוף לצאת מחומר הגופני כמו אליך הוי' נפשי אשא<sup data-n=\"7059\">48</sup> למעלה, כמו בבחי' התפעלות האהבה לאלקות בבחי' רץ לבך<sup data-n=\"7060\">49</sup> ברוח החיים שבלב כך הוא בנשמה שבמוח כמו כל הנשמה תהלל כו' והיינו מצד <span data-k=\"pg\">תקפו</span> ּ כמו טבע האש לעלות ליסודו כנ\"ל. כך טבע הנשמה לעלות למקור חוצבה שנמשכה משם והוא בשם הוי' ושם אלקים כי כל דבר נמשך לשרשו העצמי' כידוע, ע\"כ זהו כמו טבעיות בניצוץ האלקי שתחפוץ לעלות ולידבק בשרשה באלקים חיים בחשיקה ודביקה באהבה נפלאה כרשפי אש העולה כו' (וכידוע במ\"ש בכנ\"י בכלל רשפיה רשפי אש<sup data-n=\"7061\">50</sup> שלהבת י\"ה כו', ולמעלה היינו בחי' המל' שנק' נה\"ת דקארי תדיר לנה\"ע ולא שכיך<sup data-n=\"7062\">51</sup> כו' כמ\"ש בזוהר ונק' עולת תמיד<sup data-n=\"7063\">52</sup> כו' וכמו להעלות נר תמיד<sup data-n=\"7064\">53</sup> כו'). אך מבואר למעלה בשרש יסוד האש העולה ויורד כו' שזהו בא ע\"י בחי' יסוד הרוח והאור שמתפשט על ידו",[["7053","42","<b>וזהו שאור הנר</b>: ראה גם המשך תרס\"ו כאן ע' קטו."],["7054","43","<b>כל דבר נמשך לשרשו</b>: ראה גם לעיל פ' בא צה, ב. וש\"נ."],["7055","44","<b>יסוד הרוח. . עצם דק וחשוך</b>: ראה גם סידור שער החנוכה רעג, ג ואילך. אמרי בינה שער הציצית י, א. מאמרי אדה\"א ויקרא ח\"ב ע' תנ ואילך וע' תע ואילך ובהנסמן שם. לעיל פ' בשלח רלח, ג."],["7056","45","<b>שנמשך ונאחז למטה דוקא</b>: ראה סה\"ש תשמ\"ט ח\"א ע' 284 בהערות."],["7057","46","<b>הניצוץ האלקי</b>: מכאן (עד לקמן — (וכידוע) הועתק בתרס\"ו ע' קטו (בשינויים קלים)."],["7058","47","<b>כלתה נפשי</b>: תהלים פד, ג."],["7059","48","<b>אליך הוי' נפשי אשא</b>: תהלים כה, א."],["7060","49","<b>רץ לבך</b>: ס\"י פ\"א, מ\"ח. ראה גם לעיל פ' בשלח קסד, ג הערה 23."],["7061","50","<b>רשפיה רשפי אש</b>: שה\"ש ח, ו."],["7062","51","<b>המל' שנק' נה\"ת. . לנה\"ע ולא שכיך</b>: נסמן לעיל בפ' יתרו רעג, ב הערה 160."],["7063","52","<b>המל'. . עולת תמיד</b>: פינחס כח, ו. ראה זהר (רע\"מ) פינחס רנו, ב. לעיל פ' בשלח רמה, ב הערה 14."],["7064","53","<b>להעלות נר תמיד</b>: תצוה כז, כ. אמור כד, ב."]]],[2300550195,"האש כו', ולכך יובן<sup data-n=\"7065\">54</sup> ג\"כ בניצוץ האלקי דגם מה שטבעו לעלות למקורו כו' זהו בא ג\"כ ע\"י בחי' רוח דוקא כי עצם מהות הנשמה היא בבחי' הבל ורוח (רק שהיא בחי' הבל ורוח פנימי' ועצמיות כמו ויפח כו' מאן דנפח מתוכי' ופנימיותו<sup data-n=\"7066\">55</sup> כו' וכן ואתה נפחת בי<sup data-n=\"7067\">56</sup> כו') (משא\"כ רוח פיו שמחי' כל המלאכי'<sup data-n=\"7068\">57</sup> מהבל ודיבור העליון זהו בחי' חיצוני' כידוע) כנ\"ל. וזהו שאנו רואים בחי' רוח ההתעוררות באדם לפרקים שיתעורר מכח עצמו לילך בדרכי ה' ולאהבה ולדבקה בו ית' באמת והתעוררות זו היא שעולה בחי' התפשטות בניצוץ הזה שנק' נשמה שיתפשט בכל כח שבה בשכל ורצון ומדות לעלות למעלה, וגם שזהו מטבעו' הניצוץ כנ\"ל אבל תלוי ברוח המעורר (וכמשל אור הנר באויר והבל טוב יבהיק אורו לעלות כו' ובאויר מעופש וגס יכבה, כך באויר ורוח אלקי' שמתנוסס בנשמה הוא המעוררה לעלות בשלהבת האהבה והחשק הנפלא ביותר כנ\"ל). ולפ\"ע ההתעוררות בבחי' רוח כך יתפשט ההתלהבות האלקי' בנשמה שנק' הוי'<sup data-n=\"7069\">58</sup> ונר אלקי' בבחי' עלי' דוקא כנ\"ל וכמו רוח האדם בלב (בחה\"י) שעולה למעלה בבחי' רץ לבך כו' כנ\"ל, וכן בנפש הוא חום הטבעי' שבלב בשר שבא בתשוקה מורגשת ממש בהבל הגשמי שמורכב בדם כו') כמו צמאה לך נפשי<sup data-n=\"7070\">59</sup> כמה לך בשרי כו'), וכאשר אין רוח התעוררות באדם כלל אזי לא יהי' בניצוץ אלקי התשוקה ברשפי אש רק בהעלם וקטנות מאד עד שעומד ומוכן לבא לכיבוי כו' (ע\"י הבל ורוח גס דחום הטבעי' ברוח הבהמה שיורדת למטה<sup data-n=\"7071\">60</sup> כו').\n<b>ומדרגה</b> הב' בנשמות שנק' ניצוץ שיורד ונמשך וינוח למטה זהו בא ג\"כ ע\"י בחי' רוח המורידו לאור האלקי שבנשמה למטה דוקא כמו ברוח גשמי שמוריד לאור גשמי כו', והיינו כמו שיש ברוח שבלב בחי' שוב אחרי הרצוא בדפק הב' כידוע כך הוא בנשמה שבמוח שמיד שתחשוק לעלות ולצאת במס\"נ כנ\"ל תשוב למטה (וכנשימה שבחוטם שיורד בנקב הב'<sup data-n=\"7072\">61</sup> אעפ\"י שהוא בבחי' מול\"מ היפוך רו\"ש<sup data-n=\"7073\">62</sup> זהו באו\"י מלמעלה למטה ולא באו\"ח כאור הנר). והוא מה שאמר ואתה משמרה בקרבי לבלתי תצא<sup data-n=\"7074\">63</sup> בכליון למעלה כו', שזהו מה שיש בנשמה אלקי' לחפוץ בקרבת אלקי' שיומשך בו כמו שהוא למטה ע\"י תו\"מ <span data-k=\"pg\">1174</span> ּ בבחי' ירידה באו\"כ דוקא היפוך העלי' והסתלקות דאו\"ח (וכמ\"ש במ\"א במ\"ש אני הוי' לא שניתי ואתם ב\"י לא כלית\"ם במס\"נ<sup data-n=\"7075\">64</sup> כו'), לפי שנק'<sup data-n=\"7076\">65</sup> נר הוי' שהוא בבחי' רו\"ש ויש בה כח",[["7065","54","<b>יובן</b>: מכאן (עד לקמן: ההתלהבות האלקי' בנשמה) נעתק בתרס\"ו ע' קטז (בשינויים קלים)."],["7066","55","<b>מאן דנפח מתוכי' ופנימיותו</b>: ראה תניא רפ\"ב ובמ\"מ הגהות והע\"ק לשם. ליקוט פירושים שם. שה\"א צח, א ובהערה 5. ספר הפליאה יב, א. שב שמעתתא בהקדמה אות ג."],["7067","56","<b>ואתה נפחת בי</b>: ברכת אלקי נשמה. ראה גם לעיל פ' וארא עג, ד. וש\"נ."],["7068","57","<b>המלאכי'</b>: בתרס\"ו כאן: הנבראי'."],["7069","58","<b>בנשמה שנק' הוי'</b>: כ\"ה בגוכתי\"ק. יב. אמנם בטז: בנשמה שנק' נר הוי'."],["7070","59","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["7071","60","<b>ברוח הבהמה שיורדת למטה</b>: קהלת ג, כא."],["7072","61","<b>וכנשימה שבחוטם שיורד בנקב הב'</b>: ראה גם הנסמן לעיל פ' תצוה שכא, א."],["7073","62","<b>מול\"מ היפוך רו\"ש</b>: ראה גם לעיל פ' וארא סג, ד. וש\"נ."],["7074","63","<b>ואתה משמרה. . לבלתי תצא</b>: ראה גם לעיל פ' שמות ז, ג. וש\"נ."],["7075","64","<b>אני הוי' לא שניתי. . במס\"נ</b>: מלאכי ג, ו. ראה גם לעיל פ' שמות ז, ג. וש\"נ."],["7076","65","<b>שנק'</b>: מכאן (עד לקמן רוח ה' תניחנו) הועתק בתרס\"ו ע' קיח (בשינויים קלים)."]]],[2300550227,"הירידה והמשכה מלמעלה למטה לגנוז האור בכלי דוקא כמו והאר עינינו בתורתך<sup data-n=\"7077\">66</sup> כו' להיות גילוי אלקות בנפשו כמו שהוא למטה בכלים מכלים שונים ע\"י המצות וכה\"ג (וזהו ואהבת ב\"פ אור<sup data-n=\"7078\">67</sup> או\"י ואו\"ח כא' ברו\"ש דאור הנר הנ\"ל). והנה סיבת ירידה והמשכה זו היפוך העלי' והסתלקות דאו\"ח היינו מבחי' הרוח שיתעורר להמשיך גילוי אלקות בנשמתו, כמו להיות הולך בדרכי ה' בתו\"מ וצדקה וגם במודומ\"ע, וזהו מה שיש ברוח להוריד ולהמשיך האש למטה וכמו רוח ה' תניחנו<sup data-n=\"7079\">68</sup> (כמו שיש בכח הרוח להוריד הגלים דים למטה כו'), וזהו מבחי' שוב דרוח האדם עצמו בלב והיינו נשימה הב' דנשמה בירידה והמשכה למטה כידוע וד\"ל. ואמנם הנה עדיין יש להבין מאין יבא ענין התעוררות הרוח באדם לעורר את הנשמה שבמוח אף בהשגות אלקות ואוי\"ר אם בהעלא' לעלות למעלה או בירידה למטה דוקא כנ\"ל, דודאי א\"א לומר שיבוא זה מצד בחי' הרוח שבלב שנק' רוח האדם העולה למעלה<sup data-n=\"7080\">69</sup> כו' וגם יורד למטה בבחי' רו\"ש כנ\"ל, דאיך אפשר שהרוח שבלב שהוא בחי' מקבל מן הנשמה שבמוח כידוע דבחי' רוח מרכבה לגבי נשמה<sup data-n=\"7081\">70</sup> כו' והחיות שבלב עולה ברו\"ש לגבי המוח לקבל שפע ממנו והמוח ממשיך ללב כו', וכמו שרואים בחוש ההתפעלו' שבלב שאינו נולד רק מבחי' המוחי' דחו\"ב שבראש שזהו הנשמה בכלל ואיך יהי' בכח הרוח חיים שבלב להמשיך כח ועוז בעליון הימנו כו'. ואם מצד שבניצוץ דנשמה עצמה כלולה מיסוד הרוח להיותה בבחי' הבל ורוח דוקא כמ\"ש ויפח באפיו כו' כנ\"ל מאין יבא בנשמה מצד עצמה כח ההתעוררות דרוח שבה להעלותה למעלה כו' ורק לפרקי' לבד כנ\"ל וד\"ל.\n[ב]<b> אך</b><sup data-n=\"7082\">71</sup> הנה שרש סיבת ההתעוררות באדם בניצוץ האלקי שבו לעלות למעלה באהבה ותשוקה או להיפוך לחפוץ בבחי' המשכות אלקות בנפשו מלמעלה למטה שזהו בחי' רו\"ש בכלל כנ\"ל, הנה זהו בא מלמעלה מכח האלקי השורה על אור הנשמה האלקי' כמו כי אתה תאיר נרי<sup data-n=\"7083\">72</sup> כו' (והוא מה שאמר לאהרן אל מול פני המנורה<sup data-n=\"7084\">73</sup> כו' דקאי בנש\"י<sup data-n=\"7085\">74</sup> שנק' נרות הוי' בכלל כנ\"ל). ולפי שהחיות<sup data-n=\"7086\">75</sup> ואור האלקי בכללות הנבראים נמשך בבחי' רו\"ש בעלי' וירידה דוקא כידוע דמ\"ש והחיות רו\"ש קאי גם על חיות האלקי<sup data-n=\"7087\">76</sup> שמחיה כל הנבראים וכל העולמות מאין ליש שהוא בבחי' הגבורות דאו\"ח וכענין רשפי' רשפי אש שלהבת י\"ה שנק' שלהבת י\"ה ממש העולה ויורד וכמ\"ש כי ה'",[["7077","66","<b>והאר עינינו בתורתך</b>: נוסח ברכת ק\"ש."],["7078","67","<b>ואהבת </b>[אולי ניתוסף בגוכתי\"ק: גי']<b> ב\"פ אור</b>: פע\"ח (שער הק\"ש) ש\"ח, פכ\"ג. ראה לעיל פ' וארא סה, ג. וש\"נ."],["7079","68","<b>רוח ה' תניחנו</b>: ישעי' סג, יד."],["7080","69","<b>רוח האדם העולה למעלה</b>: קהלת ג, כב."],["7081","70","<b>רוח מרכבה לגבי נשמה</b>: ראה זהר לך פג, ב."],["7082","71","<b>אך</b>: ראה המשך תרס\"ו ע' קכ."],["7083","72","<b>כי אתה תאיר נרי</b>: תהלים יח, כט."],["7084","73","<b>אל מול פני המנורה</b>: בהעלותך ח, ב."],["7085","74","<b>המנורה. . בנש\"י</b>: ראה מאמרי אדה\"א במדבר ח\"ג ע' תתפא ואילך. וש\"נ."],["7086","75","<b>שהחיות</b>: מכאן ראה תרס\"ו כאן ס\"ע קכ."],["7087","76","<b>והחיות רו\"ש. . חיות האלקי</b>: ראה גם לעיל פ' תצוה שיח, ד. וש\"נ."]]],[2300550258,"אלקיך אש אוכלה כו' וכה\"ג, לכך גם בהמשכות אור וחיות האלקי' בכל בריא' כח הפועל עושה בנפעל שיהי' כמוהו ג\"כ בבחי' רו\"ש וז\"ש והחיות רו\"ש בחיות ושרפי' דבריאה ויצי' כו'. ומה שיש בחי' רו\"ש בכל הברואים עד דצ\"ח דעשי' וכל צבא השמים שאו' שירה<sup data-n=\"7088\">77</sup> בצו\"ח<sup data-n=\"7089\">78</sup> <span data-k=\"pg\">תקפז</span> ּ ברו\"ש דוקא, זהו הכל מכח ושפע אור האלקי עליהם לפי שברוח פיו כל צבאם<sup data-n=\"7090\">79</sup> שהבל זה הוא העולה ויורד כו' ולכך ימצא כח המושך בכל בריא' שיש בה בחי' ביטול הי\"ש לאי\"ן לפי ערך עד מלאכים דבריאה ויצי' כחיות הקדש ושרפי' כו', וגם בחי' הירידה והמשכה למטה כמו דמיון הדפיקו דלבא בצמצום והתפשטות כך יש בעצם כל בריאה ובריאה בחי' צמצום והתפשטות בכלל ופרט כו'. וזהו ג\"כ הטעם שיש בנה\"א ששרשה משם הוי' כנ\"ל שיהי' בה בחי' רו\"ש, ואמנם אין זה בא רק ע\"פ הארה האלקי' שמתעורר על הנשמה, והוא מה שאנו רואים<sup data-n=\"7091\">80</sup> בחוש שבכל בקר אור יש התעוררות<sup data-n=\"7092\">81</sup> פתאום בכל נשמה שמתעוררת לעבודת ה' לילך ולידבק בה' אחד באוי\"ר באמת ולא ילך אחר ההבל כו' ולא יחפוץ בחיים הגשמיי' להתגאל בתאוות זרות כו' אלא ימאס בהן ויחפוץ רק בקרבת אלקי' לבדו כענין מי לי בשמים ועמך<sup data-n=\"7093\">83</sup> כו' כלה<sup data-n=\"7094\">84</sup> שארי<sup data-n=\"7095\">82</sup> כו'. והתעוררות כזאת תמצא בכל אדם לפי ערכו בכל עת ושעת הכושר למעלה שיומשך עליו רוח ממרום פתאום לעוררו בזה ברוח החיים שבלבו והוא מה שיתעורר לבבו פתאום בלי הכנה מקודם כלל, דאם הי' לו הכנה בלבו בהתעוררות מצד עצמו ודאי רוח אייתי רוח<sup data-n=\"7096\">85</sup> ואמשיך רוח להמשיך עליו מלמעלה לעוררו, אבל כשמתעורר פתאום בלא הכנת עצמו כלל זהו אות ומופת גמור שמלמעלה מעוררים אותו, וכמו שיש ב\"ק בכלל שמכריז כו', וכן במלאכים יש כח אלקי שמעוררם לעלות. והיינו מטעם הנ\"ל שנמשך מבחי' הגבורות דאו\"ח שבכח אלקי בחי' מל' מקור הכל כו' שעי\"ז נמשך כח התעוררות בכל הברואי' בבחי' עלי' דאו\"ח בביטול היש לאין כו' כנ\"ל, וכך יומשך בנשמות שנק' נר הוי' ממש שיתעוררו ממילא לעלות למעלה כניצוץ העולה מאליה ליכלל בשלהבת רק שנק' שלהבת י\"ה ממש מאחר שנק' נר הוי' ממש (וכמו שא' לאהרן בהעלותך את הנרות<sup data-n=\"7097\">86</sup> שיעוררם באה\"ר העליונה (כמ\"ש במ\"א).\n<b>ונמצא</b><sup data-n=\"7098\">87</sup> מובן מזה דגם שיש בטבע בכל ניצוץ אלקי לעלות למעלה ליכלל ולהדבק במקור חוצבו באלקי' כניצוץ שעולה ונכללת בשלהבת כי כל דבר נמשך לשרשו מעצמו וכן א' והרוח תשוב אל האלקי' אשר נתנה כו', אך בחי' התעוררות",[["7088","77","<b>וכל צבא השמים שאו' שירה</b>: ראה מאמרי אדה\"א בראשית ע' נז. וש\"נ. שה\"א סא, ב ובהנסמן לשם."],["7089","78","<b>בצו\"ח</b>: בצורה וחומר."],["7090","79","<b>שברוח פיו כל צבאם</b>: תהלים לג, ו."],["7091","80","<b>שאנו רואים</b>: מכאן (עד לקמן: כח אלקי שמעוררם לעלות) הועתק בתרס\"ו ע' קכא (בשינויים קלים)."],["7092","81","<b>שבכל בקר. . התעוררות</b>: ראה בסמוך הערה 89."],["7093","83","<b>מי לי בשמים ועמך</b>: תהלים עג, כה."],["7094","84","<b>כלה שארי</b>: תהלים שם, כו."],["7095","82","<b>כענין. . כלה שארי</b>: בתרס\"ו כאן ליתא."],["7096","85","<b>רוח אייתי רוח</b>: נסמן לעיל פ' יתרו רנא, א."],["7097","86","<b>בהעלותך את הנרות</b>: בהעלותך ח, ב. ראה הערה 74."],["7098","87","<b>ונמצא</b>: ראה המשך תרס\"ו כאן ע' קכב."]]],[2300550288,"זו לעלות נמשך לה עזר וסיוע לעזור לטבעיו' שלה והוא כמו כח הרוח שיעלה לאש כנ\"ל, וזהו עד יערה עלינו רוח ממרום<sup data-n=\"7099\">88</sup> והוא כמו בשעת הכושר ועת רצון למעלה וכשבת ויו\"ט וכה\"ג. וז\"ש חדשים לבקרי\"ם רבה אמונתך<sup data-n=\"7100\">89</sup> שבכל בקר ובקר מתחדש כח הניצוץ אלקי לעוררו בהעלא' למעלה בכלל וגם בפרט והוא ע\"י בחי' האמונה הפשוטה ועצמי' שמתרבה בנה\"א ונמשך<sup data-n=\"7101\">*90</sup> כמו ע\"י הטלית<sup data-n=\"7102\">90</sup> כידוע, וכמ\"ש וצדיק באמונת\"ו יחי'<sup data-n=\"7103\">91</sup> בגילוי אור וחיות שממנו מתפשט בשכל ומדות ממילא כו' (וכמ\"ש במ\"א). אך הנה מובן מכל זה שגם מה שהאדם יומשך בדעתו ולבו אחרי ה' להתפעל באוי\"ר שכליי' כמו בק\"ש ותפלה אין זה בא מכח עצמו כלל כ\"א מצד בחי' כח ההתעוררו' שבאה מלמעלה על נשמתו בבחי' מקיף (דמזלי' חזי<sup data-n=\"7104\">92</sup> ופועל התעוררות פתאום במוחו ולבו כנ\"ל), ע\"י כח הזה דוקא הוא <span data-k=\"pg\">1176</span> ּ שנמשך ממילא לעבודת ה' בתפלה ואף אחר התפלה לעשות מצות ולעסוק בתורה וגמ\"ח כו', שכל זה נמשך מכח העליון האלקי שנמשך בנשמתו עד שיכלה כח המעורר הזה או יכלה כח התפעלות שלו באוי\"ר וכ\"ש בהילוך בדרכי ה' בתו\"מ כל היום. וא\"כ אין זה נק' בחי' עבודה כלל שגם מה שעובד ה' בתו\"מ ותפלה אין זה מכח עצמו (רק נק' עבודת מתנה<sup data-n=\"7105\">93</sup> כו' שניתן כח לעבודה זו במתנה כו') (וזהו כמו התינוק הקטן שהולך וגדול הוא המוליכו מאחוריו כך בצלם יתהלך איש<sup data-n=\"7106\">94</sup> במזל ומקיף דנר\"נ שמתעורר מלמעלה כנ\"ל יעורר גם לשכל ומדות עד מוד\"מ בהרהור תשובה ומע\"ט כו'). אך א\"כ לפ\"ז בטלה ענין הבחירה באדם דאין לו בחירה לבחור בטוב מצד עצמו כלל רק ממה שנתעורר מכח האלקי, והעיקר הוא הבחירה שמצד עצמו דוקא וע\"ז הוסד כל יסוד התו\"מ כמ\"ש ראה נתתי כו' ובחרת בחיים<sup data-n=\"7107\">95</sup> כו' כידוע.\n<b>ואמנם</b> הנה באמת יש עוד מדריג' ב' בנשמת האדם שהוא היפוך ענין הנ\"ל, והיינו כמו שמבואר למעלה בענין רו\"ש דאור הנר דהנה גם מה שחוזר האור ויורד ונח בפתילה זהו ג\"כ מכח המקור דאש היסודי הוא בא על האור הזה שיומשך וינוח בפתילה להדליקו ולא יעלה ויסתלק למעלה, דאם הי' בטבע האש רק לעלות ולא ירד כלל הי' עולה ומסתלק לגמרי ולא הי' מציאות אור לגמרי והרי א' יהי אור ויהי אור<sup data-n=\"7108\">96</sup> מוכרח שיש מקור מוצא להיות התהוות מציאות האור שיהי' במציאות במהו' בפ\"ע דוקא כו'. והיינו מה שיש בטבע האש ואור לירד למטה וליפול על כל דבר להדליקו כו' כמו ותפול אש ה' מן השמים<sup data-n=\"7109\">97</sup> (והוא כמו אש שותה<sup data-n=\"7110\">98</sup> שזהו מבחי' מים שבאש שבא",[["7099","88","<b>עד יערה עלינו רוח ממרום</b>: ישעי' לב, טו."],["7100","89","<b>חדשים לבקרי\"ם רבה אמונתך</b>: איכה ג, כג. ראה גם לעיל פ' בא צג, ד. וש\"נ."],["7101","*90","<b>בנה\"א ונמשך</b>: אולי כתוב בגוכתי\"ק: ונמשך בנה\"א."],["7102","90","<b>ע\"י הטלית</b>: ראה גם לקמן תיט, ד. תלב, ב. מאמרי אדה\"א בראשית ע' שצד. שמות ח\"ב ע' תרטו. במדבר ח\"ד ס\"ע א'שיג ואילך."],["7103","91","<b>וצדיק באמונת\"ו יחי'</b>: חבקוק ב, ד. ראה גם תניא פל\"ג. לעיל פ' תצוה שמה, ב."],["7104","92","<b>דמזלי' חזי</b>: מגילה ג, א."],["7105","93","<b>עבודת מתנה</b>: קרח יח, ז."],["7106","94","<b>בצלם יתהלך איש</b>: ראה גם לעיל פ' תצוה שלט, ד. וש\"נ."],["7107","95","<b>ראה נתתי כו' ובחרת בחיים</b>: נצבים ל, טו. יט."],["7108","96","<b>יהי אור ויהי אור</b>: בראשית א, ג."],["7109","97","<b>ותפול אש ה' מן השמים</b>: מל\"א יח, לח [ושם התיבות: מן השמים, ליתא]. מל\"ב א, יב [ושם: ותרד אש אלקים]. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תשפז. לעיל פ' בשלח רלח, ג."],["7110","98","<b>אש שותה</b>: ראה יומא כא, ב. לקמן תח, ג. תט, ד. לעיל פ' בשלח רלח, ג."]]],[2300550315,"בבחי' התפשטות דוקא), וכמו שיש ברוח כח היורד ומתפשט למטה כנ\"ל), והיינו מה שאור הנר מתיישב בפתילה ושמן וכה\"ג שזהו מהמשכת כח אש היסודי עליו שיחזור למטה ויהי' במציאות אור בכלי כו'. וזהו ג\"כ באש דשרפי' וחיות הרוחני' במרכבה העליונה שיש בהן בחי' ירידה והמשכה למטה ג\"כ כמ\"ש והחיות רו\"ש ובחי' שוב היינו מה שתנוח הרוח שבהם ויתיישב בכלי דוקא, ואמנם בחי' השוב הזה בא בהם מכח האלקי דוקא שנמשך עליהם בבחי' ירידה והמשכה אחר ההעלאה דרצוא דוקא כי רוח אייתי רוח ואמשיך רוח בהיפוך כו' וד\"ל.\n<b>וכך</b> יובן ג\"כ בנשמות שנק' נר הוי' או נר אלקי', והוא מדרג' הב' באדם שאחרי ההתעוררות הבאה מלמעלה לעוררו לעלות ברצוא בתשוקה לצאת מן הכלי לגמרי כנ\"ל אח\"ז יומשך היפוך זה והוא בחי' השוב, דזהו מה שיש בכח הנשמה להמשיך האור בכלי דוקא בבחי' יריד' והמשכו' אלקות בעצמו ולא יעלה למעלה כלל (כנ\"ל במ\"ש ואתה משמרה בקרבי כו' ואתם ב\"י לא כליתם). והיינו מה<sup data-n=\"7111\">99</sup> שאנו רואים שימצא באדם כח וחיזוק מצד עצמו דוקא להיות הולך בדרכי ה' בתו\"מ כל היום, דהיינו שלא יוכל למצוא מנוח לנפשו אם לא שיעסוק ויעבוד איזה ענין עבודה אלקי' באופן המשכת <span data-k=\"pg\">תקפח</span> ּ גילוי אור אלקי להתלבש בדבור או מעשה דוקא כמו בדיבור בד\"ת ומעשה הצדקה ומצות זולתה בזאת דוקא תנוח רוחו ודעתו ותתנחם נפשו ואם לאו לא תנוח רוחו ודעתו כלל באהבה ודביקות לעלות למעלה כו', והוא מצד בחי' השפלות וענוה בבחי' אי\"ן ומ\"ה בעצם שהוא היפוך מיש לבחי' העלאה דרצוא שהוא בבחי' יש ודבר כו'. והנה הגם שבחי' דשוב זה בנשמ' באה ג\"כ מכח העליון האלקי שיופיע עלי' במציאות ומהות בפ\"ע כמו למעלה במלאכי' כנ\"ל, מ\"מ ניתן כח זה בנשמה שיהי' לה מצד עצמה וכחה דוקא לילך בדרכי ה'. ואעפ\"י שאין התעוררות מלמעלה לעוררו בזה כלל אלא רק מכח הכנת עצמו שיוכל בכח עצמו ובחירתו להתחזק ברצון זה לעבודה האלקי' גם בק\"ש ותפלה לבא לבחי' התפעלות פנימי' השכל שבמוח ואוי\"ר בלב בפנימי' הכל הוא מצד כח עצמות הנשמה דוקא, והיינו כמו ע\"י עוצם יגיעתו במוח בינה להשיג גדולו' הבורא ית' איך שבורא מאין ליש ויתפעל במוח ואח\"כ יתפעל באהבה בלב ונק' עבודה ויגיעה כמ\"ש בזוהר שנק' פולחנ\"א דרחימותא<sup data-n=\"7112\">100</sup> כו' וכמ\"ש ואהבת את כו' ל' ציווי<sup data-n=\"7113\">101</sup> ואזהרה, וכן בא' שמע ישראל<sup data-n=\"7114\">102</sup> שישמע היטב בהשגה דבינה שכל זה ע\"י יגיעה רבה במוח ולב כידוע שתלוי זה בבחירה שבאדם מצד עצמו דוקא, ואם אין בו התעוררות בחירה זו לטוב לא יחזק עצמו בעבודה שבלב ומוח בתפלה כלל",[["7111","99","<b>מה</b>: מכאן (עד לקמן לעלות למעלה כו') הועתק בתרס\"ו ע' קנב."],["7112","100","<b>בזוהר שנק' פולחנ\"א דרחימותא</b>: נסמן לעיל פ' תצוה שסג, ד הערה 55."],["7113","101","<b>ואהבת את. . ציווי</b>: ואתחנן ו, ה. ראה מאמרי אדה\"ז תקס\"ו ע' קסג. תו\"א תשא פו, ג. לקו\"ת סוכות פ, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תשלו ואילך. הנחות תקע\"ז ע' שטז. תו\"ח נח מט, ג."],["7114","102","<b>שמע ישראל</b>: ואתחנן ו, ד."]]],[2300550340,"ויהי' הכל בחיצוני' ובקרירות מן השפה ולחוץ לבד כמו בפיו ושפתיו כבדוני<sup data-n=\"7115\">103</sup> ולבו רחק ממני כו', ולפ\"ז גם בחי' פנימי' הכוונה במוח ולב בא מכח עצמות הנשמה. וכמ\"כ בעבודה האלקי' כל היום בתו\"מ שיעסוק במדו\"מ ודאי אינו בא רק ע\"י כח עצמו שמתחזק בעצמו ביותר להיות הולך בדרכי ה' בתו\"מ וכו', וכמו שאמר באברהם התהלך לפני<sup data-n=\"7116\">104</sup> כו' שיתהלך מכח עצמו דוקא, וא' בזוהר ע\"פ ואברהם זקן בא בימים<sup data-n=\"7117\">105</sup> באינון יומין עילאין שהן בחי' לבושי' דמצות כו' דעובדוהי קריבו לי' מדרגא לדרגא כו' כענין שאמר בו הלוך ונסוע<sup data-n=\"7118\">106</sup> כו'. והענין הוא דמע\"ט שלו בהשתדלות ויגיעה רבה בכל כחו עוז לילך בדרכי ה' ומצותיו כמ\"ש אשר שמע בקולי<sup data-n=\"7119\">107</sup> כו' ובעבודה שבלב באה\"ר ונפלאה בתפלתו במס\"נ, ומעשיו הטובי' כל היום במו\"ד ומעשה הצדקה קריבו לי' לנשמתו להיות עולה בעילוי אחר עילוי מדרגא לדרגא עליונה יותר בקרבת אלקי', שזהו כמו ענין עליות הנשמות בג\"ע מדרגא לדרגא מהיכל להיכל כו' מעשי' ליצי' ומיצי' לבריאה עד בחי' אצי' ולמעלה לאשתאבא בגופא דמלכא<sup data-n=\"7120\">109</sup> ממש כמ\"ש והי' מדי חדש<sup data-n=\"7121\">110</sup> ושבת<sup data-n=\"7122\">108</sup> כו' כנודע. אמנם כל זה הי' דוקא מצד טוב עבודתו מכח עצמו, וכך הוא בכל ניצוץ אלקי לפ\"ע יגיעתו ועבודתו בכח עצמו בתפלה ותו\"מ כך יעלה בעילוי ברום המעלות להתקרב לפני ה' בדביקות והתקשרות אמיתי' יותר כו', ולא שטוב העבודה האלקי' באה מכח שפע האלקי' על הנשמה רק שמעשה הטוב שמצד הבחירה דוקא הוא שגרם להיו' תוס' גילוי אור אלקי בנפשו לעלות במדריג' מיום ליום כנ\"ל באברהם וד\"ל.\n<span data-k=\"pg\">1178</span> ּ<b>ועכ\"ז</b> הנה גם כח וחיזוק הזה שימצא באדם לילך מכח עצמו בעבודה שבלב כו' בא יבא מכח האלקי שבא מלמעלה בבחי' שוב כנ\"ל, וזהו ענין קבלת מל' שמים שנמשך ממל' דאצי' בכל העולמות והוא כמו בחי' היראה ופחד אלקי' שנמשך למלאכי' שמחמת זה יקבלו עליהם עומ\"ש שלימה וכמו וכולם מקבלים<sup data-n=\"7123\">111</sup> כו' שמזה יש בעצמם כח וחיזוק להיות בביטול הי\"ש לאין בהילוך דרך הוי' כמו לומר קדוש הוי'<sup data-n=\"7124\">112</sup> ברוך הוי'<sup data-n=\"7125\">113</sup> כו'. וכך הוא ג\"כ בנשמות שנמשך עליהם עול מ\"ש העליונה בבחי' יראה ופחד אלקי' כמו ע\"י עטיפת הטלית כידוע שעי\"ז ימצא אח\"כ בהם ענין הכח וחיזוק שמצד עצמו לעבודה האלקי' בפנימי' וחיצוני' לבטל<sup data-n=\"7126\">114</sup> כל רצונו מפני רצון ה' בתו\"מ כו' וכמו העבד שקיבל עליו עול אדונו לעבוד אותו ואז ע\"י קבלה זו נעשה כח וחיזוק בעצמו לעבודתו לבטל א\"ע לפניו בכל אשר יגזור אומר כו' (כמשי\"ת) וד\"ל.",[["7115","103","<b>בפיו ושפתיו כבדוני</b>: ישעי' כט, יג [ושם: ובשפתיו — ראה גם לעיל קח, ב. וש\"נ]."],["7116","104","<b>התהלך לפני</b>: לך יז, א."],["7117","105","<b>ואברהם זקן בא בימים</b>: נסמן לעיל פ' משפטים רפה, ב."],["7118","106","<b>הלוך ונסוע</b>: לך יב, ט."],["7119","107","<b>אשר שמע בקולי</b>: תולדות כו, ה."],["7120","109","<b>לאשתאבא בגופא דמלכא</b>: נסמן לעיל פ' יתרו רסט, ד."],["7121","110","<b>והי' מדי חדש ושבת</b>: ישעי' סו, כג [ושם: בחדשו ומדי שבת — ראה גם לעיל פ' שמות לג, א. וש\"נ]."],["7122","108","<b>עליות הנשמות. . מדי חדש ושבת</b>: ראה גם לעיל פ' שמות לה, ב. וש\"נ."],["7123","111","<b>וכולם מקבלים</b>: ברכת יוצר."],["7124","112","<b>קדוש הוי'</b>: ישעי' ו, ג."],["7125","113","<b>ברוך הוי'</b>: יחזקאל ג, יב [בדילוג]."],["7126","114","<b>לבטל</b>: מכאן (עד בסמוך אשר יגזור אומר כו') נעתק בהמשך תרס\"ו ע' קנה."]]],[2300550364,"[ג<sup data-n=\"7127\">*115</sup> ] וזהו שאמר ושבתם וראיתם<sup data-n=\"7128\">115</sup> בין כו' בין עובד אלקים לאשר לא עבדו דמשמע שאינו רשע ומקיים המצות ואינו עובר על ל\"ת [ו]מ\"מ אינו נק' עובד אלקי' כלל וזה פלא כו'. אך הנה ידוע בזהר שיש ב' מדרגות בחי' בן ובחי' עבד<sup data-n=\"7129\">116</sup> דבחי' בן זהו כמו הבן אל אביו שעובדו<sup data-n=\"7130\">117</sup> ג\"כ עבודה תמה בכל לבו ונפשו, אך זהו רק מצד שנמשך הבן מן האב שהולידו והוא נחשב מעצמותו כמאמר דברא כרעא דאבוה<sup data-n=\"7131\">118</sup> כו' ולכך נמשך אליו באהבה וחשק תמיד כי כל דבר נמשך לשרשו, ולזאת גם במה שיצוה עליו לעבוד ולעשות אין זה עליו לטורח ומשא כלל אלא יעבוד ויעשה רצונו בנחת ושמחה יותר ממה שעובד לצורך עצמו כמו שאמר [כ]ברא דאשתדל בתר אבוה[י] יתיר מגרמי'<sup data-n=\"7132\">119</sup> כו'. וכך יובן דנש\"י שנק' בנים כמ\"ש בנים אתם להוי'<sup data-n=\"7133\">120</sup> כו' בני בכורי ישראל<sup data-n=\"7134\">121</sup> וכה\"ג והוא מצד שרש נש\"י למעלה שנמשך מפנימי' ועצמות דא\"ס בחכ' שבמוח כו' וכמו כי אתה אבינו<sup data-n=\"7135\">122</sup> ממש, ולזאת גם בבחי' העבודה האלקי' כמו בק\"ש ותפלה ותו\"מ כל היום לא תכבד [עליו] כלל עבודה זו ונמשך כמו טבע בנפשם האלקי' לילך בדרך ה' בלי לנטות ימין ושמאל בלא עול ומשא כלל, וכמו<sup data-n=\"7136\">123</sup> שיש בבן בטבע לימשך אחר אביו באה\"ר ובעבודה תמה לעשות רצונו בשמחה כו' כנ\"ל. רק<sup data-n=\"7137\">124</sup> נש\"י כמו טבע בנפשם לימשך בהתלהבות אה\"ר [כ]ניצוץ הנמשך לשרשו ושמחה בעבודה שבמוח ולב בתפלה ותו\"מ בשמחה ש\"מ לעשות נח\"ר לאביהם שבשמים, והיינו מה שנמשך ג\"כ כח ועוז משפע האלקי' לעורר בהם את האהבה והתשוקה האלקי' לצאת מכלי הגבלת' לגמרי כנ\"ל, וכמו שמבואר למעלה שזהו מה שמתעורר האדם פתאום לעבודת ה' בלי הכנה מקודם כלל כו'.\n<b>אבל</b> הנה יש עוד מדרגה שנק' בחי' עבד והוא ג\"כ בנש\"י מצד הגופי' כמ\"ש כי לי בנ\"י עבדים<sup data-n=\"7138\">125</sup> כו' והוא כמו מעשה העבד לאדון, שאנו רואים שעיקר ענין העבדו' אינו רק בחי' עול גדול שמוטל עליו מאימת האדון לעבוד כל עבודה קשה וכבידה ביותר אף שמאד נגד כחו ורצונו כו', ותכבד עליו העבודה עד שתקצר רוחו ונפשו עליו וגם בלילה לא ינוח בשינה ויכביד עליו עולו עול ברזל לעבודתו כמו להקיצו משינתו המועטת לעבודה ולא יתננו השב <span data-k=\"pg\">תקפט</span> ּ רוחו כלל, עכ\"ז יקבל העבד עבודה זו מצד עול האדון, אע\"פ שבע\"כ הוא ונעשה אצלו כמו טבע בנפשו ממש לשאת העול והמשא והטורח הגדול בעבודה קשה כמו [שהורגל] השור לעול וחמור למשא וקבלת העול הזה נקנה אצל העבד",[["7127","*115","<b>ג</b>: יב: ב. [ג' נרשם לקמן על יד הערה *276]."],["7128","115","<b>ושבתם וראיתם</b>: מלאכי ג, יח. ראה לקמן בפנים על יד הערה 151. תרס\"ו ע' קנה. וע' שיג ואילך."],["7129","116","<b>ב' מדרגות בחי' בן ובחי' עבד</b>: ראה זהר (רע\"מ) אמור קיא, ב."],["7130","117","<b>שעובדו</b>: מכאן (עד לקמן עול ומשא כלל) נעתק בתרס\"ו ע' שט (בשינויים קלים)."],["7131","118","<b>דברא כרעא דאבוה</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד, פ\"א בשם רז\"ל. מאו\"א מערכת ירך אות לב: ואחז\"ל. של\"ה (מס' פסחים מצה שמורה) קסט, סע\"א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שדמ ובהנסמן במ\"מ לשם. מאמרי אדה\"א שמות ח\"ב ע' תקצה. וש\"נ. קונטרסים ע' שלט. וש\"נ."],["7132","119","<b>[כ]ברא דאשתדל. . מגרמי'</b>: ראה זהר (רע\"מ) תצא רפא, סע\"א."],["7133","120","<b>בנים אתם להוי'</b>: פ' ראה יד, א."],["7134","121","<b>בני בכורי ישראל</b>: שמות ד, כב."],["7135","122","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["7136","123","<b>וכמו</b>: מכאן (עד לקמן בלו\"נ לאדונו) נעתק בהמשך תרס\"ו ע' שט (בשינויים קלים)."],["7137","124","<b>רק</b>: טז: כך."],["7138","125","<b>כי לי בנ\"י עבדים</b>: בהר כה, נה. ראה לקמן שצז, ג."]]],[2300550384,"כטבעיות ממש, כי מתבטל מכל עצם מהותו כאילו אינו במציאות בעולם ואינו נברא בעולם רק למלאכה ושירות לאדונו לפי שנחשב כרכושו וקנין כספו כו'. הנה ודאי עבד כזה אין לו שמחה ונח\"ר לעצמו כלל בעבודתו בעול קשה כזה, ועכ\"ז מה ש[י]ק[ו]בל לרצון לאדונו מכל טורח עבודתו זהו כל חיותו ומציאותו שלזה נברא ונוצר ואין לו דבר עצמו זולת זאת, כי אין לו מקום ומציאות ומהות בפ\"ע כלל כי נרצה<sup data-n=\"7139\">126</sup> ונקנה נפשו וגופו וכאש\"ל<sup data-n=\"7140\">127</sup> לאדונו דגם מה שקנה ומצא והרויח הכל לרבו כידוע.\n<b>ואמנם</b> יש בחי' עבד שעבודתו מאהבה ותענוג ושמחה דוקא והוא ששמח ומתענג בעבודתו מצד גודל אהבתו והתקשרותו בלו\"נ<sup data-n=\"7141\">128</sup> לאדונו וע\"כ שיעבד<sup data-n=\"7142\">129</sup> עצמו וגופו לשרתו בשירות השייך לכבוד האדון ולמזונו ושולחנו והנהגת ביתו וכל אשר לאדון ברכושו וכלי כסף וזהב וכל הון ביתו נמשך<sup data-n=\"7143\">130</sup> לידו כמו אליעזר עבד אברהם שהי' זקן ביתו מושל בכאש\"ל<sup data-n=\"7144\">131</sup> כו', וכיוסף שהי' מצליח בבית אדונו<sup data-n=\"7145\">132</sup> שיש מעבד כזה ברכה מרובה בבית האדון בכפלי כפלי[י]ם, הרי עבד כזה אינו עובד בעול ומשא כלל, רק מאה\"ר שחפץ בגדולת ועושר והצלחת האדון ובשלוותו להיות לו נח\"ר ותענוג, ע\"כ משתדל בעצמו בכל כח ועוז ותעצומות הן בשירות שמשרתו לצורך גופו ומזונו ולבושו ומשקיהו כמו לערוך שולחן בכל מעדני טוב שעשה לו ולנקות לבושיו וליפותם<sup data-n=\"7146\">133</sup> ולתקן יופי והידור בכלי יקר שלו<sup data-n=\"7147\">134</sup> ולהשקותו מיין הטוב בכלי יקר<sup data-n=\"7148\">135</sup> וכה\"ג שיהי' מקבל נח\"ר ועונג מטוב תיקונו בכל אלה וכה\"ג, הרי ודאי כל עבודת העבד היקר כזה רק בזריזות ושמחה ותענוג גדול בכל אשר עושה לנח\"ר לאדונו שמקבל מזה עונג ושמחה ואין משא כלל וכלל בעבדו' שלו כו' מצד עוצם פנימי' התקשרות[ו] באה\"ר שבעצמות נפשו שמחמת זה הוא שמסר א\"ע לעבודתו לטובתו בכל לו\"נ, וכן להתאמץ בכל כח שכלו ומדותיו בהנהגת בית האדון ובמלאכתו להרויח למצוא תוס' ברכה בבית ובשדה כו' עד שיוכל להיות שמטוב הצלחת העבד היקר כזה שהשליך נפשו מנגד רק להוסיף ברכה והצלחה בבית האדון, וזה כל מגמתו יותר מאדון ובעה\"ב עצמו שיתעשר ויתגדל האדון בכל הון יקר וגדולה יתירה שלא הי' ביכולת האדון מכח עצמו ומזלו כלל ([ו]כיוסף שהי' איש מצליח ונתברך אדונו ממלאכתו ביותר (וכה\"ג נא' במשיח ישכי\"ל עבד\"י<sup data-n=\"7149\">136</sup> פי' ישכי\"ל יצליח<sup data-n=\"7150\">137</sup> עד כי גבה מאד כו' (כמשי\"ת).",[["7139","126","<b>נרצה</b>: טזיז ותרס\"ו: נרצע."],["7140","127","<b>וכאש\"ל</b>: טז: וכל אשר לו."],["7141","128","<b>בלו\"נ</b>: בלב ונפש."],["7142","129","<b>שיעבד</b>: מכאן (עד לקמן שצו, ג תורה ומצות כל היום) נעתק בתרס\"ו ע' שי (בשינויים קלים)."],["7143","130","<b>נמשך</b>: טזיז: נמסר. בתרס\"ו כאן: נותן."],["7144","131","<b>אליעזר. . זקן ביתו מושל בכאש\"ל</b>: ח\"ש כד, ב."],["7145","132","<b>וכיוסף שהי' מצליח בבית אדונו</b>: וישב לט, ב ואילך."],["7146","133","<b>וליפותם</b>: בהמשך תרס\"ו כאן באה הגה ארוכה — בנמשל."],["7147","134","<b>שלו</b>: שם ע' שיא באה כאן הגה."],["7148","135","<b>יקר</b>: שם באה כאן הגה."],["7149","136","<b>במשיח ישכי\"ל עבד\"י</b>: ישעי' נב, יג. ראה מאמרי אדה\"א ויקרא ח\"א ע' קיב. וש\"נ."],["7150","137","<b>פי' ישכי\"ל יצליח</b>: ת\"י ומפרשים לישעי' שם."]]],[2300550401,"<b>והנה</b> הדוגמא מכ\"ז בב' מיני עבד הנ\"ל יובן ג\"כ בעבודה האלקי', וכמו שנק' בנ\"י עבדי\"ם מצד הגופי' שצריכים לקבל עליהם עומ\"ש לעבודה האלקי' וכמו שאו' אבינו מלכינ\"ו<sup data-n=\"7151\">138</sup> כו' ונק' מלך ישראל וגואלו<sup data-n=\"7152\">139</sup> כו' וכה\"ג, הנה קבלת עול זה הוא כמו קבלת העבד הפשוט לאדונו [ה]נ\"ל שאין עיקר עבודתו רק בעול גדול לסבול כל עבודה קשה כו' אף שמאד נגד רצונו כנ\"ל, מ\"מ נעשה זה כטבע אצלו מצד עול העבדו' כו', וכך הוא בכל קבלת עומ\"ש <span data-k=\"pg\">1180</span> ּ מצד יראה אלקי' שזהו שנק' עובד אלקי' דוקא, דאלקים ל' שררה<sup data-n=\"7153\">140</sup> ואדנות שמקבל עליו עול אדנות וממשלה האלקי' מצד אימה ופחד אלקי' על נפשו שמחמת זה משעבד כל גופו הגשמי להיות גם הוא כמו שור לעול ממש, והיינו לייגע עצמו וכחו האנושי בהיפוך מטבעו ורצונו החומרי דהיינו רק לילך בעול תורה ומצות כל היום ולייגע עצמו במוחו ולבו בתפלה לבטל כל מ\"ז ורצון [זר] כו'. ואע\"פ שזהו מאד נגד טבעו ולעזוב דבר שהמשיך נפשו לזה, מ\"מ יבטל רצונו וטבעו בע\"כ בדרך כפי' והכרח להתיש כח הרע שבלבו ולעצור<sup data-n=\"7154\">141</sup> רוח תאוותו אף במ[ו]\"ד מצד עומ\"ש שקיבל עליו שימנענו מכל רע בפו\"מ עכ\"פ ומכריחו לעבודה האלקי' ב[ו]עשה טוב בתפלה ותו\"מ וצדקה, אע\"פ שתכבד עליו העבודה ותקצר רוחו בעמלו כי לא ימצא נח\"ר ועונג ומעלה לעצמו בזה כלל, כי הכל עושה רק לכבוד קונו ואדון כל ישים נפשו כשור לעול ויט שכמו לסבול<sup data-n=\"7155\">142</sup> עול תורה ומצות אף בע\"כ כו', כי נתן עליו עומ\"ש כעול ברזל לעבודה האלקי' מחמת שנקנה ונרצה בכל עצם מהותו לקונו<sup data-n=\"7156\">143</sup> ואין לו מציאות ומהות בפ\"ע כלל. ולכך ודאי עבד כזה אין לו רק לעשות מה שמוטל עליו בעול ואין לו שמחה ועונג כלל בעבודתו, אדרבה הוא תמיד בשפלות ונבזה בעיניו בלי מהות יש ודבר כלל אף שישלים עבודתו בכי טוב בכל אשר מוטל עליו כרצון האדם<sup data-n=\"7157\">144</sup> הרי נק' עבד לרבו ואין לו לעצמו כלום, ואף מה שיקבל פרס וירויח הכל לרבו כנ\"ל, וזהו אל תהיו כעבדים המשמשי' ע\"מ לקבל פרס<sup data-n=\"7158\">145</sup> כו' וד\"ל. ועל בחי' עבד כזה אמר דוד שמח נפש עבדך<sup data-n=\"7159\">146</sup> כו', כי צריך הוא שישמחנו האדון כי אין לו שמחה ועונג בעבודתו ויגיעתו כלל וכלל, ולכך אמר שמח נפש עבדך כו'<sup data-n=\"7160\">147</sup> כי אליך הוי' נפשי אשא<sup data-n=\"7161\">148</sup> שהוא מס\"נ גם בעול כזה להשליך נפשו לגמרי לבטל כל רצונו וטבעו לייגע כל נפשו בעבודה שזהו כמו שנושא את נפשו ממש ומוסר א\"ע בכל כו' להיות נרצע לעבד לעולם כו'. וזהו שנק' עובד אלקים בעול כבד שזהו כשכל עבודתו הוא למעלה מכפי טבעו ורגילותו כמו בעמל<sup data-n=\"7162\">149</sup> תורה",[["7151","138","<b>אבינו מלכינ\"ו</b>: נוסח התפלה. ראה גם לעיל פ' משפטים רפה, ב."],["7152","139","<b>מלך ישראל וגואלו</b>: ישעי' מד, ו."],["7153","140","<b>דאלקים ל' שררה</b>: ראה רש\"י בראשית ו, ב. לעיל פ' וארא ס, א. וש\"נ."],["7154","141","<b>ולעצור</b>: מכאן (עד לקמן פ\"ד) הועתק בהמשך תרס\"ו ע' שיג (בשינויים קלים ובהוספות)."],["7155","142","<b>ויט שכמו לסבול</b>: ויחי מט, טו."],["7156","143","<b>לקונו</b>: טזיז ניתוסף: ו(ל)יוצרו. בהמשך תרס\"ו כבפנים."],["7157","144","<b>האדם</b>: טזיז ותרס\"ו: האדון."],["7158","145","<b>אל תהיו כעבדים. . פרס</b>: ראה אבות פ\"א, מ\"ג."],["7159","146","<b>שמח נפש עבדך</b>: תהלים פו, ד."],["7160","147","<b>כו'</b>: כ\"ה גם בטזיז ותרס\"ו."],["7161","148","<b>כי אליך הוי' </b>[טז ותרס\"ו: ה']<b> נפשי אשא</b>: המשך הכתוב שמח נפש עבדך [ושם: אדני — ראה זהר בלק קצה, ב. שער הכולל פי\"א, סכ\"ג בסופו. לקמן תיג, רע\"א ובהערה שם. מאמרי אדה\"א דברים ח\"א ע' דש. תשובות וביאורים ס\"ה. נדפס גם באגרות קודש שלו ח\"ב ע' לז]."],["7162","149","<b>בעמל</b>: טזיז בעול. בהמשך תרס\"ו כבפנים."]]],[2300550418,"שקיבל עליו לקרות ולשנות פרק א', ואם הוא רק כפי רגילותו וטבעו שהוא אוהב בטבעו לשקוד ולהתמיד בלימוד אין זו עבודה בעול כלל אבל ביתר מכפי טבעו ורגילותו ביגיעה ועמל רב עד מיצוי הנפש ממש כו' אדם כי ימות באהל<sup data-n=\"7163\">150</sup> תורה שממית עצמו עלי' ונק' עמל תורה זהו שנק' עולה של תורה כו'.\n<b>וזהו</b> שאמר ע\"פ זה ושבתם כו' בין אשר לא עבדו שאינו דומה השונה פרקו<sup data-n=\"7164\">151</sup> ק' פעמים לק\"א פעמים שבפעם הא' שהוא יתר מרגילותו וטבעו נק' עובד אלקי' בעול תורה כו', ובק' פעמים אע\"פ ששונה בעבודה קשה ויגיעה כזו מ\"מ אינו נק' עובד אלקי' להיות שיש חשק בטבעו להיות שוקד ולחזור על לימודו אפי' עד ק' פעמים כך רגילותו וטבעו, אבל בפעם [ה]א' היתירה על טבעו שמאד נגד רצונו ותכבד עליו ביותר פעם הא' הזה זהו שנק' עובד אלקי' בעול גמור (וכדמיון זה כל<sup data-n=\"7165\">152</sup> פרסא בזוזא כו' לפי שקשה עליו לעשות יותר מרגילותו כו'). <span data-k=\"pg\">תקצ</span> ּ וכך הוא בשארי מצות כמו במצות הצדקה שיעשה נגד טבעו ורצונו באיש<sup data-n=\"7166\">153</sup> כילי וקמצן שממונו חביב עליו מגופו ונפשו בטבעו ואינו מוציא להוצאות ביתו רק בקימוץ גדול כדי סיפוק צרכו כו'. ואמנם במצות צדקה להחיות העניים יכול לפזר יותר מטבעו הרבה, זהו מצד עומ\"ש עליו שנק' עבד אלקי' שמבטל טבעו וכח יגיע כפיו שנשא נפשו [ל]זה ונותן לעני ודל רק לקיים רצון ה' כי ירא למרוד בקונו ואימתו מוטלת עליו, אבל כשאינו מפזר רק כפי טבעו בנדיבות הלב ולא יותר אין זה נק' עובד אלקי' בעול לבטל טבעו ורגילותו כו'. וכך הוא בכל המדות שמעציר רוחו ומתאפק ומושל בטבעו הרע וקשה בע\"כ דוקא מצד עומ\"ש כו', כמו המושל ברוחו לבלתי יכעוס בכעס קשה ולא יקום ויטור לרעהו ולא לחשוב רע לאדם וכ\"ש שלא לדבר לה\"ר ורכילות ולא לעסוק בהוללות כו' אעפ\"י שזהו נגד טבעו שהוא לץ ובעל לה\"ר כו', זהו שעומ\"ש עליו בעול כבד להניח ולבטל רצונו הטבעי. וכך בכל התאות [כ]תאות המאכל ותאות המשגל והשגת עושר והון וכבוד וניצוח אע\"פ שאינו איסור דאורייתא יתאפק וימשול ברוחו למנוע א\"ע וכל<sup data-n=\"7167\">154</sup> אלה ביתר מכפי כחו וטבעו אע\"פ שהוא איש חכם<sup data-n=\"7168\">155</sup> בטבעו ורודף כבוד ועושר והתנשאות כו', ויסתפק במיעוט<sup data-n=\"7169\">156</sup> ויסבול מכל מה שיעשו נגד רצונו כמו שומע חרפתו וקללתו ואינו משיב וכה\"ג בכל הטבעי' כו'. והוא שאינו מרגיש חיות וטעם גם בבחי' הטוב בעבודתו כלל רק עושה ביגיעה רבה ועול גדול ביותר ועיקר היגיעה ועבודה הוא רק לעשות נגד טבעו אפי' בדבור<sup data-n=\"7170\">157</sup> קל בהתאפקות בדבור ומ\"ז",[["7163","150","<b>אדם כי ימות באהל</b>: חוקת יט, יד. ראה שבת פג, סע\"ב. לעיל פ' שמות ד, א הערה 176."],["7164","151","<b>שאינו דומה השונה פרקו</b>: ראה חגיגה ט, ב. תניא פט\"ו."],["7165","152","<b>כל</b>: טזיז ביו\"ד. ראה בהערה שלפנ\"ז. בהמשך תרס\"ו לא הועתק כל החצע\"ג."],["7166","153","<b>באיש</b>: שם כאיש. בהמשך תרס\"ו כאן ע' שיד כבפנים."],["7167","154","<b>וכל</b>: טז: בכל. יז ותרס\"ו: מכל."],["7168","155","<b>חכם</b>: טזיז: חם. בתרס\"ו לא הועתק."],["7169","156","<b>במיעוט</b>: טז ותרס\"ו: במועט."],["7170","157","<b>בדבור</b>: טזיז: בדבר. בהמשך תרס\"ו כבפנים."]]],[2300550435,"כנ\"ל (ואפילו בהוללות אם בטבעו הוא בעל מרה לבינה יעשה עצמו בעוצב וימעט מאד בדיבור וישמור פיו ולשונו ולא ילך בגדלות והתפשטות בקומה זקופה ורוח גבוה לדבר גדולות כ\"א בהכנעה ושפלות וענוה גדולה ואע\"פ שבטבעו הוא רוח גבוה ורחב לב כו' וכה\"ג). ובכל אלה אעפ\"י שלא נהפך הטבעיות שלו כלל רק שמכניע הלב ועוצר רוחו וכובש יצרו בע\"כ שנק' לאכפיי' לסט\"א לבד נק' עובד אלקי' באמת (והיינו שעבודה זו נק' ג\"כ בשם תיקון כמו עורות עבודי'<sup data-n=\"7171\">158</sup> כידוע, והיינו מה שמתקן לבחי' שם אלקי' גימ' הטבע<sup data-n=\"7172\">159</sup> במה שמכניע הטבע הגופני' שהיא מק\"נ ונכלל בשם אלקי' דקדושה כמ\"ש במ\"א). משא\"כ מי שלא עבד אלקי' בעומ\"ש לעמוד על נפשו נגד טבעו כנ\"ל, אע\"פ שעושה מצות ולומד תורה ומתפלל בכ\"י ויום אינו נק' עובד אלקי' כלל כמו שאמר יען נגש העם הזה אלי<sup data-n=\"7173\">160</sup> בפיו ושפתיו כבדוני בתפלה [ב]רגילות מן השפה ולחוץ כי כך רגילותו מנעוריו כו', וכן יראת מצות אנשים מלומדה ברגילות וטבעיות ממש, רק כמו שהרגילום אבותיהם מנעוריהם כו' לבד שאין בזה שום צד ענין עבודה בעומ\"ש מכח עצמן לעשות נגד טבעו דוקא אף בע\"כ כנ\"ל, אין זה עובד אלקי' כלל כנ\"ל. וזהו שאמר ושבתם וראיתם בין צדיק לרשע דודאי היכר גמור ונראה לעין במעשיהם [ב]היפוך <span data-k=\"pg\">1182</span> ּ מטוב לרע כו', כך ממש תתבוננו ותראו הבדל הניכר לעין [ה]רואה בין עובד אלקי' למעלה מטבעו [ב]עול מ\"ש ממש כנ\"ל, לאשר לא עבדו בעול כלל כנ\"ל אע\"פ שמעשיהם בעבודה האלקי' כמו בתפלה ותו\"מ א' הוא ממש, ובאמת ההבדל ביניה[ם] כמו בין צדיק לרשע ממש כי האדם יראה לעיניו בחיצוני' המעשה לבד וה' יראה ללבב<sup data-n=\"7174\">161</sup> כמו<sup data-n=\"7175\">*162</sup> שיש בלבו עומ\"ש בעבודתו אם אין בלבו עומ\"ש כלל כנ\"ל וד\"ל.\n[ד]<b> אך</b><sup data-n=\"7176\">162</sup> הנה בחי' עבד הב' הנ\"ל שעבודתו בשמחה ותענוג ולא תכבד עליו כלל אף בלילה תדוד שינתו ויעבוד בכל עיבוד הקשה<sup data-n=\"7177\">163</sup> וכבידה בכל אשר יגזור אדונו עליו, ואע\"פ שיהי' למעלה ולנגד טבעו לגמרי עד מס\"נ ממש לא ירגיש כלל בעצמו למשא ו[ל]עול כלל אדרבה יעשה הכל מאה\"ר כו' בעונג ושמחה. וכ\"ז מצד עוצם התקשרותו מלונ\"ח<sup data-n=\"7178\">164</sup> לאדונו כו' כנ\"ל, הנה כ\"ז יש בנשמות הגבוהות שנק' עובדי הוי' בכלל שלמעלה מעובד אלקי' בכלל דעובד אלקי' בכלל זהו מצד היראה ואימה יתירה בקבלת עומ\"ש באמת כנ\"ל, ועובד הוי' הוא רק מצד",[["7171","158","<b>שעבודה. . עורות עבודי'</b>: נסמן לעיל פ' יתרו רסח, ב."],["7172","159","<b>אלקי' גימ' הטבע</b>: ראה שער היחוד והאמונה רפ\"ו. לעיל פ' שמות לח, א הערה 20."],["7173","160","<b>יען </b>[יז ניתוסף: אשר]<b> </b>נגש העם הזה אלי [טז: ליתא]: ישעי' כט, יג [ושם: יען כי נגש העם הזה — ראה לעיל פ' בשלח רג, ד הערה 1011]."],["7174","161","<b>כי האדם יראה לעיניו </b>[טז: לעינים]<b>. . וה' יראה ללבב</b>: שמו\"א טז, ז."],["7175","*162","<b>כמו</b>: טזיז: במי. תרס\"ו: אם."],["7176","162","<b>אך</b>: מכאן הועתק בהמשך תרס\"ו ע' שטז בשינויים ובהוספות."],["7177","163","<b>עיבוד הקשה</b>: טזיז: עבודה קשה."],["7178","164","<b>מלונ\"ח</b>: טז: בלו\"נ חפיצה."]]],[2300550451,"האהבה וההתקשרות האמיתי' ע\"כ ישליך נפשו מנגד ויהי' לעבד נאמן לשרתו בכל ביתו כמו אליעזר<sup data-n=\"7179\">165</sup> כו') (וכן יהושע הי' נער משרת למשה<sup data-n=\"7180\">166</sup> כעבד נאמן וכן אלישע<sup data-n=\"7181\">167</sup> לאליהו<sup data-n=\"7182\">168</sup> שזהו רק מצד פנימי' ההתקשרות כו'). וכך הי' משה נק' עבד הוי'<sup data-n=\"7183\">169</sup> דוקא והוא שאמר לא כן עבדי משה<sup data-n=\"7184\">170</sup> בכל ביתי נאמן הוא כו' שזהו כעבד הנאמן בבית ובכל אשר לו שנמסר הכל לידו מכל הון ביתו<sup data-n=\"7185\">171</sup> שהוא כבעה\"ב עצמו ועושה ומצליח להביא תוס' ברכה כו' כנ\"ל. וכך יש נשמות בפרט שנקראו עובדי הוי'<sup data-n=\"7186\">172</sup> באהבה ושמחה ותענוג גדול כמ\"ש עבדו את ה' בשמחה<sup data-n=\"7187\">173</sup> דוקא, וכמו בשמחה ש\"מ שאינו רק מצד עוצם ההתקשרות פנימי' שבלב ומוח לדבקה בו ית' מניח<sup data-n=\"7188\">174</sup> כל עצמו לעסוק בעבודת ה' בעבודה פנימי' לשרת אותו ככהן משרת בבית ה' להקריב קרבן ה' ולערוך שולחן ה' ולהקטיר קטורת כו', וכמו להושיט יין בכלי יקר ולתקן ולייפות הלבושי' וההיכלו' וכל כלי יקר כו' שיהי' לכבוד ולתפארת ולנח\"ר לאדון כנ\"ל. כך עובדי הוי' בתו\"מ לתקן בחי' הכלים ולבושים נאים במעשה המצות שזהו לברר בירורי' דרפ\"ח כו', כהעלא' דקרבן וקטרת לריח ניחוח להוי' ולשמח לב אדם העליון בכל תיקוני ההיכלות ובכל הון ביתו העליון נאמן לעשות כבעה\"ב עצמו, דהיינו לכוין ברצון הפנימי' ושיהי' תוס' ברכה באו\"כ בבית ובשדה כו' כמו ע\"י תשב\"כ ו[תו]שבע\"פ ע\"י משה שהי' נאמן ביתו כנ\"ל (כמו אם יתן איש את כל הון ביתו<sup data-n=\"7189\">175</sup> דקאי בתו\"מ העליוני' כו'). וכאברהם שהי' עובד ה' רק מגודל התקשרות אה\"ר שנמצא לבבו נאמן<sup data-n=\"7190\">176</sup> באמת עד שמסר כל עצמו ונפשו רק לעשות נח\"ר ליוצרו אף במה שנגד טבעו כמו לשחוט לבנו יחידו וכה\"ג, לפי שהי'<sup data-n=\"7191\">177</sup> רחימא דמלכא<sup data-n=\"7192\">178</sup> כידוע, שלא תכבד כלל על עבד נאמן הזה כל עבודה קשה <span data-k=\"pg\">תקצא</span> ּ יעשה הכל בשמחה ונחת יותר משיעשה העבד בעול קשה שתכבד עליו העבודה ביותר כנ\"ל. וגם הלא יש ע\"י עבד נאמן בית הנ\"ל תוס' ברכה והצלחה בכל הון ביתו בכפלי כפלים עד שיגדל ויתעשר על ידו ביותר בכל אשר לו יותר מע\"י כח עצמו, וכמו ע\"י משה עבד הוי' כנ\"ל שנמצא תוס' ברכה בכל האו\"ח<sup data-n=\"7193\">179</sup> עליוני' דאצי' בשם הוי' ע\"י תו\"מ שנמשך ע\"י משה למטה, וז\"ש לא כן עבדי משה כו', ואתפשטותי' דמשה בכל דרא<sup data-n=\"7194\">180</sup> בפרטי נשמות שנק' עובדי הוי' בתו\"מ לשמה ובכלל נש\"י שקיבלו התו\"מ באהבה ורצון כמו הללו את ה' כל עבדי הוי'<sup data-n=\"7195\">181</sup> כו' שע\"י עבודתם בשמחה וטוב לבב לעשות נח\"ר",[["7179","165","<b>לשרתו. . אליעזר</b>: לך טו, ב. ח\"ש כד, ב."],["7180","166","<b>יהושע הי' נער משרת למשה</b>: תשא לג, יא. בהעלותך יא, ב."],["7181","167","<b>יהושע. . כעבד. . אלישע</b>: ראה תרס\"ו כאן ע' שיז בהגה."],["7182","168","<b>משרת. . אלישע לאליהו</b>: מל\"א יט, כא."],["7183","169","<b>משה נק' עבד הוי'</b>: ברכה לד, ה."],["7184","170","<b>לא כן עבדי משה</b>: בהעלותך יב, ז. ראה גם לעיל קנה, ד. וש\"נ."],["7185","171","<b>שנמסר הכל לידו מכל הון ביתו</b>: בתרס\"ו (כאן ע' שיז) מפרש היינו דכל סדר ההשתל' ניתן ע\"י להמשיך בהם תוספת אורות."],["7186","172","<b>נשמות. . עובדי הוי'</b>: ראה תרס\"ו כאן ע' שיז ואילך."],["7187","173","<b>עבדו את ה' בשמחה</b>: תהלים ק, ב. בתרס\"ו כאן ע' שיח לשמוח בשמחת ה' וחדות ה' היא מעוזו כו', שאינו רוצה לעצמו מאומה כ\"א הוא שמח מהשמחה ונח\"ר שלמעלה."],["7188","174","<b>מניח</b>: טזיז ותרס\"ו: יניח."],["7189","175","<b>אם יתן איש את כל הון ביתו</b>: שה\"ש ח, ז. ראה גם לעיל פ' בשלח קנה, ד. וש\"נ."],["7190","176","<b>וכאברהם. . שנמצא לבבו נאמן</b>: נחמי' ט, ז. ח."],["7191","177","<b>שהי'</b>: טזיז: שהי' נק'. ובתרס\"ו כבפנים."],["7192","178","<b>רחימא דמלכא</b>: ראה זהר ואתחנן רסב, ב. מאמרי אדה\"א שמות ח\"ב ע' שמג. וש\"נ."],["7193","179","<b>האו\"ח</b>: טזיז: האורות. בתרס\"ו האו\"כ."],["7194","180","<b>ואתפשטותי' דמשה בכל דרא</b>: ראה ת\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א ס\"א). הנסמן לעיל פ' וארא פ, ג."],["7195","181","<b>הללו. . עבדי הוי'</b>: וכ\"ה בהמשך תרס\"ו כאן ע' שיט — חיבור שני כתובים תהלים קיז, א (הללו את ה') קלד, א (כל עבדי ה')"]]],[2300550466,"ליוצרם מוסיפים תוס' ברכה למעלה בשם הוי' ביחו\"ע שנעשי' ע\"י במצות כו'.\n<b>וזהו</b> כי לי בנ\"י עבדים עבדי הם כו', פי' עבדי עבדי הוי' בבחי' עבד נאמן בית הנ\"ל בתו\"מ שנק' הון ביתו כו', וזהו בחי' עבד שלמעלה מבחי' בן הנ\"ל, דאע\"פ שעבודתו של הבן לאביו ג\"כ הוא ברוב שמחה ותענוג לעשות נח\"ר לאביו ולא תכבד עליו כלל וכלל כנ\"ל, הרי זהו מצד שנמשך לשרשו כי הרי יש בכח<sup data-n=\"7196\">*182</sup> המושך בנפש הבן מצד כח האב עד שנמשך אליו ממילא שזהו כמו טבע בנפשו מצד התולדה כו'. וכך בנש\"י שנק' בנים נמשך להם כח ההתעוררו' מאביהם שבשמים שיומשכו אחריו בכל לב ונפש כמו משכני אחריך<sup data-n=\"7197\">182</sup> כו' שזהו מצד שרשם בעצמות א\"ס ע\"כ לא תכבד עליהם העבודה האלקי' ולא ינטו ימין ושמאל כנ\"ל, אבל אין זה מכח עצמם ובחירתם ולא יהי' עי\"ז<sup data-n=\"7198\">183</sup> תוס' אור ושפע וברכת ה' למעלה. משא\"כ ע\"י בחי' עבד נאמן בית הנ\"ל שמשליך נפשו מנגד מצד עצמו כאברהם שהכיר לבוראו וכמשה עבד ה' וכה\"ג (וכיוסף צ\"ע כו'), ונעשה כבעה\"ב עצמו להביא תוס' ברכה בשלו שאין זה בכח הבן כלל כו'. והיינו שנק' ישראל עבדי' עבדי הוי' לשלימות המעלה שיהי' בהם כח מצד עצמם [ב]עבודתם בתו\"מ ואוי\"ר להוסיף אורות באצי' בתוס' ברכה למעלה יותר מעצם שרשם, ולזה נמשכו הנשמות בגופים שיהיו נק' עבדים דירידה זו לצורך עלי'<sup data-n=\"7199\">184</sup> הוא כידוע להעלות לנשמתם ע\"י קדושה העצמי' דתו\"מ למעלה משרשם בחכמה שבמוח האב כו', והוא ע\"י שמחה וטוב לבב במצות דוקא שמזה יהי' העוה\"ב<sup data-n=\"7200\">185</sup> שהוא תוס' אור וברכה כמו ברכת ה' [היא] תעשיר<sup data-n=\"7201\">186</sup> כו' וד\"ל.\n<b>והנה</b> הגם שלפי המובן מכל הנ\"ל בהפרש שבין עבד הא' הנק' עובד אלקי' בעומ\"ש לעבד הב' שנק' עבד הוי' שעובד בשמחה ותענוג כנ\"ל ודאי שאין ערך כלל לעבד בעול שבע\"כ הוא עובד בעול ותכבד עליו העבודה עד שתקצר רוחו כו' משא\"כ עבד ה' שבאהבה ושמחה שיניח כל עצמו רק לה' לבדו כו' שנק' עבד נאמן כו', עכ\"ז יש יתרון מעלה רבה בעבודת עול דוקא יותר מעבודה באהבה דעבד נאמן הנ\"ל משני טעמים, הא' מצד עצם העבודה שהעבודה הבאה מתוך האהבה וההתקשרות האמיתי' כנ\"ל כל מה שיעשה ויעבוד לאדון לא נק' עבודה כלל, כי כל עבודה כזאת יעשה האוהב הנאמן לאוהבו מצד עוצם <span data-k=\"pg\">1184</span> ּ התקשרות האהבה כאהבת הבן לאביו ואשה לאישה שישרת אותו ויעשה רצונו בכל אשר יגזור אומר עליו כמו לתקן תיקוני ביתו ולבושיו וכליו ושולחנו וגם מלאכת הבית והשדה להיות",[["7196","*182","<b>בכח</b>: טזיז ותרס\"ו: כח."],["7197","182","<b>משכני אחריך</b>: שה\"ש א, ד."],["7198","183","<b>עי\"ז</b>: בתרס\"ו ע' שיט: עי\"ז כ\"כ."],["7199","184","<b>דירידה זו לצורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["7200","185","<b>במצות. . שמזה יהי' העוה\"ב</b>: ראה מאמרי אדה\"א בראשית ע' שצב. וש\"נ. לעיל פ' שמות ז, א. וש\"נ."],["7201","186","<b>ברכת ה' [היא] תעשיר</b>: משלי י, כב."]]],[2300550481,"תוס' ברכה כאשה עקרת הבית שתעשה באמונה לבעלה כמו א\"ח כו'<sup data-n=\"7202\">187</sup> בטח בה לב בעלה<sup data-n=\"7203\">188</sup> כו' גמלתהו טוב<sup data-n=\"7204\">189</sup> כו', וכן הבן בנכסי אביו שמוסר הכל לידו, ולמה יגדל מעלת העבד הנאמן יותר מאשתו ובנו וכל או\"נ<sup data-n=\"7205\">190</sup> כנפשו שכל אלה אינו רק מצד ההתקשרות באה\"ר ונפלאה עד שמתבטל מכל עצמו לעבודתו ולרצונו כו', ואפי' כמו עבודה דאברהם ומשה שנק' נאמן בית אין זו עבודה כעבודת עבד ממש רק כעבודת האוהב הנאמן לאוהבו (וכמו יהושע נער משרת משה לא הי' זה רק מהתקשרות עוז האהבה לקבל ממנו אור תורה כתלמיד שמשמש לרבו וכן אלישע לאליהו שעזב בית אביו וישרתהו וכה\"ג שאינו נק' עבד כלל<sup data-n=\"7206\">191</sup> ). אבל<sup data-n=\"7207\">192</sup> עבודת העבד הפשוט שעובד בעול לבד שלא מצד האהבה וחשק אדרבה תכבד עליו העבודה ולא יחפוץ בה כלל וגם לעשות נח\"ר לאדון או להגדיל כבודו אין לו בלבו התקשרות אהבה כ\"כ רק מצד היראה ופחד שאימת האדון עליו עושה [בעול] בע\"כ כנ\"ל זהו שנק' עבודה ממש. וזהו כעבודת עבד לאדונו בהכרח בתמידות בלי שינוי וחילוף לא יגרע עבודתו, ואף בעבודות גשמיות כחוטב עצים ושואב מים וכה\"ג שוה אצלו כעבודות קלות ודקות כהושטת כלי יקר לשתי' ולייפות שולחן ולבוש וכה\"ג כי הכל עובד מצד עול המוטל עליו לבד כו'. וכך הוא<sup data-n=\"7208\">193</sup> למעלה בעבוד' האלק[י]' שמקבל אדם ע\"ע עומ\"ש עול ממש וכמ\"ש עבדו את ה' ביראה<sup data-n=\"7209\">194</sup> דוקא, וכמלאכים שנק' משרתים ועבדים מצד עומ\"ש שעליהם כידוע והיינו שלא מצד התקשרות אהבה רק מצד היראה ואימה<sup data-n=\"7210\">195</sup> לכך עבודתם בעול אף שתכבד העבודה ואין<sup data-n=\"7211\">196</sup> בה נח\"ר ושמחה כלל וכלל, רק הכרחי' וחיוב גדול מצד העומ\"ש שמוטל עליו ע\"כ לא יגרע מן עבודתו יום ולילה כמו בעול תורה ועול מצות ועול תפלה והוא שנק' עבודה ממש כנ\"ל. ויש<sup data-n=\"7212\">197</sup> בזה יתרון מעלה מצד שבעבודה יש ביטול כל המהות של העבד הזה שאין לו מקום ומציאות בפ\"ע כלל וכלל כי נקנה ונרצה לעבד לעולם ולכך מבטל כל מהותו ועצמותו לעבודה זו לעשות היפוך טבעו אף שיכבד עליו ביותר יעשה נגד טבעו ומהותו כי אין לעצמו דבר מה בעבודה זו, נמצא שנקראת העבודה הזאת ע\"ש האדון עצמו מצד שאין העבד רק כרכושו וקנינו וכמו שיעבוד בשורו וחמורו שישביחו שדותיו ברב תבואות לא נק' כ\"ז ע\"ש השור כי קנין כספו הוא וכן מה שיעשה העבד הכל לרבו. ולזאת מצד עצם העבודה דעבד זה בעול עולה למעלה יותר מעובד באהבה והתקשרות שנק' ע\"ש העובד ויש בעבודה זו שינוי לעיתים לפ\"ע האהבה לפי שמורכבת באהבה וביטול שמצד הטעם, ולא נק' עבודה כלל אלא כאוהב לאוהבו שהוא בחי' יש ודבר בפ\"ע רק שבטל בכל נפשו אליו לעבודתו ולנח\"ר כנ\"ל, ואע\"פ שיצליח בעבודתו",[["7202","187","<b>א\"ח כו'</b>: משלי לא, י."],["7203","188","<b>בטח בה לב בעלה</b>: משלי שם, יא."],["7204","189","<b>גמלתהו טוב</b>: שם לא, יב."],["7205","190","<b>או\"נ</b>: אוהב נאמן — ראה גם לעיל צ, ב הערה 176."],["7206","191","<b>ואפי'. . עבד כלל</b>: כ\"ז ליתא בתרס\"ו. ובמקומו ישנו הרחבת הביאור."],["7207","192","<b>אבל</b>: מכאן (ועד המוטל עליו לבד) נעתק בתרס\"ו כאן ע' שכא."],["7208","193","<b>הוא</b>: מכאן (ועד אף שתכבד העבודה) נעתק בתרס\"ו כאן ע' שכב (עם הוספות)."],["7209","194","<b>עבדו את ה' ביראה</b>: תהלים ב, א."],["7210","195","<b>ואימה</b>: ראה המשך תרס\"ו כאן ע' שכב: דאפי' מלאכים שעבודתם באהבה. . הנה כללות עבודתם הוא מצד היראה. . וכן הוא בנשמות שיש שעיקרן הוא בקבעומ\"ש."],["7211","196","<b>ואין</b>: מכאן (ועד שנק' עבודה ממש) נעתק בהמשך תרס\"ו ע' שכג (עם הוספות)."],["7212","197","<b>ויש</b>: מכאן (ועד שיעשה העבד הכל לרבו) נעתק בהמשך תרס\"ו ע' שכו (עם הוספות)."]]],[2300550496,"ויתגדל כבוד האדון נק' ע\"ש העובד ולא ע\"ש האדון. משא\"כ <span data-k=\"pg\">תקצב</span> ּ בעבודת עבד הנקנה לו אע\"פ שעובד בעול זהו הכל [בביטול] כל העצמו' ומהות העבד ממש כנ\"ל ונק' רק ע\"ש האדון כי אין לו מהות בפ\"ע כלל כנ\"ל, ובזה [יש] יתרון מעלה לעובד אלקי' בעומ\"ש יותר מעובד הוי' באהבה והתקשרות אמיתי' ודוקא מצד שאין לו לעצמו נח\"ר כלל בעבודתו כנ\"ל וד\"ל.\n<b>והטעם</b> הב' מצד היפוך הטבע שבעבודת העבד בעול שזהו [מ]חודש מעיקרו כביטול הי\"ש לאי\"ן שזהו מה שנקנה ונרצה לעבד להיות כשלו ממש ע\"כ<sup data-n=\"7213\">198</sup> הברכה שיש במעשה ידיו יערב לו לאדון ביותר כמו שהי' האדון בעצמו עושה מלאכה ביגיע כפיו והי' מצליח מלאכתו מאד, שיערב לאדם ביותר מצד שהוא נעשה ביגיעה ועמל דוקא עד שהוציא לפועל בטוב מאד כיגיעה בשדה בזריעה שנק' עמ\"ל מלאכה וקוצר בברכה שתהי' השמחה [ב]יותר<sup data-n=\"7214\">199</sup> ממה שהי' או\"נ נותנים לו שפע רב משלהם או שהיו משביחים בנכסיו בטוב השתדלות' שיש בזה הרכבה מאהבה של העבד נאמן שאין זה בחי' עצמיות שלו כ\"כ כיגיעתו בעצמו בדבר עמ\"ל מלאכ\"ה, וכמ\"כ ע\"י עבדים שעובדים בעובדי'<sup data-n=\"7215\">200</sup> כשור לעול ממש שמשביח בשדותיו וכאש\"ל שזהו כמו שהרויח הון מיגיעת עצמו ביגיע כפיו זהו יקר מאד ונעלה הרבה יותר מכח שכלו ומדותיו מצד עצמם, וכמו שיקבל אדם עונג גדול בעצמות נפשו [ב]מה שיפרנס עצמו ביגיעה ועמל דוקא שמתחדש מיש לאין<sup data-n=\"7216\">201</sup> יותר מכל הון ביתו בעצם שהי' מרויח בהן ע\"י אוהבי' ועבדים נאמנים כו' כי במעט פרנסה מיגיעה ועמל נפשו<sup data-n=\"7217\">202</sup> ישלים נפשו הרבה יותר מכל הון שמתעשר מהתאמצות אחרים זולתו כו'. וכך יובן בענין עמל תורה<sup data-n=\"7218\">203</sup> ועומ\"ש במצות ביגיעה רבה ע\"י עבדים הנקנין בקנין כספו שעושי' בעול כשור כנ\"ל, שיעשו תוס' ברכה ושלימות בחכ' ומדות העליונות שנק' הון ביתו יותר מע\"י או\"נ כעבדי הוי' שעובדי' מאה\"ר במס\"נ כנ\"ל להיותו נעשה בעמ\"ל ויגיעה בעול דוקא, שזהו כמו יגיע כפיו בשדה שיברכנהו ה' במעשה ידיו מלמטה למעלה בחידוש גמור לאין שיעור למעלה כו'. וזהו ענין עולה של תו\"מ שיהי' במשיח<sup data-n=\"7219\">204</sup> דכתי' בי' הקים עול<sup data-n=\"7220\">205</sup> כו', שהוא ע\"י יגיעה רבה בעמל תורה כמו בפלפול שנוגע עד מיצוי הנפש כאדם שממית עצמו (והרוצה לחיות ימית א\"ע<sup data-n=\"7221\">206</sup> ) ונעשה מי\"ש אי\"ן כעול העבד שנעשה כטבע בנפשו לעמל מלאכה, זהו שעולה למעלה בתוס' אורה ושמחה ועונג למעלה מכל הון ביתו שהי' במשה [ב]תשב\"כ ושבע\"פ כו'. וזהו ישכי\"ל עבד\"י עבד בעולה דתו\"מ, ירום ונשא וגב\"ה מא\"ד שהוא כארז שצומח מלמטה למעלה מקטנות",[["7213","198","<b>ע\"כ</b>: מכאן (ועד לקמן מהתאמצות אחרים זולתו כו') נעתק בהמשך תרס\"ו ע' שכז (עם הוספות)."],["7214","199","<b>מצד. . [ב]יותר</b>: בתרס\"ו כאן ליתא."],["7215","200","<b>בעובדי'</b>: טזיז: בעול. בתרס\"ו: ליתא."],["7216","201","<b>מיש לאין</b>: יז ותרס\"ו: מאין לי\"ש."],["7217","202","<b>נפשו</b>: טזיז: ליתא. בתרס\"ו כבפנים."],["7218","203","<b>עמל תורה</b>: טז: עול תו'. יז: עמל."],["7219","204","<b>עולה של תו\"מ שיהי' במשיח</b>: ראה גם לעיל פ' בשלח קסט, ג. וש\"נ."],["7220","205","<b>הקים עול</b>: שמו\"ב כג, א."],["7221","206","<b>והרוצה לחיות ימית ע\"א</b>: ראה תמיד לב, א."]]],[2300550510,"לגדלות ביותר מצד יניקתו בארץ בעומק יותר, והוא בחי' חידוש מאין ליש מצד היגיעה ועמל דעומ\"ש שנחשב ונק' ע\"ש מהו\"ע א\"ס ב\"ה ממש בלי מהות בפ\"ע כלל. וזהו כתר ש\"ט דמשיח<sup data-n=\"7222\">207</sup> למעלה ממש<sup data-n=\"7223\">208</sup> לפי שכל המשפיל עצמו מיש לאין כעבד בעול המגביהו<sup data-n=\"7224\">209</sup> מלמטה למעלה יותר מביטול עצמי' דענוה והתקשרות פנימי' דמשה ואברהם וכה\"ג וד\"ל.\n[ה]<b> ולהבין</b> זה בתוס' ביאור יש להקדים ענין משל<sup data-n=\"7225\">211</sup> א' המבואר במ\"א באב<sup data-n=\"7226\">210</sup> שהי' לו בן <span data-k=\"pg\">1186</span> ּ מושלם בכל המעלות בחכ' ומדות והי' מנהיג כל ביתו בחכמתו ויושר שכלו וטוב אמונתו והשתדלותו כבן לאב ורצה בטובתו יותר מנפשו כו' כנ\"ל, אך מכל העונג והשמחה שבן חכם כזה ישמח אב בחכמתו וטוב פעולתו ועבודתו בכל קנינ[ו ו]רכושו שהצליח למעלה מאד לא נחה דעת האב מבנו השלם שאין לו שלימות האמיתי עדיין במה שצריך לאביו לקבל מזונו ושפעו וכל הצטרכותו הכל מאביו, אע\"פ שראוי לכל שכר טוב מצד טוב שכלו ולמודו בכל חכ' וכשרון יושר מעשיו הטובים לו ביותר עכ\"ז הרי אין הבן יכול לפרנס א\"ע בחכמתו ולימודו ומדותיו היקרים רק מקבל הכל מאביו, ואין זה שלימות אמיתי בכל החכ' ומדות שלו אע\"פ שעושה ומצליח בשל אביו כו' כ\"א כשיהי' ביכולתו לפרנס א\"ע ביגיע כפיו בשלו שלא משל נכסי אביו כלל, כמו כשילמוד עצמו לעשות בכלי אומנות לתקן כלים ולרקום בגד יקר וכה\"ג שמעט יגיע כפיו שירויח בזה להחיות נפשו אף במיעוט זהו שלימות האמיתי' ויערב לו ביותר במה שא\"צ לשום אדם ולא לאביו ליהנות בתענוגים רבים שאינם שלו שאוכל נהמא דכסופא<sup data-n=\"7227\">212</sup> כו'. וגם האב ישמח ויערב לו ביותר מה שבנו יכול לפרנס א\"ע יותר מכל הון ביתו שהי' נותן לו בכל לבו עבור טוב חכמתו ומעלתו. וכ\"ש אם בנו יפרנס לאב מיגיע כפו בכלי אומנו' עד שהגיע לעושר גדול יותר משל האב כי זהו שחכמתו עמדה לבן לעשות תוס' ברכה בחידוש מעיקרו כמו בכלי אומנתו לתקן דבר המקולקל או לעשות כלים ואבני יקר מחדש ממש כמו מאין ליש, משא\"כ בעושר שהצליח בנכסי אביו או במסחור שאינו רק יש מיש כו' ולא ביגיע[ה] ועמל [כלל]. וכ\"ז א\"א להיות כ\"א שהבן הזה יהי' מרוחק מאביו ולא יהי' כלום<sup data-n=\"7228\">213</sup> בנכסי אביו וילך למרחקים ללמוד אומנות, שבודאי צריך שיהי' נמכר<sup data-n=\"7229\">214</sup> לעבד [ו]למשרת לאדונו שהוא האומן המלמדו לעשות אצלו המלאכה ימים רבים ביגיעה גדולה ועצומה עד מיצוי הנפש, עד שיוכל גם הוא לתקן ולעשות בכלי אומנות כרבו ויוכל לפרנס א\"ע מיגיע כפיו להיות עושר גדול מכח עצמו יותר משיהי' אצל אביו כו' וד\"ל.",[["7222","207","<b>כתר ש\"ט דמשיח</b>: ראה גם לעיל פ' בשלח קנו, ד. וש\"נ."],["7223","208","<b>ממש</b>: יביז: ממשה."],["7224","209","<b>המגביהו</b>: יב: הקב\"ה מגביהו. יז: ה' מגביהו. יח: מגביהו."],["7225","211","<b>משל. . באב</b>: מכאן ועד לקמן שצט, א ראה המשך תרס\"ו ע' שפ-שפד (בשינויים והוספות)."],["7226","210","<b>משל. . באב שהי' לו בן</b>: ראה גם לקמן תז, ב. תטו, ב. תיז, ד. תיח, ב. שע\"ת סז, סע\"ד ואילך ובהערה 1."],["7227","212","<b>נהמא דכסופא</b>: ראה ירושלמי ערלה פ\"א, ה\"ג הובא בלקו\"ת צו ז, רע\"ד. מאמרי אדה\"א קונטרסים ע' תקצה. וש\"נ. תו\"ח וישלח קפד, א."],["7228","213","<b>כלום</b>: בתרס\"ו כאן: לו כלום."],["7229","214","<b>נמכר</b>: שם: ליתא."]]],[2300550524,"<b>וכך</b> יובן הנמשל מזה בכלל בנש\"י שנק' בנים כמו בני בכורי ישראל וכן א' הבן יקיר לי אפרים<sup data-n=\"7230\">215</sup> כו' לפי ששרש נש\"י עלו במחה\"ק<sup data-n=\"7231\">216</sup> בבחי' פנימי' דחכ' ומדות בדומה לעליון כו' כמ\"ש מ\"ה שמו ומ\"ה שם בנ\"ו<sup data-n=\"7232\">217</sup> (וכמו כח המוליד שיוליד בדומה לו בבחי' אדם בחכ' ומדות השלימות כמו ח\"ע ומדות דתוה\"ק שזהו מ\"ה שמו בעצם מ\"ה דח\"ע העצמי' ממש, כך מ\"ה דחכ' דשם מ\"ה [דאלפי']<sup data-n=\"7233\">218</sup> כו' שהוא שם בנ\"ו בחי' יש\"ס<sup data-n=\"7234\">219</sup> כו', וזהו בשביל התוה\"ק שנק' ראשית [ב]חכמה<sup data-n=\"7235\">221</sup> ובשביל ישראל<sup data-n=\"7236\">220</sup> שעבמ\"ח בספ\"ר וסיפו\"ר<sup data-n=\"7237\">222</sup> דאותיות דתוה\"ק כמו אז ראה ויספרה<sup data-n=\"7238\">223</sup> כו' ויאמר לאד\"ם<sup data-n=\"7239\">224</sup> שלמטה כו' דג' קשרים הן<sup data-n=\"7240\">225</sup> כידוע וד\"ל). ובפרט ירדה התו' במ\"ת בנשמות מבחי' שם מ\"ה דח\"ע והוא בחי' מש\"ה מ\"ה שמו<sup data-n=\"7241\">226</sup> כו' וקיבלו התו\"מ במ\"ת וזהו תורה צוה לנו משה<sup data-n=\"7242\">227</sup> כו', והי' בבחי' בן כמו מ\"ה שם בנ\"ו וגם בחי' עבד הוי' בכל הון <span data-k=\"pg\">תקצג</span> ּ ביתו דתוה\"ק נאמן הוא להמשיך אור דחכמה דתוה\"ק [ב]ירידות והתלבשות למטה בתרי\"ג מצות לברר בירורים דרפ\"ח<sup data-n=\"7243\">228</sup> כו'. וישראל קיבלו ממנו עוז וכח זה להיות יכולים לברר בשם מ\"ה דחכמה דתורה, ונק' גם הן עבדי הוי' ע\"י עבודתם התמה בתו\"מ לשמן בכוונה ורעו\"ד בשמחה וטוב לבב להוסיף אורות באצי' בתוס' מרובה על העיקר כמ\"ש זרע ברוכי הוי'<sup data-n=\"7244\">229</sup>. וגם נק' נרות הוי'<sup data-n=\"7245\">230</sup> ע\"י נר מצוה ותורה אור<sup data-n=\"7246\">231</sup> להאיר שם הוי' גם בחשך דק\"נ כמו בריבוי הנרות מאד יאיר גם לחושך<sup data-n=\"7247\">232</sup> כו' והן ע\"י אותיות [דתושב\"כ] דתורה אור, וכמו במ\"ת שחכ' אדם העליון תאיר פניו<sup data-n=\"7248\">233</sup> ביו\"ד הדברות באותיות כמו ואתא מרבבות קדש<sup data-n=\"7249\">234</sup> העליון למטה מטה, וכך דבר ה' בד\"ת גם עתה וכמצות באוי\"ר בכוונה כו'. וזהו הכל כמשל הבן השלם בחכמה ומדות שנוהג כל בית ורכוש אביו ביושר שכלו עפ\"י החכ' האמיתי' ומדות הישר'<sup data-n=\"7250\">235</sup> שקיבל מאביו והוסיף ברכה והצלחה בכל הון ביתו כנ\"ל [שישמח לב האב בחכמתו וטוב שלימות פעולתו ועבודתו הנאמנה בכל קנינו ורכושו שיצליח ועושה פירות רבים כו' כנ\"ל]. וז\"ש במשה בכל ביתי נאמן הוא<sup data-n=\"7251\">236</sup> כו' וכן ישראל שמצליחי' במע\"ט בכל דור ע\"י צ\"ג שבהן כו' עושי' פירות [למעלה ו]למטה בתוס' ברכה כו'.\nאך כ\"ז אינו שלימות אמיתי בבחי' בן או עבד [כ]זה לפי שכל האור וההמשכה וברכה הזאת באה מלמעלה למטה ה\"ז",[["7230","215","<b>הבן יקיר לי אפרים</b>: ירמי' לא, יט."],["7231","216","<b>נש\"י עלו במחה\"ק</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל פ' שמות לב, ב הערה 428."],["7232","217","<b>מ\"ה שמו ומ\"ה שם בנ\"ו</b>: משלי ל, ד."],["7233","218","<b>דשם מ\"ה </b>[דאלפי']: נסמן לעיל פ' תרומה שיג, א."],["7234","219","<b>יש\"ס</b>: ראה ב\"ר פע\"ד, ח. זהר ויחי רלג, א. רלו, א. ועוד."],["7235","221","<b>ראשית [ב]חכמה</b>: ראה תהלים קיא, י."],["7236","220","<b>בשביל התוה\"ק. . ובשביל ישראל</b>: ראה רש\"י בראשית א, א. הנסמן בתו\"ח בראשית מד, א הערה 6."],["7237","222","<b>בספ\"ר וסיפו\"ר</b>: ראה ספר יצירה פ\"א, מ\"א."],["7238","223","<b>אז ראה ויספרה</b>: איוב כח, כז."],["7239","224","<b>ויאמר לאד\"ם</b>: איוב שם, כח."],["7240","225","<b>דג' קשרים הן</b>: ראה זהר אחרי עג, א. לעיל פ' שמות ב, ד הערה 107."],["7241","226","<b>מש\"ה מ\"ה שמו</b>: ראה גם לעיל פ' שמות מג, ד. וש\"נ."],["7242","227","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["7243","228","<b>דרפ\"ח</b>: נסמן לעיל פ' יתרו ערב, ד."],["7244","229","<b>זרע ברוכי הוי'</b>: ישעי' סה, כג."],["7245","230","<b>נרות הוי'</b>: נסמן לעיל פ' תצוה שסד, ב."],["7246","231","<b>נר מצוה ותורה אור</b>: משלי ו, כג."],["7247","232","<b>לחושך</b>: יבטז ניתוסף: הגס. יז ניתוסף: הנר( ). בתרס\"ו (כאן ע' שפב) כבפנים."],["7248","233","<b>שחכ' אדם. . תאיר פניו</b>: קהלת ח, א."],["7249","234","<b>ואתא מרבבות קדש</b>: ברכה לג, ב. ראה לעיל פ' תרומה שטו, ב הערה 259."],["7250","235","<b>הישר'</b>: יב ובתרס\"ו כבפנים. טז: היקרים."],["7251","236","<b>בכל ביתי נאמן הוא</b>: בהעלותך יב, ז."]]],[2300550537,"הכל במה שכבר הוכן ועומד שהוא ע\"י תוה\"ק כנ\"ל, ואין זה שממשיך הבן ועבד רק בבחי' יש מיש ולא חידוש גמור מאין ליש ולא מכח עצמו אעפ\"י שחכמתו ומדותיו ישרים ומוצלחים כו'. וגם מה שצריך לקבל הכל מאביו כו' כנ\"ל, אע\"פ שראוי לשכר טוב והוא העוה\"ב מצד טוב פעולתו וכשרון מלאכתו במעשה המצות בעוה\"ז דבשם מ\"ה דחכ' אתברירו<sup data-n=\"7252\">237</sup> ע\"י תו' וישראל כנ\"ל (וזהו [כ]חכ' דשלמה שבנה בהמ\"ק [מאשר הי'] מן המוכן מדוד<sup data-n=\"7253\">238</sup> אביו, וכה\"ג הי' באבות שהכינו במעשיהם לתו\"מ ולכך נק' בראשית ס' הישר<sup data-n=\"7254\">239</sup> כמ\"ש במ\"א בפ' לך לך<sup data-n=\"7255\">240</sup> שכל האור הנוסף ע\"י המצות אינו רק להביא מן ההעלם לגילוי יותר מכפי [קו] המדה ממאציל לאצי' ואין כל חדש מעיקרו בזה כו'). ואע\"פ שמשה נק' ס[ו]פר ומחוקק<sup data-n=\"7256\">241</sup> בגילוי אותיות דתשב\"כ, אין זה חדש מעיקרו רק שמביא מן ההעלם לגילוי אור בכלים עד למטה שנק' יש מיש, אע\"פ שהחכ' מאין תמצא<sup data-n=\"7257\">242</sup> זהו רק מהעלם לגילוי לבד כמו במזל ונוצר, וכן א' הכל תלוי במזל<sup data-n=\"7258\">243</sup> אפי' ס\"ת בהיכל כו'. ואעפ\"י שנא' במשה כי טוב הוא בטי\"ת רבתי<sup data-n=\"7259\">244</sup> דעה\"ח דתוה\"ק כנ\"ל והאיר אור דחכ' דתורה עד למטה בדברים גשמיי' דק\"נ ונעשה ע\"י צ\"ג יח\"ע למטה כמו למעלה כו' והצל[יח] למטה<sup data-n=\"7260\">245</sup> שנברר בין טו\"ר ומזה יהי' השכר בעוה\"ב כו'. מ\"מ עיקר השלימות האמיתי יהי' במשיח לאחר הבירור דעה\"ד טו\"ר ע\"י תו\"מ שא' ישכי\"ל עבד\"י כו' וגבה מא\"ד למעלה מאור דתוה\"ק שירד ע\"י משה, והוא העדן סתימאה<sup data-n=\"7261\">246</sup> שלמעלה משכר המצות בעוה\"ב שא' עין לא ראתה<sup data-n=\"7262\">247</sup> כ\"א למחכה לו דוקא וא' למאן דדייק מילי דחכ'<sup data-n=\"7263\">248</sup> שהוא מה שיחודש מאין ליש ממש מלמטה למעלה בבחי' או\"ח בתושבע\"פ<sup data-n=\"7264\">249</sup> דוקא, שזהו כמו האומן בכלי אומנות שעושה <span data-k=\"pg\">1188</span> ּ ומתקן כלי חדש ואבן יקר מלוטש ובגדי רוקם וכה\"ג, דהחכ' כזו דוקא תחי' בעליה לפרנס א\"ע במיעוט שהוא למעלה מכל הון דח\"ע שבתוה\"ק שנק' הון ביתו כנ\"ל, מטעם שזהו עיקר השלימות דבן שא\"צ לאביו ולכל הון ביתו כי יחי' א\"ע במה שמחדש בכלי אומנתו.\n<b>וזהו</b> שנק' מי שתו\"א [ש]פטור מן התפלה<sup data-n=\"7265\">250</sup> כו' וכמ\"ש ואהי' אצלו [אמון] אומנא<sup data-n=\"7266\">251</sup> דקאי לע\"ל אנא זמין לאתגלאה<sup data-n=\"7267\">252</sup> בימות המשיח שיהי' בירור האחרון מהיפוך חשך לאור מכח",[["7252","237","<b>דחכ' אתברירו</b>: נסמן לעיל פ' יתרו רסו, ד."],["7253","238","<b>דשלמה. . המוכן מדוד</b>: ראה דהי\"א כט, יט. בסמוך הערה 240."],["7254","239","<b>נק' בראשית ס' הישר</b>: נסמן לעיל פ' יתרו רסא, ב."],["7255","240","<b>בפ' לך לך</b>: ראה תו\"ח לך פד, ד ואילך."],["7256","241","<b>שמשה נק' ס[ו]פר ומחוקק</b>: ברכה לג, כא ובתרגומים שם. ראה גם לעיל פ' שמות יב, ד ובהערה 584."],["7257","242","<b>שהחכ' מאין תמצא</b>: איוב כח, יב."],["7258","243","<b>הכל תלוי במזל</b>: ראה זהר (אד\"ר) נשא קלד, א. לעיל פ' שמות יא, א ובהערה 486."],["7259","244","<b>כי טוב הוא בטי\"ת רבתי</b>: שמות ב, ב ובמנחת שי שם. ראה לעיל פ' שמות מג, ד. וש\"נ."],["7260","245","<b>למטה</b>: יביז: כבפנים. טז: למשה."],["7261","246","<b>העדן סתימאה</b>: ראה גם לעיל פ' שמות ה, ג. וש\"נ."],["7262","247","<b>העדן. . עין לא ראתה</b>: ראה ברכות לד, א. ישעי' סד, ג."],["7263","248","<b>למחכה לו. . למאן דדייק מילי דחכ'</b>: ישעי' שם. ראה זהר ח\"ש קל, ב. לעיל פ' שמות ח, ג. וש\"נ."],["7264","249","<b>בתושבע\"פ</b>: ראה המשך תרס\"ו כאן ע' שפג."],["7265","250","<b>שתו\"א [ש]פטור מן התפלה</b>: ראה גם לעיל פ' יתרו רנו, ב. וש\"נ."],["7266","251","<b>ואהי' אצלו [אמון] אומנא</b>: משלי ח, ל. ב\"ר בתחלתו."],["7267","252","<b>אנא זמין לאתגלאה</b>: ראה זהר ויקרא יא, א. אחרי סה, ב."]]],[2300550550,"עצמו דוקא, כמו אומן בכלי אומנות שעי\"ז נעשה שלם בעצם החכמה דתו\"מ העליונים ומפרנסי' גם לאביהם שבשמים<sup data-n=\"7268\">253</sup> וז\"ש קומי לך רעייתי פרנסתי<sup data-n=\"7269\">254</sup> כו', והוא ע\"י בחי' עמל תו' דוקא שנק' עולה של תורה<sup data-n=\"7270\">255</sup> שבאה ע\"י יגיעה רבה עד מיצוי הנפש כמו למחכה לו כו' שזהו עולה למעלה מתענוג ושעשועי' דתוה\"ק שנק' הון ביתו. וזהו כמשל הבן היקר המושלם בחכמה ומדות כשנעשה עבד משרת ללמוד אומנות לפרנס א\"ע שע\"ז אמר והחכמה תחי' בעלי'<sup data-n=\"7271\">256</sup> דחכמה במקורה, שזהו במי שחכמתו עמדה לו לחדש דבר מעיקרו מאין ממש ולא בנכסי האב שנק' יש מיש כנ\"ל עד שיגיע לעושר גדול יותר מעושר והון שהניח לו האב במוכן כו' שיערב לאב יותר מכל שלימות דחכ' שכבר למד הבן אצלו ועשה רב פעלים ברכושו כו' (וכך הי' ביוסף בחי' צ\"ע אצל יעקב אביו בבחי' שלימות המעלה דחכמה עילאה ומדות דיעקב איש ת\"ם<sup data-n=\"7272\">257</sup> בקו האמצעי<sup data-n=\"7273\">258</sup> כו', ונק' בן פור\"ת יוסף שמפרה ומרבה<sup data-n=\"7274\">259</sup> אורות העליונים לאין שיעור למעלה להיותו יפ\"ת ויפ\"מ<sup data-n=\"7275\">260</sup> משופרי' דא\"ק<sup data-n=\"7276\">261</sup> בחכ' ומדות דתוה\"ק שבא בריבוי או\"כ בבחי' התיקון, שזהו כמו בחי' משיח שנק' מלך הח' הד\"ר<sup data-n=\"7277\">262</sup> שהוא שם מ\"ה החדש<sup data-n=\"7278\">263</sup> דא\"ק מקו\"ר התיקו\"ן ע\"כ הי' פותר חלומות לתקן לבחי' התהו<sup data-n=\"7279\">264</sup>. אך זהו הי' דוקא כשנמכר יוסף צ\"ע בגלות לעבד [ו]הצליח ביותר שזהו בזמן הגלות גם עכשיו שמל\"ך אסו\"ר<sup data-n=\"7280\">265</sup> כו' ואח\"כ נעשה מלך על כל הארץ<sup data-n=\"7281\">266</sup> ובירר וליקט כל הכסף<sup data-n=\"7282\">267</sup> כו' שהן כל החסדי' העליונים והטמין ג' מטמונים<sup data-n=\"7283\">268</sup> ויתגלה כל אוצר הזה<sup data-n=\"7284\">270</sup> למשיח<sup data-n=\"7285\">269</sup> שהוא יוסף<sup data-n=\"7286\">271</sup> צ\"ע שיצליח וישכיל וגב\"ה מא\"ד). וזהו הטעם למה שהקים עולה של תו\"מ דוקא שנק' עמל תורה וע[ו]ל חיצוני דמל' שמים כעבד ממש שהעלה זה למעלה מבחי' בן ועבד נאמן בשם הוי' שהי' במשה וישראל במ\"ת ביראה פנימי' ועצמיות ממש כנ\"ל וד\"ל.\n<b>והנה</b> עיקר ההפרש בין ב' מיני עבד לבחי' בן שבחי' בן<sup data-n=\"7287\">272</sup> בקבלת עול דוקא הוא העושה מכח עצמו דוקא דהיינו רק במה שעומד על נפשו לעשות היפוך טבעו ורצונו רק מחמת עול הרצון<sup data-n=\"7288\">273</sup> כנ\"ל, אבל עבודת הבן והעבד הנאמן מחמת פנימי'",[["7268","253","<b>ומפרנסי' גם לאביהם שבשמים</b>: נסמן בהערה הבאה."],["7269","254","<b>קומי לך רעייתי פרנסתי</b>: שה\"ש ב, י. יג. ראה שהש\"ר פ\"א ט, ו (עה\"פ שה\"ש א, ט). בחיי ויקרא א, ט. במדרש שה\"ש (א, טו) הנך יפה רעיתי (ראה שה\"ש זוטא שם). זהר (רע\"מ) צו לג, ב (עה\"פ שה\"ש ה, ב). הנסמן לעיל פ' תצוה שמ, ד הערה 770. בהמשך תרס\"ו (כאן ס\"ע שפג): וכמו רעייתי פרנסתי."],["7270","255","<b>תורה</b>: טז תו\"מ."],["7271","256","<b>והחכמה תחי' בעלי'</b>: קהלת ז, יב [ושם: החכמה — ראה הנסמן לעיל פ' שמות ב, ב]."],["7272","257","<b>דיעקב איש ת\"ם</b>: תולדות כה, כז."],["7273","258","<b>דיעקב. . בקו האמצעי</b>: ראה שע\"ת ס, ב ובהערה 18."],["7274","259","<b>בן פור\"ת יוסף שמפרה ומרבה</b>: ויחי מט, כב וראה בת\"א שם (הובא ברש\"י שם). אגדת בראשית פפ\"ב."],["7275","260","<b>יוסף. . יפ\"ת ויפ\"מ</b>: וישב לט, ו. ראה גם תו\"ח ויחי רמד, ב."],["7276","261","<b>יוסף. . משופרי' דא\"ק</b>: ראה גם שעה\"י קלד, ב ובהערות 45-6."],["7277","262","<b>משיח שנק' מלך הח' הד\"ר</b>: ראה גם לעיל פ' בשלח רלא, ב ובהערה 601."],["7278","263","<b>מלך הח' הד\"ר שהוא שם מ\"ה החדש</b>: נסמן לעיל פ' תשא שפד, ד."],["7279","264","<b>פותר חלומות לתקן לבחי' התהו</b>: ראה תו\"ח ויחי רמג, ג ואילך (ובהנסמן בריש המאמר שם). וישלח קפח, ד ובהערה 48. וראה גם לעיל פ' שמות לח, א ובהערה 14."],["7280","265","<b>שמל\"ך אסו\"ר</b>: שה\"ש ז, ו."],["7281","266","<b>נעשה מלך על כל הארץ</b>: מקץ מא, כג. כד."],["7282","267","<b>וליקט כל הכסף</b>: ויגש מז, יד. ראה פסחים קיט, א."],["7283","268","<b>והטמין ג' מטמונים</b>: ראה פסחים שם."],["7284","270","<b>אוצר הזה</b>: טז: האוצר. יביז: [ה]אוצר העליון הזה."],["7285","269","<b>ויתגלה כל אוצר הזה למשיח</b>: להעיר מתו\"ח וישב רד, ב. ויחי רמז, ג. ותרס\"ו כאן ע' שפד."],["7286","271","<b>למשיח שהוא יוסף</b>: ראה גם לעיל פ' שמות לט, ג. וש\"נ."],["7287","272","<b>בן</b>: טזיז עבד."],["7288","273","<b>הרצון</b>: שם: האדון."]]],[2300550563,"ההתקשרות בעוז אה\"ר לבטל א\"ע כו' אין זה מכח עצמו רק מכח הנמשך בהתקשרות זאת מאהבה דאדון ואב שמושכו אליו ממילא עד שנמשך אחריו ממילא בלי בחירה כו'. וזהו כח התעוררות שפע האלקי' על כל ניצוץ קטן לעוררו מלמעלה עד שמחמת כח זה ילך אח\"כ בכח עצמו בשכל ומדות כו' כנ\"ל (וכך הי' ביצ\"מ שא' לכתך אחרי<sup data-n=\"7289\">274</sup> כו' כבן שהולך אחר אביו <span data-k=\"pg\">תקצד</span> ּ ובמ\"ת שעכ\"ד פרחה נשמתן<sup data-n=\"7290\">275</sup> כו' הי' זה מצד גילוי אור הפנימי' דשם הוי' אליהם כו' כידוע). אך<sup data-n=\"7291\">*276</sup> א\"כ יש להבין איך אמר במשיח שהקים עולה של תו\"מ כו' מאחר שאינו רק בחי' חיצוני'<sup data-n=\"7292\">276</sup> עומ\"ש לבטל טבעו בע\"כ איך יעלה יותר מביטול עצמי' דבן ועבד הנאמן בכל ביתו הנ\"ל. ועוד דלכאו' יש סתירה לענין זה דהקים עולה של תורה<sup data-n=\"7293\">277</sup> דמשמע שהעיקר יהי' במשיח רק עומ\"ש בחיצוני' ולא בפנימי', [והלא] נא' בו והריחו ביראת ה'<sup data-n=\"7294\">278</sup> עד דמורח ודאין<sup data-n=\"7295\">279</sup> כו' שהוא יראה פנימי' ועצמי' בביטול עצמי בגופו כמו בנשמתו ממש לפי שיהי' כלי לאור מל' דא\"ס עצמו שיתגלה אז דוקא וכמ\"ש וע\"י יתיב<sup data-n=\"7296\">280</sup> כו', ולכך יהי' פחד ה' על כל הברואים<sup data-n=\"7297\">281</sup> גשמיי' כמ\"ש וראו כל בשר<sup data-n=\"7298\">282</sup> כו' וכמו ושמ\"ך נור\"א על כל<sup data-n=\"7299\">283</sup> כו' כידוע ובבחי' גילוי אור גדול כזה איך יתכן ענין יראה חיצוני' בעול מ\"ש לבד, ומה גם שהקים עול זה כו' כנ\"ל. אך הנה באמת עיקר בחי' ההתגלות אלקות עצמו בימוהמ\"ש, היינו לפי שיראו הכל בבחי' ראי' חושי' ממש בפנימי' אלקות מה שנביאים לא ראו רק ע\"י הפשטת הגשמי' כו' וגם זה [רק] במרא[ה] כו' בחלום ידבר בו<sup data-n=\"7300\">284</sup> כו', שהרי א' אז ולא ילמדו [עוד] איש את רעהו כו' כי כולם ידעו אותי מקטנם<sup data-n=\"7301\">285</sup> כו' וידיעה זו היא הכרה עצמי' לכולם בשוה ממש ואותי ממש וכמו אל יתהלל חכם<sup data-n=\"7302\">286</sup> כו' כ\"א השכל וידוע אותי<sup data-n=\"7303\">287</sup> כו', וזהו פלא גדול מאין יהי' זה לע\"ל בחי' הזדככות החומר כ\"כ שיוכלו לראות בעיני בשר מ\"ש עכשיו כי לא יראני האדם וחי<sup data-n=\"7304\">288</sup> כו' רק במראה ובחלום כו' כידוע.\n<b>אך</b> הנה יש להקדים ענין א' הידוע ומבואר במ\"א בדרך כלל ענין ההפרש בין גלות לגאולה שהגלות נק' עיבור כמו הרה תקריב ללדת<sup data-n=\"7305\">290</sup> כו' (ובמשנה א' אפילו אתה<sup data-n=\"7306\">291</sup> מתמלא",[["7289","274","<b>לכתך אחרי</b>: ירמי' ב, ב."],["7290","275","<b>שעכ\"ד פרחה נשמתן </b>[טזיז: ליתא]: נסמן לעיל פ' יתרו רנג, ד."],["7291","*276","<b>אך</b>: יב נרשם כאן: ג [ב נרשם לעיל על יד הערה *115. ד נרשם לקמן על יד הערה *380]."],["7292","276","<b>בחי' חיצוני'</b>: טז: חיצוני'. יז: בחיצוני'."],["7293","277","<b>תורה</b>: טז: תו\"מ כו'."],["7294","278","<b>והריחו ביראת ה'</b>: ישעי' יא, ג."],["7295","279","<b>דמורח ודאין</b>: סנהדרין צג, ב. ראה לעיל פ' בשלח קנח, ג הערה 428."],["7296","280","<b>וע\"י יתיב</b>: דניאל ז, ט."],["7297","281","<b>פחד ה' על כל הברואים</b>: ראה גם לעיל פ' בשלח קפה, ב. וש\"נ."],["7298","282","<b>וראו כל בשר</b>: ישעי' מ, ה."],["7299","283","<b>ושמ\"ך נור\"א על כל </b>[יז ניתוסף: מה שבראת]: תפלת העמידה לימים נוראים."],["7300","284","<b>במרא[ה] כו' בחלום ידבר בו</b>: ע\"ד בהעלותך יב, ו."],["7301","285","<b>ולא ילמדו. . מקטנם</b>: ירמי' לא, לג [ושם: למקטנם — ראה לעיל פ' שמות לח, ג הערה 47]."],["7302","286","<b>אל יתהלל חכם</b>: ירמי' ט, כב."],["7303","287","<b>כ\"א השכל וידוע אותי</b>: ירמי' ט, כג [בדילוג]."],["7304","288","<b>כי לא יראני האדם וחי</b>: תשא לג, כ."],["7305","290","<b>הרה תקריב ללדת</b>: ישעי' כו, יז."],["7306","291","<b>ובמשנה א' אפילו אתה</b>: עד\"ז (בשם משנה) מובא בכ\"מ. ראה ברכות כח, ב. כט, ב. לעיל פ' שמות לא, ג הערה 215."]]],[2300550576,"עליהם עברה כאשה עוברה יהיו כ\"צ כו') והגאולה נק' בחי' לידה<sup data-n=\"7307\">289</sup> וכמ\"ש במשיח בני אתה<sup data-n=\"7308\">292</sup> אני היום ילדתיך<sup data-n=\"7309\">293</sup> כו' (ולכך יש בחי' חבלי לידה קודם כמ\"ש תחיל תזעק [בצרות] בחבלי'<sup data-n=\"7310\">294</sup> כן הרינ\"ו חלנו מפניך הוי'<sup data-n=\"7311\">295</sup> קודם שיתגלה האור הגדול בימות המשיח כמ\"ש במ\"א<sup data-n=\"7312\">296</sup> ). והנה מעין בחי' לידה דגאולה אחרונה בימוהמ\"ש הי' כבר בגאולה דמצרים כידוע שבגלות מצרים זה הי' כמו בחי' עיבור הולד בבטן אמו כו' ובגאולת[ם] זהו הי' בבחי' לידה כמו שא' ואעבור עליך ואראך מתבוססת בדמיך ואומר לך בדמייך חיי כו' וכמבואר ביחזקאל<sup data-n=\"7313\">297</sup>, והטעם הוא כי בזמן הגלות נק' ג\"כ בבחי' שינה<sup data-n=\"7314\">298</sup> כמו עורה למה תישן הוי'<sup data-n=\"7315\">299</sup> וכמו היינו כחולמים<sup data-n=\"7316\">300</sup> כו', והענין הוא שבגלות נק' ליל\"ה<sup data-n=\"7317\">301</sup> שזהו דומה לשינה בלילה, [כי ה]שינה בלילה נק' בחי' דורמיטא שהוא בחי' הסתלקות המוחי' ומדות למעלה מעלה ולא נשאר רק בחי' רושם בעלמא רק בדמיון שבמחשבה והבל דפיקו דלבא ונשימה בחוטם כו', ואין באברים חיצוני' חיות מורגש בעצמו ולא תנועה מורגשת ברצון ובחירה רק בהעלם ובקטנות והעינים סגורות כי נעלם כח הראי' או נסתלק<sup data-n=\"7318\">302</sup> למעלה מצד הסתלקות של אור השכל שבמוחי' דעיני' מקבלי' הראי' מן המוחי' כידוע וכן אין באזן השמיעה וכך כל חושי' פנימי' כריח ודבור וכה\"ג גם בחושי' חיצוני' הכל הוא בבחי' הסתלקו' בשינה לגמרי <span data-k=\"pg\">1190</span> ּ כידוע. אך הנה מיד שיק[י]ץ את הישן מתעורר ובהתעוררות שלו מיד יפתח עיניו ויראה ואזנ[י]ו ישמעו ורגליו יהלכו בתנועה ברצון ובחירה כו', וכך ירגיש חיות פנימית בעצמו בכל אברי גופו כאלו חי מחדש ונתהווה מאין ליש כמו ממות לחיים (שבשינה יש א' מס' במות<sup data-n=\"7319\">303</sup> לפי שכמת יחשב בלא תנועה והרגש כו' ועיניו סגורות כו'). אבל באמת יודע אדם בעצמו שאין כל חדש כלל בעיקר מציאות חיותו בקומו מן השינה בבקר כי מה שעיניו יראו כבר יש חיות הראי' בהן ולא נסתלק לגמרי כמות ממש רק שעלה למעלה ונשאר בהעלם ומיד שיפתח עיניו יראה מכח הראי' בעצם כו', וכן כח השכל שנסתלק בשינה אין זה הסתלקות גמורה שא\"כ לא הי' משכיל מאומה וחושב מחשבות בהקיצו רק שנתעלם השכל ומח' ומיד שנתעורר יאיר השכל והמח' וכן הדיבור בפה ושמיעה באזן כו' וכה\"ג, וכל מה שמתפשט הכח בגילוי באברים אינו חידוש מעיקרו רק שנעשה כברי' חדשה כי בשינה לא ראה ולא שמע כו'. ואמנם מה שבהקיצו מיד יראה וישמע וילך כו' הכל מכח עצמות חיות הנפש הוא וא\"כ מי שהקיצו אינו רק שגרם לו שיתעורר משינתו לבדו ויאיר בגילוי אור ולא שעשה בו בהקיצו איזה חידוש בעצם חיותו כלל כו' וד\"ל.",[["7307","289","<b>שהגלות נק' עיבור. . והגאולה. . לידה</b>: ראה גם לעיל יז, ג. וש\"נ."],["7308","292","<b>בני אתה</b>: טזיז: ליתא."],["7309","293","<b>אני היום ילדתיך</b>: תהלים ב, ז. ראה סוכה נב, א. לעיל פ' שמות א, ג הערה 31."],["7310","294","<b>תחיל תזעק. . בחבלי'</b>: ישעי' כו, יז."],["7311","295","<b>כן הרינ\"ו חלנו מפניך הוי'</b>: כ\"ה בכ\"מ. ראה ישעי' כו, יז. יח. לעיל פ' וארא סו, ג הערה 328."],["7312","296","<b>כמ\"ש במ\"א</b>: ראה ד\"ה להבין שרש ענין חבלי משיח נדפס במאמרי אדה\"א קונטרסים ע' רכג ואילך."],["7313","297","<b>ואעבור עליך. . ביחזקאל</b>: טז, ו."],["7314","298","<b>הגלות נק'. . שינה</b>: ראה זהר אמור צה, א. האזינו רפו, א. לעיל פ' שמות לז, ד הערה 4."],["7315","299","<b>עורה למה תישן הוי' </b>[טזיז: ה']: תהלים מד, כד [ושם: אדני — ראה תו\"ח מקץ ריח, ד הערה 72. אוה\"ת שמות כרך ח ע' תתמג]."],["7316","300","<b>היינו כחולמים</b>: תהלים קכו, א."],["7317","301","<b>שבגלות נק' ליל\"ה</b>: ראה זהר אחרי סז, רע\"ב. סה\"מ מלוקט ח\"ב ע' רסו הערה 16."],["7318","302","<b>או נסתלק</b>: טזיז: ונסתלק."],["7319","303","<b>שבשינה יש א' מס' במות</b>: ברכות נז, ב."]]],[2300550587,"[ו]<b> ועפ\"ז</b> יובן ג\"כ בבחי' עיבור הולד בבטן אמו שזהו ג\"כ כמו ענין השינה ממש, דהולד במעי אמו כמו ישן הוא שעיניו סגורים<sup data-n=\"7320\">304</sup> ופיו סתום וראשו בין ברכיו<sup data-n=\"7321\">*305</sup> מקופל כו' ואינו יכול לשמוע ולראות ולעשות תנועה רצוני' בידיו ורגליו רק מעט<sup data-n=\"7322\">305</sup> כאבן דומם כמו שהוא בהתפשטות<sup data-n=\"7323\">306</sup>, ומוחי' שלו שבראש הן בהסתלקות והעלם וכן מדותיו שבלב ורק רושם שבחיות יש<sup data-n=\"7324\">*307</sup> בלבו ובדם האם שמקבל ממה שאמו אוכלת<sup data-n=\"7325\">307</sup> כו'. ועכ\"ז הרי בלידת הולד שיפתחו עיניו מיד ויראה והאזן ישמע ונפתח הפה בקול ויש בו תנועה והרגש בגילוי כברי' בפ\"ע אין כל זה ענין דבר חידוש מעיקרו כלל, כי הרי כח הראי' הי' בעינים בהיותו בבטן בכלי עין המסוגל לזה וכן השמיעה באזן וכל חיות האברים וגם השכל במוח רק שעלו ונסתלקו במקורן בנפש עצמה, וגם זה אינו הסתלקות גמורה רק בחי' ההעלם שנק' מקיף מלמעלה ואינו מאיר בגילוי במוח ועין ואזן אבל הכלים דעין ואזן ומוח מוכנים מיד לקבל הצורה שכבר ישנה בבריאה רק שהיא בהעלם וקטנות (והיינו מה שמקופל ראשו כו' שזהו נק' תלת גו תלת<sup data-n=\"7326\">308</sup> שהמוחי' בהעלם במדות ומדות בנה\"י ולא נשאר רק נה\"י דנה\"י בגילוי כו'), [ו]לכך מיד שנולד ויצא לאויר העולם שנפתח הסתום ועיניו יפקח ויראה אין זה רק שנמשך הראי' הרוחני' בעין מהעלמה בגילוי בלבד כמו שיק[י]ץ אדם מן השינה ויפתח עיניו ויראה שאין בזה חידוש המציאות אע\"פ שהיו עיניו סגורות בשינה כנ\"ל כי העיבור דומה לשינה ממש כנ\"ל.\n<b>ולפ\"ז</b> יובן שיש מעלה בשינה<sup data-n=\"7327\">309</sup> או עיבור אעפ\"י שהכחות הן בהעלם והסתלקות ואינם מאירים בכלים שהן האברים מ\"מ עולים הם במקיף דיחידה ומחמת זה <span data-k=\"pg\">תקצה</span> ּ הוא הגורם אח\"כ להיות המשכות והתיישבות האור בכלי, כמו אור השכל שהוא בשינה בהעלם במקורו מזה יהי' סיבת הארת אור השכל בכלי המוח בהקיצו בכי טוב וכל שישן יותר יותר יצלל דעתו ושכלו וכן העין לראות והרגל להילוך, כי מתחזק כל כחות האברים בכל א' לפי פעולתו ע\"י השינה דוקא עד שנעשה כברי' חדשה כידוע. וכך הוא בענין העיבור שע\"י ט\"ח בעיבורו שכחות שלהם בהעלם במקיף דנר\"נ כו' בקטנות המוחי' דוקא מזה נמשך בלידתו התיישבות המוחי' בראש מעט מעט, וכן כל תוקף האור וחיות בכל אבר לפי טבעו הכל בא מימי העיבור בט\"ח שאם אינו נשלם זמן עיבורו נק' נפל ואינו בן קיימא כידוע, וגם ברוחניות הרי א' שתינוק במעי אמו מלמדי' אותו כל התו'<sup data-n=\"7328\">310</sup> כו', וז\"ש מי",[["7320","304","<b>דהולד במעי אמו. . שעיניו סגורים</b>: ראה ת\"ז ת\"ע קלו, א. לעיל פ' וארא סו, ד הערה 337."],["7321","*305","<b>ופיו סתום וראשו בין ברכיו</b>: נדה ל, ב."],["7322","305","<b>מעט</b>: יבטזיז: מונח."],["7323","306","<b>בהתפשטות</b>: טז: בלי התפשטות. יביז: כבפנים."],["7324","*307","<b>שבחיות יש</b>: טזיז: חיות (יש)."],["7325","307","<b>שמקבל ממה שאמו אוכלת</b>: נדה שם."],["7326","308","<b>תלת גו תלת</b>: נסמן לעיל פ' תצוה שלד, א."],["7327","309","<b>מעלה בשינה</b>: ראה גם לעיל פ' שמות לח, ד. וש\"נ."],["7328","310","<b>שתינוק במעי אמו. . כל התו'</b>: ראה נדה ל, ב. וראה גם לעיל פ' בשלח קפ, ג ובהערה 748."]]],[2300550598,"יתנני כירחי קדם<sup data-n=\"7329\">311</sup> דוקא כו'. ואמנם יתרון מעלה בהקיץ וכן בלידת הולד במה שנמשך האור בכלי בכי טוב כמו ש[י]פקח העין וראי' הטוב<sup data-n=\"7330\">312</sup> והמוח ישכיל ואזן ישמע ויוכל לעשות בכל מלאכה בדעת והבחנה טובה בכל דבר כאדם בר שכל ומדות כו' והרגל והיד פועלי' מלאכתם באור וחיות נגלה, משא\"כ [ב]שינה או עיבור דאעפ\"י שיש ראי' ושמיעה ושכל ומדות במציאותם ממש, אך הן למעלה כלולים במקיף ובלתי מאירים בכלים שזהו כמו הסתלקות הנפש מגוף שעיקר הגרעון הוא בכלי הגוף כו' שלא נק' אדם בר דעת במוחו ולבו והאברים בגשמיות כמו שהוא בעצם נפשו ברוחניות וד\"ל. ונמצא שעיקר ההפרש בין שינה להקיץ וכן<sup data-n=\"7331\">313</sup> עיבור [ללידה] אינו רק ענין הארת האור והתיישבות שלו כמו שהוא ממש ברוחניות יאיר בכלי שיקבל גם הוא הצורה באור הראי' בכלי העין והשכל במוח כו' שבשינה או עיבור אעפ\"י שיש ראי' ושכל הכל בהעלם וברוחניות דמקיף ובהקיץ או בלידה נתגלה מן ההעלם לגילוי בכלי שהוא האבר הגשמי לבד ואין כל חדש בזה כלל בעצם האור רק במה שמתגלה בכלי לבד כנ\"ל.\n<b>אך</b> באמת אין הענין כן דלפ\"ז יש מעלה יתירה בעצם האורות דנפש בשינה ועיבור יותר כנ\"ל כמו כח ואור השכל הרוחני שיתעלה במקורו בנפש עצמה שהוא למעלה מן השכל שמאיר בכלי המוח הגשמי וכמו\"כ כח ואור הראי' הרוחניות מתעלה בעילוי הרוחני' בנפש עצמה וכן בשאר כחות האברים עד שבירידתם אח\"כ בהקיץ מן ההעלם לגילוי ה\"ז בחי' ירידה וצמצום האור בכלי בבחי' קטנות הערך כו', ובאמת נהפוך הוא ממש שבשינה שנסתלק האור הרוחני דשכל ומח' וכה\"ג נעשה בבחי' קטנות מאד בהעלם גדול כמו הדמיון שבמח' שמדמה חלומות שוא ועניני הבל וקטנות ושקר שאין השוטה ומשוגע יחשוב כזה, שהוא היפך גמור מהארת השכל והמח' במוח שאז הוא גדלות האור שמתפשט בכחו הרוחני דוקא להשכיל כל שכל ולחשוב כל דבר עמוק בהבחנה טובה בין טו\"ר וכה\"ג, וכן התפשטות כח הראי' הרוחני' בכלי העין שיראה בהבחנה טובה בכל דבר וכן שמיעת האזן ותנועת היד ורגל באור וחיות טוב מגילוי השכל ורצון שמנהיגם כו'. משא\"כ בשינה הגם שיש שכל ומח' <span data-k=\"pg\">1192</span> ּ וראי' כולם בבחי' הקטנות בתכלית והכלים שהן המוח והעין בלתי מקבלי' הצורה הרוחני' דשכל וראי' כו', וכערך קטנות דנפש הבהמה וכל בע\"ח קטן שגם שרואה בעיניו והולך ברגל[י]ו בחיבור כח רוחני בחומר שלהם אין זה ערך כלל וכלל לראי' והילוך ושמיעה ומח' דאדם אפי' בקטן ותינוק שראי' ושמיעה שלו בכלי עינו ואזנו הכל הוא בבחי' הגדלות דנפש אדם בר שכל ומדות כו', ע\"כ גם בחי' הצורה בחומר שלו נבדל בערך מצו\"ח כעין ואזן דבע\"ח כו'. והוא לפי שזה<sup data-n=\"7332\">314</sup> וזה הן בגדר החי בחומר וצורה [כמו] בראי' העין מ\"מ נפש החי בעצם",[["7329","311","<b>מי יתנני כירחי קדם</b>: איוב כט, ב. ראה גם לקמן תב, ג. מאמרי אדה\"א דברים ח\"ד ע' א'שעו. וש\"נ."],["7330","312","<b>וראי' הטוב</b>: טזיז: ורואה היטב."],["7331","313","<b>וכן</b>: שם: ובין."],["7332","314","<b>שזה</b>: טז: שגם זה. יז: שגם שזה."]]],[2300550609,"בריאה שפילה ונפש שפילה ברוחני', ונפש האדם אף בחי שבו גדול במעלה בבחי' הרוחני' כמו שכל ומדות שבה לכך גם בראי' העין הגשמי אף שמצד כלי חומר העין גשם הוא [כ]כלי עין דבהמה מ\"מ נבדל הוא בערך מן הבהמה אף בכלי חומר העין וכ\"ש בראי' הרוחני' שבה שאין ערך לראי' עין דבהמה כלל<sup data-n=\"7333\">315</sup> לראי' עין האדם כלל מצד נפש האדם שהיא בבחי' הגדלות דאדם ונפש הבהמה בקטנות הערך בדילוג גדול כערך הצומח ודומם לגבי החי ויותר מזה כו'. וכך יובן ערך מעלת מוחי' דגדלות ומדות וראי' ושמיעה ודבור בנפש האדם בהקיץ על בחי' הקטנות דמוחין ומדות וראי' כו' שבשינה, שמלבד שאינו מאיר הראי' בכלי העין כלל אף בגשמיות מצד הסתלקות כחות הנפש כנ\"ל וכן היד לפעולה בלי תנועה חיצוני'<sup data-n=\"7334\">316</sup>, הנה זהו בחי' קטנות עצם הנפש בעצם שמתצמצם השכל והמח' והמדות ונעשי' בבחי' קטנות יותר מקטנות דתינוק ושוטה להיות משוטטת המח' ומדות בעניני קטנות ושקרים ודמיונות. ואעפ\"י שעצם השכל ומדות כלולים בהעלם גדול בעצם הנפש שזה שנק' מקיף, אבל כלולי' בו בקטנות בתכלית כמו שבתינוק גם כל שכלו ומדותיו הן בבחי' קטנות הערך בעניני' קטנים, כי הנפש קטן ושכלו קטן ומדותיו קטנים ואבריו קטנים רק שמתגדל והולך בגידול הצורה וחומר מן ההעלם לגילוי הרי העלם זה נק' קטנות וכן העלם שבשינה נק' קטנות כו'.\n<b>וכך</b> יובן בענין העיבור שנק' בחי' קטנות המוחי' ומדות בתכלית כמו שראשו מקופל כו' כנ\"ל, שזהו בחי' קטנות הנפש בעצם שבתחלת הבריאה דנפש אדם בבטן אמו היא נפש קטנה בערך בעצם הרוחני', לכך גם בחי' כחות שלה כמו כח הראי' ושכל רוחני שבה הן בקטנות בהעלם גדול בעצם הנפש יותר מהעלם וקטנות דשכל התינוק הנולד אף בן יומו שעכ\"פ מאיר קצת אור האחרון מן המוח ושכל בכלי מוחו כמו שאור הראי' מתגלה רוחני' בגשמיות העין לראות כמו בהקיץ באדם גדול, אבל בעיבור אין מוצאי'<sup data-n=\"7335\">317</sup> שכל וראי' ברוחני' כלל כ\"א בהעלם בתכלית הקטנות יותר מדמיונות שבשינה, כי האדם שנתגדל במח' ומדות רק בשינה כלולי' בהעלם בקטנות כנ\"ל נשאר רושם גם מן המח' ומדות שהרי בהקיץ מיד יאיר בו בגילוי. <span data-k=\"pg\">תקצו</span> ּ משא\"כ בעיבור שלא בא עדיין עצם מציאו' הנפש לגדלות כלל רק כפרי שפורח\"ת ועול\"ה בקטנו' בהעלם כו' שאין לו מח' ושכל ומדות כלל רק בהעלם דהעלם כו', והוא שיוצא לגילוי אחר הלידה דוקא בגודל<sup data-n=\"7336\">318</sup> הנפש הזאת בצומח חי<sup data-n=\"7337\">319</sup> מקטנות לגדלות ביניקה ומוחין. אך עכ\"ז הגם שהעיבור והשינה נק' בחי' קטנות והקיצה והלידה נק' גדלות כנ\"ל מ\"מ בכל א' לפי ענינו יוצא מקטנות לגדלות שבחי' ההעלם שבקטנות הוא הגורם הגילוי אור בכלי בגדלות המוחי' ומדות דאדם, וכנ\"ל במה שנראה מן השינה שהסתלקו' המוחי' שנעשי'<sup data-n=\"7338\">320</sup>",[["7333","315","<b>כלל</b>: שם: ליתא. יב: כבפנים."],["7334","316","<b>חיצוני'</b>: טזיז: רצוני'."],["7335","317","<b>מוצאי'</b>: שם: מציאות."],["7336","318","<b>בגודל</b>: שם: בגידול."],["7337","319","<b>בצומח חי</b>: שם: בצו\"ח בצורה וחומר."],["7338","320","<b>שנעשי'</b>: טז: שבשינה."]]],[2300550618,"בקטנות והעלם הוא שגורם אח\"כ גילוי והתיישבות המוחי' בבחי' גדלות בחיזוק האור בכלי להיות כברי' חדשה ממש. וכן בענין של העיבור ולידה דע\"י העלם זמן רב דט\"ח דוקא בבטן אמו שזהו כשינה עי\"ז דוקא נעשה<sup data-n=\"7339\">321</sup> הכלים מוכנים לקבל הצורה הרוחני' בלידה להיות הולך וגדול מקטנות לגדלות בצו\"ח כמו ברוחני' השכל ומדות בגילוי א\"ס<sup data-n=\"7340\">322</sup> כו'. ונמצא דב' הענינים הנ\"ל אמת דודאי אין ערך [כלל] לגדלות דלידה עם קטנות דעיבור וכן מהקיץ לשינה, ומ\"מ אין כל חדש בעיקר דמציאות בגידול זה מקטנות לגדלות שזהו רק כמו גילוי ההעלם דאורות בכלים כנ\"ל וד\"ל.\n<b>ואחר</b> כל הנ\"ל יובן הנמשל מכ\"ז בבחי' הרוחני' דנש\"י בין בחי' עיבור ללידה או מבחי' שינה להקיץ שבזה נמשל ענין הגלות והגאולה ראשונה ואחרונה כנ\"ל, ותחלה יובן בבחי' שינה<sup data-n=\"7341\">323</sup> בגלות דהנה כתיב אני ישינה ולבי ער קול דודי דופק<sup data-n=\"7342\">324</sup> כו', פי' כנ\"י בזמן הגלות ששכינה עמהם בגלות כמאמר גלו לאדום שכינה<sup data-n=\"7343\">326</sup> עמהם<sup data-n=\"7344\">325</sup> וכמו במצרים שא' אנכי ארד עמך<sup data-n=\"7345\">327</sup> כו', ואז או' אני ישינה בבחי' שינה ממש כמו בחי' שינה בגשמיות כנ\"ל דהיינו שבנש\"י הכלולים כולם כא' בציור קומה אחת<sup data-n=\"7346\">328</sup> במל' דאצי' [שנק'] שכינה<sup data-n=\"7347\">329</sup> שה[י]א נק' אם הבנים בכלל כידוע (שכל הנשמות היו בבחי' עיבור שם (כמשי\"ת), הרי בחי' המוחין בהשגת אלקות ומדות אוי\"ר וכל בחי' אברי' דרוחני' הנשמות בכלל הן בבחי' הקטנות בתכלית והוא בבחי' הסתלקות בהעלם גדול כהסתלקות השכל גשמי מן המוח גשמי והראי' מסתלק [מן ה]עין שעיניו סגורים בשינה ואין האוזן שומעת ואין מדות בלב והמח' בדמיונות כו'. כך הוא בבחי' הרוחני' האלקי' דנשמות שהגם שיש בהן מוחין ומדות וראי' ושמיעה רוחני' בבחי' אלקות (כנשמות [בג\"ע] וכה\"ג), אבל הרי הן בבחי' ההעלם והסתלקות בהתכללות מקיף הנעלם שנק' מזלא כו' ואינם מאירים בגילוי או\"כ במוח ולב כלל ולא בעין רואה ואזן שומעת כו' (רק בחי' הקטנו' ברו\"ש כמו דפיקא דלבא בנשימ' בחוטם). וכמו שרואי' בחוש דגם בהתפעלות השכל וההשגה במוח בהתבוננו' והשגת אלקו'<sup data-n=\"7348\">330</sup> כמו איך שמהווה מאין ליש בבחי' ממלא כו', אין השגה זו נתפסת בגילוי גמור במוח הגשמי כמו שמשיג במוחו בדבר הטבעי' שנתאמת ידיעתו ומציאותו בעולם כמו השמים והארץ [ו]אש ורוח, להיות שכל רוחני הבא מאין ליש בכח האלקי [ש]זהו בכח הפועל אלקי בנפעל לא נודע ומושג אמיתי' מציאותו כמו שהוא ממש רק בדמיונות ומשלים שמדמה במח' ושכל שמקרב השגה זו אל השכל, כמו שמדמה <span data-k=\"pg\">1194</span> ּ הדבר הזה לאור וחיות הנפש בגוף או לאותיות הדבור שיוצא ומתגלה לחוץ כך הוא בריאת כל בריא' מאין ליש מכח האלקי. ובאמת",[["7339","321","<b>נעשה</b>: טז: נעשו. יז: נעשי'."],["7340","322","<b>א\"ס</b>: שם: או\"כ."],["7341","323","<b>בבחי' שינה</b>: טז: ענין השינה."],["7342","324","<b>אני ישנה ולבי ער קול דודי דופק</b>: שה\"ש ה, ב."],["7343","326","<b>גלו לאדום שכינה עמהם</b>: ספרי מסעי לה, לד. ראה לעיל פ' שמות א, ד הערה 53."],["7344","325","<b>כמאמר. . שכינה עמהם</b>: טז: ליתא."],["7345","327","<b>אנכי ארד עמך</b>: ויגש מו, ד. ראה גם לעיל פ' וארא פו, ב הערה 884."],["7346","328","<b>שבנש\"י. . בציור קומה אחת</b>: ראה גם לעיל פ' שמות מה, ד. וש\"נ."],["7347","329","<b>במל'. . שכינה</b>: ראה תניא רפנ\"ב. לקמן תג, ג. תכז, ב. תלט, ג. לעיל פ' שמות א, ד הערה 56."],["7348","330","<b>במוח. . אלקו'</b>: טז: אלקית."]]],[2300550624,"אין זה רק כמו דמיון ומשל לבד לקרב הדבר לשכל האנושי אבל לא שמשיג ויודע ומכיר אמיתי' הדבר כמו שהוא למעלה ממש במציאות כח זה האלקי שבורא את הנברא בכל רגע מאין ליש כו', וה\"ז כמו שבשינה מדמה במח' דבר מה מרחוק כאלו רואה ומשיג מהותו ובמעט רגע יתרחק ממנו ידיעה זו. וכן בראי' העין גם שאין<sup data-n=\"7349\">331</sup> השכל שבמוח החכ' יראה בראי' והסתכלות מרחוק לאור האלקי כמו שהוא לאמיתו, אין זה רק בבחי' ההעלם מרחוק ה' נראה לו<sup data-n=\"7350\">332</sup> אמיתת מציאו' שנק' השגת והכרת המציאות שנתאמת ונתברר הדבר בעין השכל ברוחני' שהוא בהעלם מרחוק מאד ולא בראי' מקרוב כאלו רואה בראי' החושי' בעין הגשמי. וכן בהתפעלות האהבה ודביקות [בלב אין זה אהבה ודביקות] האלקי כמו שהוא באמיתי' התקשרות הנשמה למעלה באלקות כניצוץ בשלהבת, אלא רק בדרך דמיון כמו שמדמה בשינה שנתפעל בלב באיזה דבר נחמד וטוב ויקר והקיץ משינתו והי' כחלום יעוף, וכמו שהי' מדמה בנפשו שאכל ושבע לנחת מכל מעדנים ושתה מן יין הטוב והקיץ ונפשו ריקנית מכל והוא ברעב וצמא כו'. וכך הוא בכל עניני פרטי הארות והתפשטות כחות נה\"א בגוף בבחי' הקטנות ו[ב]העלם כמו בשינה, וגם בכל אשר יעשה מצות וילמוד תורה לשמה אין אור דתורה ומצות מאירי' בנפשו בגילוי כמו לנשמות בג\"ע שהכלים שלהם מקבלים הצורה דאור האלקי' כמו שהגוף מקבל צורת נפש הטבעי' ברוחני'<sup data-n=\"7351\">333</sup> ושמיעה בגשמי' כו', ויחי' הנשמה מאור וחיות האלקי שנהנה מזיו השכינה ומאור תורה כו'. משא\"כ באור האלקי בנשמה בגוף בתפלה ותו\"מ בעוה\"ז זהו הכל בבחי' הקטנות כחלום בשינה ולכך יחלוף וישנה מהיפוך להיפוך כמו ממס\"נ בתפלה יהופך לרע בכל היום כמו שיחלום דבר והיפוכו כמות וחיים ברגע א' כמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> בשוב ה' כו' היינו כחולמים<sup data-n=\"7352\">334</sup> שיכירו אז בגאולה שנק' לידה שאז יהי' כלי הגוף מזוככי' כ\"כ שיקבל הצורה האלקי' בראי' עין השכל, שעכשיו בהעלם במח' יאיר בכלי המוח בגילוי עד שיראה אור אלקי זה בראי' חושיי' כמו שיקיץ מן השינה שיפקח עיניו. ועכשיו זהו כעור בעין בראי' האלקי' וגם בחי' הרוחני' דראי' השכל הוא בבחי' העלם בקטנות כמו בשינה וכנ\"ל, בבינה והשגה שבמוח בינה שהיא בחי' שמיעה באוזן כו' כמו שאו' שמע ישראל בהרגשה בחוש השמיעה באלקי' ולא השגה מרחוק לבד, וכמו שמיעה דנשמות בג\"ע לקול דבר אלקי' באור תורה. וכך הי' מעין זה במ\"ת שהיו שומעי' קול אלקי' מדבר כו' הרי היו כלי האוזן והעין מזוככי' לקבל בחי' ראי' ושמיעה באלקו' כמו חושי הטבעי' ממש כראי' ושמיעה גשמי' עכשיו (וכבר הי' לעולמי' קודם חטא עה\"ד באדה\"ר שנפח",[["7349","331","<b>שאין</b>: טזיז: שעין."],["7350","332","<b>מרחוק ה' נראה לו</b>: ירמי' לא, ב."],["7351","333","<b>ברוחני'</b>: טזיז: בראי'."],["7352","334","<b>בשוב ה' כו' היינו כחולמים</b>: תהלים קכו, א."]]],[2300550630,"באפיו נ\"ח דפרחא מחה\"ע<sup data-n=\"7353\">335</sup> ממש שהוא בחי' אלקו' ממש בנשמתו בכלי חומר גופו [ב]עין ואוזן ומוחו ולבו וכה\"ג כמו בבחי' <span data-k=\"pg\">תקצז</span> ּ הרגשה טבעיות ממש (וכמשי\"ת) וד\"ל.\n[ז]<b> והנה</b> עד\"ז יובן כמו ענין ההפרש בכלל בין הגלות שנק' שינה כמ\"ש אני ישינה בגלותא דוקא [ל]זמן בהמ\"ק שהי' גילוי השכינה בארון ולוחות וקרבנות הי' מאיר פנימי' דשם הוי' בכללות נש\"י גם בגופים שלהם כמו בהקיץ שיפקח עיניו ויראה כו', וכן<sup data-n=\"7354\">336</sup> למעלה שהיו עיניו פקוחות כמ\"ש עיני ה' אלקיך בה<sup data-n=\"7355\">337</sup> כו' ולא בבחי' שינה בהסתלקות ההשגחה הפנימי' וכמו שביטל יוחנן כה\"ג לומר<sup data-n=\"7356\">338</sup> עורה<sup data-n=\"7357\">339</sup> כו', שהרי הי' בג' מועדי' עולי רגל בחי' ראי' פב\"פ שיראה כל זכורך<sup data-n=\"7358\">340</sup> את פני כו', והי' גילוי נבואה בנביאים במראה ובהקיץ בגילוי הדבור בפי הנביא ונסים ונפלאות שלמעלה מן הטבע כידוע (אף בגלות בזמן מרדכי ואסתר ובימי חשמונאי בב\"ר<sup data-n=\"7359\">341</sup> כו', משא\"כ עכשיו א' אותותינו לא<sup data-n=\"7360\">342</sup> כו' שמתלבשי' בדרכי הטבע שהוא לבוש שק כמו בחלום בלילה כו', ולכך גם בנש\"י בגופי' נתמעט אור האלקי בנשמתם גם בתפלה ובתו\"מ שלהם ואף ששכינה עמהם ממש זהו בבחי' קטנות דשינה כמ\"ש אני ישינה כו'. וכך יובן ענין [ה]הפרש זה עצמו בין בחי' עיבור ללידה שעכשיו נק' בחי' עיבור, שזהו כמו שנש\"י הן בהתכללות למעלה בבטן אמם שהוא בחי' המל' מקור תולדות נש\"י בהתפשטות שכל ומדות לכאו\"א ונק' אם הבנים כנ\"ל, שזהו כולד בבטן שמקופל ראשו כו' ועיניו סגורים כו', בהסתלקות המוחין ומדות בהעלם בתוך העלם בלתי ראי' ושמיעה והילוך ברוחניות דאלקות כלל כנ\"ל, דגם בחו\"ב ואוי\"ר שכליי' דנשמות בגופי' הוא בקטנות מאד כי אין הכלים מוכנים לקבל הצורה האלקי' כלל (וכמ\"ש למעלה בעיקר ההפרש בין עיבור ללידה ושינה להקיץ זהו רק בגילוי האור בכלי לבד כו'). ועכ\"ז יש מעלה בבחי' עיבור ושינה שכל אורות דנר\"נ דנש\"י למעלה הן עולי' בעלי' בהתכללות דמקיף (וכעובר ירך אמו<sup data-n=\"7361\">343</sup> ואוכל מה שאמו אוכלת כו' מטבורו דוקא כמ\"ש במ\"א בפ' וארא<sup data-n=\"7362\">344</sup> כו' באורך), ומחמת בחי' עלי' והתכללות זו הוא שנמשך אח\"כ מקטנות לגדלות בהולדו ביניק' וגדלו' כו' וכמו שבשינה הרבה יתחזק כח השכל להתיישב בצלילו' יותר בכלי המוח וכן בראי' בעין ושמיעה באוזן ויהי' כברי' חדשה וכ\"ש בלידת הולד שיהי' כבריה חדשה כו'.",[["7353","335","<b>באדה\"ר שנפח באפיו נ\"ח דפרחא מחה\"ע</b>: בראשית ב, ז. ראה זהר תרומה קלח, א. לעיל פ' שמות מ, ב. וש\"נ."],["7354","336","<b>וכן</b>: טזיז: וכמו."],["7355","337","<b>עיני ה' אלקיך בה</b>: עקב יא, יב."],["7356","338","<b>שביטל יוחנן כה\"ג לומר עורה</b>: ראה סוטה מז, סע\"א. מח, א. מאמרי אדה\"א נ\"ך ע' רצט ואילך. ע' תג. וש\"נ."],["7357","339","<b>עורה </b>[טז ניתוסף: למה תישן]: תהלים מד, כד."],["7358","340","<b>שיראה כל זכורך</b>: פ' ראה טז, טז. משפטים כג, יז. תשא לד, כג."],["7359","341","<b>בב\"ר</b>: יב: בבית שני. טזיז: בב\"ש."],["7360","342","<b>אותותינו לא</b>: תהלים עד, ט."],["7361","343","<b>וכעובר ירך אמו</b>: גיטין כג, ב."],["7362","344","<b>ואוכל. . מטבורו. . בפ' וארא</b>: לעיל פ' וארא סז, א."]]],[2300550636,"<b>וכך</b> יובן בהפרש זה ברוחני' דנשמות בהיותם עתה בבחי' עיבור שמזה יהי' דוקא בחי' גילוי הצורה בחומר שיהי' החומר מוכן לקבל הצורה בכי טוב והוא מה שיהי' אור השכל שבמוח משיג ורואה באלקות כמו בחוש הטבעי וכן בראי' שבעין ושמיעה שבאוזן כו' כולד שנולד שנפקחו עיניו הסגורים ויראה אור גשמי וישמע באזניו כו', כך יראו אור האלקי לע\"ל בידיעה והכרה עצמי' כמ\"ש וראו כ\"ב כי פי הוי' כו' וכולם ידעו אותי<sup data-n=\"7363\">345</sup> ממש בלי אמצעי כלל דהיינו לא דרך השתלשלו' דחו\"ב בחי' אין ויש שנמשך האור האלקי בלבוש מסתיר אלא אמיתת עצמותו <span data-k=\"pg\">1196</span> ּ יתגלה בראי' והכרה עצמי' ממש וכמו וידע כ\"פ<sup data-n=\"7364\">346</sup> כו'. וזהו שא' ולא ילמדו עוד איש את רעהו כו' שאינו צריך להשגת שכל ברוחניות ובהעלם דבר כי יאיר אור האלקי בכלי הגוף שלהם כמו טבעי' ממש, ולכך כולם ידעו ויכירו אותו מקטנם כו' בשוה לקטני' בחכ' לגדולי' כי יהי' זה בהכרה וידיעה טבעי', כמו ידע שור קונהו<sup data-n=\"7365\">347</sup> כו' כי גם בהמות וחיות יהי' בהן בחי' הביטול לאלקות כי ידע כ\"פ כו' בטבעיות ולא בלמודי' בשכל או בהפשטת הגשמי' כנביאי' עכשיו כו' (וכמ\"ש אנו כחמורי' ולא כחמורו של רפב\"י<sup data-n=\"7366\">348</sup> שנשאר מבהמות שקודם חטא עה\"ד שלא נמשך רע וחושך המסתיר אלקות כלל, וכמו שהי' בג\"ע שא' ה' אל הנחש<sup data-n=\"7367\">349</sup> כו' והי' קול אלקי' מתהלך בגן<sup data-n=\"7368\">350</sup> ודיבר עם קין<sup data-n=\"7369\">351</sup> שלא כדבר ה' עם נביאי' אלא כאשר ידבר איש<sup data-n=\"7370\">352</sup> כו', לפי שהי' גופם מופשט מן החומרי' דעכשיו והי' מזוככי' בתכלית להיות כלי ממש לאור ורוח האלקי<sup data-n=\"7371\">353</sup> שהי' בנפשם בגילוי אור וחיות כטבעי' ממש, והן היו בני האלקי'<sup data-n=\"7372\">354</sup> הגבורים אשר מעולם<sup data-n=\"7373\">355</sup> כו' וכמ\"ש בקין קניתי איש את הוי'<sup data-n=\"7374\">356</sup> ממש עד שחטא בעה\"ד ונתערב רע בטוב<sup data-n=\"7375\">357</sup> והלכו גם בני אלקי' אחר תאוות חומרי' כמו בדור המבול אמר לא ידו\"ן רוח\"י עוד באדם בשגם<sup data-n=\"7376\">358</sup> הוא בשר כו' דמשמע שקודם לזה הי' רוח אלקי' ממש בנפשם וגופם כא' ונק' בני האלקי' ממש (ולכך האריכו ימים ושנים שלא לפי הטבע האנושי' דעכשיו). וכמו שהי' קודם החטא באדם ובבהמה כך יהי' לאחר בירור דעה\"ד בשלימות (שחשמל דנוג\"ה יהי' זך ובהיר וכמו כתנו\"ת או\"ר<sup data-n=\"7377\">359</sup> בא[ל\"ף]<sup data-n=\"7378\">360</sup> כו' והוא לבוש דנה\"ט יהי' זך ובהיר לקבל אור האלקי בלבוש זך דנשמות בג\"ע דעשי' עכשיו (שיש שם כל חלקי דצח\"ם<sup data-n=\"7379\">361</sup> גם עתה כידוע). וא\"כ לא יפלא כלל על מה שיהי' בימות המשיח הזדככות החומר כ\"כ באדם עד שיהי' ג\"כ בכלי גופו בחי' ראי'",[["7363","345","<b>וכולם ידעו אותי</b>: ירמי' לא, לג."],["7364","346","<b>וידע כ\"פ</b>: תפלת העמידה לר\"ה."],["7365","347","<b>ידע שור קונהו</b>: ישעי' א, ג."],["7366","348","<b>אנו כחמורי'. . רפב\"י</b>: שבת קיב, ב. ראה גם לעיל פ' בשלח קצה, ד הערה 595."],["7367","349","<b>שא' ה' אל הנחש</b>: בראשית ג, יד. ראה גם לעיל פ' בשלח קצו, א."],["7368","350","<b>קול אלקי' מתהלך בגן</b>: בראשית ג, ח."],["7369","351","<b>ודיבר עם קין</b>: בראשית ד, ט."],["7370","352","<b>כאשר ידבר איש</b>: לשון הכתוב תשא לג, יא."],["7371","353","<b>ורוח האלקי</b>: טז: וחיות אלקי. יז: האלקי."],["7372","354","<b>והן היו בני האלקי'</b>: ראה גם לעיל פ' בשלח קס, ד."],["7373","355","<b>בני האלקי' הגבורים אשר מעולם</b>: בראשית ו, ד [בדילוג]."],["7374","356","<b>קניתי איש את הוי'</b>: בראשית ד, א."],["7375","357","<b>שחטא בעה\"ד ונתערב רע בטוב</b>: ראה לעיל פ' שמות מ, ב. וש\"נ."],["7376","358","<b>לא ידו\"ן רוח\"י עוד באדם בשגם</b>: בראשית ו, ג [ושם: רוחי באדם לעולם בשגם — ראה גם לעיל פ' בשלח קנד, א. טז: עוד רוחי — ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'ס]."],["7377","359","<b>שחשמל דנוג\"ה. . כתנו\"ת או\"ר</b>: ראה גם לעיל פ' בשלח קנח, ב. וש\"נ. (לקמן הערה 537)."],["7378","360","<b>כתנו\"ת או\"ר בא[ל\"ף]</b>: נסמן לעיל פ' משפטים רפז, ב."],["7379","361","<b>בג\"ע. . כל חלקי דצח\"ם</b>: ראה גם אוה\"ת בראשית כרך ז ע' תתשסג ואילך."]]],[2300550642,"ושמיעה רוחני' האלקי' ממש כמו בנשמה ויותר הרבה מזה וכמו דמיון שהולד נולד שיפקח עיניו ויראה כנ\"ל וד\"ל.\n<b>וזהו</b> בחי' גדלות המוחי' ומדות האלקיי' שיהי' אז בנשמות בכלל בבחי' לידה כנ\"ל שזהו ממש כמו התינוק הנולד שיגדל בשכלו וגופו כא' וכל מה ש[י]הי' גילוי אלקות בנש\"י באוי\"ר והשגו' שלהם ואף בתו\"מ בזמן הגלות נק' ממש<sup data-n=\"7380\">362</sup> בחי' עיבור דקטנות לבד (תלת גו תלת כנ\"ל), ומבואר למעלה דב' העניני' אמת בענין קטנות וגדלות דעיבור ולידה או שינה והקיץ דודאי אין ערך כלל לקטנות דעיבור ושינה לגבי גדלות המוחי' והכלים דלידה או הקיץ, ומ\"מ עיקר הגורם כל מה שיהי' בחי' הגדלות דלידה והקיץ הוא בא מבחי' הקטנות דעיבור ושינה שאין זה אלא כיוצא מהעלם דמקיף שבקטנות לגילוי או\"כ בהתפשטו' גדולה בלידה והקיץ שאין חידוש מעיקרו בזה משום דהא בהא תליא דוקא. וכך יובן בדרך כלל גם <span data-k=\"pg\">תקצח</span> ּ בבחי' הרוחני' דנשמות בענין קטנות שלהם בעיבור ושינה שיוצא מזה בחי' הגדלות דלידה בימות המשיח וכמו שהי' הפרש זה בין יצ\"מ למ\"ת מקטנות לגדלות כמ\"ש רבבה כו' (כמ\"ש במ\"א<sup data-n=\"7381\">363</sup> ), וז\"ש העם ההולכים בחשך דגלות ראו או\"ר גדו\"ל<sup data-n=\"7382\">364</sup> (וכמו ותחלימנ\"י ותחיינ\"י<sup data-n=\"7383\">365</sup> וכשינה דחוני המעגל<sup data-n=\"7384\">366</sup> כו'). וז\"ש במשיח אני היום ילדתיך שהוא בכללות נש\"י שיפקחו עיניהם כו' כמו במ\"ת שהי' קצת מעין זה כנ\"ל (וזהו ישכיל עבד\"י כו' בגדלות המוחי' ומדות בפנימי' התוה\"ק (מ\"ה החדש<sup data-n=\"7385\">367</sup> מקור התיקון כמשי\"ת) שבא[ה] בריבוי הכלים שיקבלו האור הגדול שלא הי' זה גם במ\"ת שעכ\"ד כו', וזהו רק מחמת עולה של תו\"מ לעשות היפוך הטבע כנ\"ל (וכמשי\"ת).\n<b>וזהו</b> מ\"ש אני ישינה ולבי ער קול דודי דופק פתחי לי כו', דהנה הגם שמבואר למעלה בכל ענין גילוי אלקות בנש\"י בגלות זהו בבחי' שינה בקטנות המוחי' ומדות בתכלית כנ\"ל מ\"מ אמר ולבי ער כו', והיינו דגם בשעת שינה שאז הסתלקו' [ה]מוחי' ומדות ולא נשאר רק בחי' נה\"י שבנה\"י שזהו אוי\"ר טבעיות שבמעשה מצד עצמה (כמשי\"ת), אבל לבי ער שזהו בחי' נקודת פנימי' ועצמ[י'] הלב דבחי' יחידה דנה\"א שלמעלה מכל התפעלות רצון ושכל ומדות אלא הוא עצמיות הנפש ממש שחבוקה ודבוקה תמיד למעלה באלקות, ואין בה שינוי כלל בין קטנות לגדלות דקטנות וגדלות לא שייך רק בהתפשטות דרצון ושכל ומדות ומחדו\"מ שהוא בחי' ציור אדם במוחי' כו'. ובזה יש הפרש בין שינה שמסתלק השכל ונשאר רק בקטנות דנה\"י החיצוני' ובין הקיץ או בין עיבור ללידה כנ\"ל, אבל בעצמות דיחידה לבי ער תמיד אפילו בשינה. וכמו גם בזמן הגלות דנש\"י",[["7380","362","<b>ממש</b>: טז: ליתא. יז: רק."],["7381","363","<b>רבבה. . במ\"א</b>: יחזקאל טז, ז. ראה גם לעיל פ' וארא סט, א. פ' בשלח קלו, ג."],["7382","364","<b>העם ההולכים בחשך. . ראו או\"ר גדו\"ל</b>: ישעי' ט, א."],["7383","365","<b>ותחלימנ\"י ותחיינ\"י</b>: ישעי' לח, טז [ושם: והחייני — ראה לעיל פ' שמות לט, א. וש\"נ]."],["7384","366","<b>וכשינה דחוני המעגל</b>: תענית כג, א. ראה גם לעיל פ' שמות לט, א."],["7385","367","<b>מ\"ה החדש</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"ב ואילך."]]],[2300550648,"בתכלית הקטנות מאד ברצון ושכל ומדות באוי\"ר ותו\"מ, מ\"מ נקודת עצם יהדותם בעצמות דיחידה קיים להיות מזה מקור כל רצון אף במס\"נ למעלה מן הכלי והטעם. ואמנם מלובש זה הכח בהעלם גדול ודוקא בסוף מעשה בנה\"י שבנה\"י שנשאר גם בגלות שנק' שינה או עיבור, והוא בעצם המעשה דמצות לבד אוי\"ר שבהן שע[י]\"ז דוקא יש בכחם לבא למס\"נ כמו שהי' בימי חשמונאי שרצו להשכיחם תו\"מ, ומס\"נ כו' כי נעוץ תב\"ס<sup data-n=\"7386\">368</sup> דוקא. וזהו ולבי ער גם בגלות ע\"כ קול דודי דופק שהוא בגאולה שיעורר מן השינה והגלות כמו אדם הישן בתוקף השינה ובא איש ומעוררו מן השינה ע\"י דפיקו שדופק עליו, וזהו רבותא גדולה דודאי בשינה גובר העלאה דאו\"ח לעלות וליכלל במקיף דיחידה אף המקור דשכל ורצון ומדות<sup data-n=\"7387\">369</sup> (והחלומות גוברי' מצד המקיף שכולל כל מיני רצון ושכל כו' אלא שמתחלף הסדר דהרהורי לבו כו' וכמ\"ש במ\"א בשרש החלומות שהן בבחי' מקיפים דעיגולים דתהו<sup data-n=\"7388\">370</sup> שזהו בגלות בלבוש שק דקדרו\"ת באהלי קד\"ר<sup data-n=\"7389\">371</sup> ופותר חלומות להביא הכל לבחי' התיקון באו\"כ מחדש <span data-k=\"pg\">1198</span> ּ שזהו ע\"י שם מ\"ה החדש מבחי' מלך הח' הד\"ר שהוא צ\"ע כיוסף<sup data-n=\"7390\">372</sup> ומשיח שישכיל עבד\"י ויעשה ריבוי או\"כ מחלומות דתהו שבגלות).\n<b>וזהו</b> קול דודי כו' שיש כח העליון יותר מכל בחי' אדם (דתהו ותיקון) לעוררו מן השינה בהתעוררות שמצד עצמות [א]א\"ס שמעורר לבחי' יחידה לפי שלבו ער, ויש שם נקודות עצמיות<sup data-n=\"7391\">373</sup> דאו\"מ זה וגובר כח המעורר הזה בדפיקו שלו להיות מתעורר [אדם] מן השינה להביאו לבחי' הירידה והמשכה דאו\"י מעצמות הנפש להאיר ברצון [ו]שכל ומדות בבחי' הגדלות בהקיצו שזהו מהיפוך להיפוך מאו\"ח לאו\"י שהן בהפכי'<sup data-n=\"7392\">374</sup> ומקטנות לגדלות. וכך הוא בכנ\"י שמעוררים אותם מעצמות א\"ס להתעורר מן השינה והקטנות ויפקחו עיני ראיה ושמיעה והילוך כמו בהקיץ כנ\"ל וכמו בחי' לידה שיהי' לע\"ל, וז\"ש קול דודי דופק ל' הוה שגם עתה יש קול המעורר והוא כח העליון המעורר בתש\"ע שיאיר מזה אור דגדלות המוחי' ומדות בראי' ושמיעה כמו בכל ר\"ה ועשי\"ת שיעורר נקודה דיחידה להאיר בגילוי במוחי' ומדות כו', וכן בכל יום בכל בקר מתעורר אדם מן השינה גם [ב]נשמתו שהיה בשינה [ב]בחי' הסתלקות א' מס' במות בתכלית הקטנות ובהקיצו יאיר כח חדש בשכל ומדות באלקות כברי' חדשה כמ\"ש חדשים לבקרים בכל בקר רבה אמונתיך דמקיף דיחידה, וכמ\"ש אך בצלם יתהלך איש<sup data-n=\"7393\">375</sup> במ\"ם דצלם ילך בהשגות במוחי' והתפעלות במדות ומדו\"מ כל היום בתו\"מ, והוא הכח המעוררו מן השינה ע\"י קול דודי דופק כו' פתחי לי להיות גילוי אלקות באו\"כ ממש כו' כמו שיהי' לע\"ל כנ\"ל. והגם שבודאי",[["7386","368","<b>נעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["7387","369","<b>המקור. . ומדות</b>: טז: במקור הרצון דשכל ומדות."],["7388","370","<b>החלומות. . דתהו</b>: ראה גם לעיל שצט, א ובהערה 264."],["7389","371","<b>באהלי קד\"ר</b>: ע\"פ שה\"ש א, ה."],["7390","372","<b>מלך הח' הד\"ר. . כיוסף</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'שפו. וש\"נ."],["7391","373","<b>נקודות עצמיות</b>: טזיז: נקודה עצמי'."],["7392","374","<b>בהפכי'</b>: שם: ב' הפכים."],["7393","375","<b>אך בצלם יתהלך איש</b>: תהלים לט, ז. ראה מאמרי אדה\"א דברים ח\"ב ע' תצח ואילך ובהנסמן בריש המאמר שם."]]],[2300550654,"אין ערך כלל לשינה שא\"י לעשות מלאכה ולא ישמע ויבין כו' להקיץ שעושה מלאכה בדעת ויראה וישמע ויבין כו', מ\"מ הסיבה שגרם כל זה אינו רק בחי' כח ההתעוררות שעוררו אותו והוא בבחי' המקיף דיחידה הנ\"ל מלמעלה ממנו כנ\"ל וד\"ל.\n<b>אך</b> הנה הגם שמצד ההתעוררות העליונה האלקי' הוא שמתעוררים כנ\"י מן השינה להיות בגילוי אור ברצון ושכל ומדות באלקות בבחי' ראיה ושמיעה וגם בהילוך ברגל שהוא מעשה המצות, אבל העיקר הוא מה שאחר ההתעוררו' מלמעלה יוכל אדם לראות בראי' דחכ' האלקי' ובשמיעה דבינה וגם בהילוך ומו\"ד כו' הכל מכח עצמו דוקא ולא מצד כח העליון האלקי כלל (ולכך נק' אד\"ם אדמ\"ה לעליון<sup data-n=\"7394\">376</sup> בצל\"ם אלקי'<sup data-n=\"7395\">377</sup> כמו שיהי' לע\"ל כנ\"ל), שהרי נראה זה מן משל השינה גשמי' אע\"פ שאדם שהקיצו מן השינה גרם לו כל זה שרואה בעין ושומע והולך כו', מ\"מ מה שאחר הקיצו עושה מלאכה ורואה ושומע אין עיקר מציאות כח זה מצד האדם שהקיצו רק מכח עצמו שכבר הי' בנפשו וגופו כל עיקר מציאות כחות הללו דראיה ושמיעה כו', רק שהי' בשינה בהסתלקות והתכללות למעלה בעצמות הנפש וע\"י התעוררות זו שהקיצו האדם גרם לו שיתגלה הכל מן ההעלם דמקיף בכל אברי <span data-k=\"pg\">תקצט</span> ּ גופו כו'. וכך יובן למעלה בענין כח ההתעוררות העליון מלמעלה לעורר לנש\"י מן בחי' השינה (כמו בכל חצות דבטש בגדפוהי<sup data-n=\"7396\">378</sup> כו', וכן הקיצו שוכני עפר<sup data-n=\"7397\">379</sup> שיעוררו בתחה\"מ לע\"ל) אינו אלא גרם שיאיר האור דמוחי' ומדות מן ההעלם לגילוי באו\"כ, ומה שיאיר אור השכל והשגה בחו\"ב ובראי' האלקי' וכן בהילוך בתו\"מ כל היום אחר ההתעוררות בבקר כנ\"ל, זהו הכל מכח עצמם שכבר יש בנפשם כל זה בעצם הנשמה רק שיצא מהעלם דמקיף דיחידה לגילוי באו\"כ (ואע\"פ שמבואר למעלה דבשינה ועיבור זהו בחי' הקטנות בעצם כברי' שפילה כערך הבהמה לאדם ותינוק לגדול והקיץ ולידה נק' גדלות בעצם כנ\"ל, עכ\"ז מה שיוצא מקטנות לגדלות זהו כמו הגילוי מן ההעלם לבד ואם לא בחי' הקטנות בעיבור או שינה לא היה מתגדל [בגדלות] כנ\"ל, ונמצא דבחי' הגדלות בראיה ושמיעה זהו כח עצמ[י] דוקא רק שיצא מהעלם דקטנות לגילוי בלבד כו'). ונמצא דמה שילך אדם במעשה המצות ובתורה ויראה ואהבה בחו\"ב זהו העיקר שהוא בא מכח עצמו ביגיעה בשכל ולב שנק' עובד אלקים, והיינו מה שאחר הדפיקו והתעוררות שמעוררים בתשו\"ע ולמעלה הולכים כל אחד ואחד מישראל מכח זה באור וכח עצמם בבחי' אור וחיות אלקות בגילוי בכלי גופם במוחם ולבם הגשמי' גם מצד עצמם, כמו שהלב רואה ראי' עין השכל ושומע ומבין ויש בו כח ההילוך בדרך הוי' [כ]עושה מלאכה בדעת כאדם כו', שאם הי'",[["7394","376","<b>אד\"ם אדמ\"ה לעליון</b>: נסמן לעיל פ' יתרו רסב, א."],["7395","377","<b>אד\"ם. . בצל\"ם אלקי'</b>: בראשית א, כז. נח ט, ו."],["7396","378","<b>בכל חצות דבטש בגדפוהי</b>: ראה לעיל פ' וארא עד, ד ובהערה 166."],["7397","379","<b>הקיצו שוכני עפר</b>: ישעי' כו, יט [בדילוג. ראה גם שע\"ת כו, יט]. טז: הקיצו ורננו כל שוכני עפר."]]],[2300550660,"כח הילוך זה וראי' ושמיעה רק מכח ההתעוררות העליונה דקול דודי דופק כו' הנ\"ל הרי אין כאן ענין הבחירה באדם כלל ואינו נק' אדם אלא מצד הבחירה שיש בכח עצמו דוקא דאדם אדמה לעליון ממש כו' וד\"ל.\n<b>ואמנם</b><sup data-n=\"7398\">*380</sup> הנה הגם שהעיקר הוא מה שיש בכח עצמו של הניצוץ אלקי לילך בתו\"מ ואוי\"ר ביגיע' אחר הדפיקו וההתעוררות העליון כנ\"ל במשל המעורר מן השינה שאינו אלא גורם כו', מ\"מ אין הענין כן למעלה, דודאי כל מה שיש ביכולת כח הנשמה מצד עצמה בהילוך מדרגות באלקות באור תורה ועבודה אין כל זה רק בבחי' הגבו[ל] כפי עצם הנשמה שהיא נברא מאין ליש כו' ואין לה ערך כלל וכלל לכח העליון האלקי שמעורר הנשמה מלמעלה שהוא כח בלתי בע\"ג כלל כמ\"ש גדול אדונינו ורב כח<sup data-n=\"7399\">380</sup> כו' ואין בו קץ וגבול כמו לא ייעף ולא ייגע<sup data-n=\"7400\">381</sup> כו', וא\"כ ממילא מובן מה שנמשך [שפע ו]המשכה אלקי' בכח ההתעוררו' [לעורר] לנש\"י מבחי' השינה זהו בלתי גבול כלל, והוא גם במה שנמשך דרך פרט כמו לעורר הכוונה שבמוח בהשגה אלקי' ולפתוח הלב באוי\"ר וכה\"ג שאין בזה גבול ושיעור כלל כפי עצם כח הא\"ס שהוא בלתי בע\"ג, ואין ערך כלל ליגיעת כח הנשמה בכח עצמה להגיע לזה כי כל כחה מוגבל ומחודש ונק' עבודה גבולי' כו'. ומלבד זה הרי אנו רואי' שנש\"י הן בחי' מקבל כאשה שמקבלת מאיש <span data-k=\"pg\">1200</span> ּ כו' וכלבנה מן השמש וכה\"ג דלית לה מגרמה כלום<sup data-n=\"7401\">382</sup> רק מה שמקבלת מן המשפיע כידוע. וכך הוא בענין זה דשינה שאנו רואים בחוש שכל משך זמן שיהי' אדם בכח ההילוך וראי' כו' בהקיץ, זהו רק כפי ערך כח ההתעוררו' משינה שהוא כח המקיף דמזלא שמחדש אור חיותו להיות כברי' חדשה בכל כח[ות] שלו במוח ולב וראי' והילוך כו' כל היום. וכך הוא ברוחניות דנשמות שכל מה שימצא בכח עצמם בהשגות אלקות והילוך וראי' כו' כל היום ביגיעה שבמוח ולב אע\"פ שנראה כ\"ז רק מכח עצמם דוקא מטעם הנ\"ל, מ\"מ כל היגיעה והילוך הזה הוא בא רק מכח הדפיקו וההתעוררות שבאה מלמעלה דהיינו לפ\"ע כח שפע התעוררות זו אם רב או מעט ואם בכלל או בפרט (להיותו כח העליון מתהו ותיקון דאד\"ם כנ\"ל) להיות[ו] בלתי בע\"ג, והוא הנותן כח ועוז בנשמות בע\"ג<sup data-n=\"7402\">383</sup> שילכו לכחו ואורו כל היום דוקא ובכלות אור וכח העליון הזה יפסיק כח ההילוך ויגיע' האדם שמצד עצמו [כ]נוק' שמקבלת רק מה שניתן לה מכח המשפיע כנ\"ל וד\"ל. וראי' לזה ממה שאנו רואים בחוש בכל אדם בקומו בבקר שיחודש חיותו כנ\"ל, שלפעמים יקום בעוצב ומרירות או קטנות [ה]מוח והלב [ו]רוגז או בהיפוך שיקום בשמחה ורוחב הלב והמוח וחסד וטוב כו', והיינו לפי מה",[["7398","*380","<b>ואמנם</b>: יב נרשם כאן: ד [ג נרשם לעיל על יד הערה *276. ה נרשם לקמן על יד הערה *422]."],["7399","380","<b>גדול אדונינו ורב כח</b>: תהלים קמז, ה."],["7400","381","<b>לא ייעף ולא ייגע</b>: ישעי' מ, כח."],["7401","382","<b>וכלבנה. . דלית לה מגרמה כלום</b>: ראה גם לעיל פ' יתרו רנד, ד ובהערה 252."],["7402","383","<b>בע\"ג</b>: טזיז: כו'."]]],[2300550666,"שקיבלה הנפש עצמה אופן גילוי אור חיותה ממקורה בהשוטטה במקורה המעוררה לבא בגילוי מן ההעלם בעת השינה כך יהי' אופן גילוי אור חיות כחות שלה בהקיצה באברי' כמו במוח ולב, אם בשמחה או בעוצב ומשך זמן מוגבל עד כלות אור וכח הזה באופן פרטי [שקיבלה] בשינה דוקא. וכך הוא בענין קול דודי דופק שיש חידוש אופן בכל בקר ובקר לכל נשמה בהקיצה שתאיר במוח ולב אם בעוצב ושפלות בעבודה שבלב ומוח בתפלה או בשמחה כו' הכל לפי האופן שהי' בחי' קבלת השפע דיחידה שבה בשינה מקול דודי דופק כו' וד\"ל.\n[ח]<b> והנה</b> לפ\"ז יובן ג\"כ עד\"ז בענין עיבור ולידה ג\"כ שכל מה שיהי' בלידה אופן התגלות הצורה בחומר כמו ברי' חדשה במוחי' ומדות וראי' ושמיעה והילוך בכח עצמו דוקא הכל הוא ע\"פ כח העליון במקיף דיחידה שכלולי' בו כל הכחות דמוחי' ומדות וכחו' האברי' כראי' ושמיעה בהעלם דקטנות כו', שלפי אופן הגבלה<sup data-n=\"7403\">384</sup> שלהם בהעלותם והתכללותם בהעלם זה דמקיף העליון בכל ימי העיבור (שאוכל מה שאמו אוכלת כו' ונכלל במוחי' ומדות דאימא ממש), כך יהי' אח\"כ התגלות או\"כ בנר\"נ ואברי' בלידתו להיות גידול המוחי' ומדות ואברי' בצו\"ח<sup data-n=\"7404\">385</sup> שלהם כמו שכפי הגבלה דנפש בהושטטה בשינה במקורה במקיף כך יהי' הארת אור בגילוי בגוף בהקיצו כל משך זמן שיאיר האורות בכלי[ם] כל היום כנ\"ל. ולפ\"ז יובן דאע\"פ שהגאולה דכנ\"י נק' בחי' לידה כמו שהי' במצרים כנ\"ל שנש\"י יהיו בבחי' ראי' ושמיעה ושכל ומדות באלקות <span data-k=\"pg\">תר</span> ּ בטבעיות באברי הגוף כנ\"ל במ\"ש כולם ידעו אותי כו', מ\"מ כל סיבת גילוי אור האלקי הזה בפרטי אופניו בכל נשמה במדרגה ואופן מיוחד הכל הוא עפ\"י אותו הכח העליון שהאיר בהעלם דמקיף דאימא בהיות כללות נש\"י בבחי' עיבור בזמן הגלות כנ\"ל [כולד] מקופל כו' שהכל הי' בהעלם בתוך העלם במקיפים דיחידה כמו בשינה ממש כנ\"ל, ולפי אופן קבלה זו במקורם באימא עילאה כל זמן הגלות באוי\"ר ותו\"מ כו' כנ\"ל כך יהי' אופן הגילוי דאור הגדול בנשמות לע\"ל בכאו\"א כו' וד\"ל (וזהו כמו התינוק בבטן אמו שמלמדי' אותו כל התורה כו' שזהו בבחי' מקיף דיחידה שבו בחי' מ\"ם דצלם שבכח זה שקיבל בהעלם דהעלם הוא שנמשך אח\"כ לגילוי אור מעט מעט<sup data-n=\"7405\">386</sup> בלידתו מקטנות לגדלות כל ימי חייו עד שנעשה זקן שקנה חכמה<sup data-n=\"7406\">387</sup> בגילוי מן ההעלם דח\"ס כו', וזהו מי יתנני כירחי קדם כו' ונק' חד\"ר הורת\"י<sup data-n=\"7407\">388</sup> כו' וכמ\"ש בזהר להרת\"ם כתיב<sup data-n=\"7408\">389</sup> דזהו בחי' עיבור דתו\"מ בקטנות דנה\"י לענין מעשה לבד וכך בנש\"י אין הגילוי רק [ב]בחי' נה\"י בקטנות",[["7403","384","<b>הגבלה</b>: שם: הקבלה."],["7404","385","<b>בצו\"ח</b>: טז: בצורה וחומר."],["7405","386","<b>התינוק. . כל התורה. . שקיבל בהעלם. . לגילוי אור מעט מעט</b>: ראה גם לעיל פ' בא קכט, א הערה 762."],["7406","387","<b>זקן שקנה חכמה</b>: נסמן לעיל פ' משפטים ש, ב."],["7407","388","<b>חד\"ר הורת\"י</b>: שה\"ש ג, ד."],["7408","389","<b>בזהר להרת\"ם כתיב</b>: משפטים כד, יב. זהר שמיני מ, ב. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' קפב."]]],[2300550672,"דקטנות בעיבור, ואמנם בזה דוקא שורה בחי' המקיף דיחידה להביא הכל מן ההעלם לגילוי בלידה (כמשי\"ת).\n<b>והנה</b> אחר כ\"ז יש להבין הטעם שאמר הקים על עולה דתו\"מ שהוא מה שנק' עובד אלקי' דוקא רק לבטל א\"ע למעשה בלבד בעול מ\"ש יותר מטבעו ורגילותו כו', שהרי דוד הוא משיח<sup data-n=\"7409\">390</sup> דלע\"ל דכתי' בי' ישכיל עבדי כו' וגבה מאד כו' (ואמר בו בני<sup data-n=\"7410\">391</sup> היום ילדתיך בבחי' לידה דנש\"י בכלל כנ\"ל) וכל העלם יביא לגילוי באו\"כ עד שכולם ידעו אותי כו', ואיך יהי' כ\"ז רק בעול בע\"כ בלבד כו'. אך הענין הוא דהקים עול היינו כל עומ\"ש שהי' בתחלה בחיצוני' בלא אור וחיות כלל הקים והגביה והעלה אותו למדרגה הגבוה והעליונה מהנ\"ל<sup data-n=\"7411\">392</sup> והוא בבחי' מקיף למקיף שנק' כת\"ר שבכת\"ר ונק' כת\"ר ש\"ט דמשיח שעולה גם על כת\"ר מל' וכתר תורה כו' (וכמ\"ש אבן מאסו הבונים<sup data-n=\"7412\">393</sup> שהן או\"א הית\"ה לראש פנ\"ה בעטר' ע\"ג הראש וכן אב\"ן הראש\"ה<sup data-n=\"7413\">394</sup> כו' והוא בחי' ב\"ן דנוג\"ה אחר הבירור ע\"י עומ\"ש דוקא בביטול הי\"ש לאי\"ן נגד הטבע כנ\"ל). והענין הוא כידוע בהפרש שבין או\"י לאו\"ח דבע\"ס דאו\"ח המל' בחי' כת\"ר<sup data-n=\"7414\">395</sup> כו', והענין הוא דבחי' עיבור או שינה דגלות זהו בחי' או\"ח דוקא כנ\"ל ואז בחי' המל' שהיא נה\"י דנה\"י בחי' כתר ממש. וזהו מ\"ש אני ישנה ולבי ער כו' שזהו בחי' טבעי' המדות בלב בחיצוני' דחיצוני' לענין מעשה לבד שנשאר בשינה דגלות בכנ\"י בלא אור וחיות כלל וכלל כו' כנ\"ל, ועד\"ז<sup data-n=\"7415\">396</sup> יכולים למס\"נ ממש על המעשה דמצות דוקא כידוע שמוכרח לומר שיש בזה דוקא מבחי' האו\"מ עצמי<sup data-n=\"7416\">397</sup> דיחידה ממש שממנו מקור כל רצון לטוב כו' כי נעוץ סב\"ת באו\"ח שהמל' כתר כו'.\n<b>וזהו</b> ולבי ער דזהו פלא גדול דאם הלב הוא בחי' מקבל מן המוח<sup data-n=\"7417\">398</sup> כידוע, וא\"כ איך יהי' כלי המוח שהוא המשפיע בשינה בהסתלקות והעלם לגמרי כנ\"ל ולבי ער שהלב אינו בהסתלקות והעלם כלל, שזהו <span data-k=\"pg\">1202</span> ּ ההיפוך מבהקיץ שאין ערך גילוי האור וחיות במדות שבלב ובחיצוני' שבו רק לפ\"ע קבלתו מן המוחי' שבראש כידוע ובשינה יהי' להיפוך שהמוח ישן והלב ער ולא ישונה מן אונס השינה. אלא מוכרח לומר דיש נקודה פנימי' בלב שלמעלה מן המוח לגמרי והוא בעצמות דיחידה (שבה א' בלא לב ולב<sup data-n=\"7418\">399</sup> שניהם שוין כו') שלא יפול בו ענין שינה כלל כנ\"ל, דשינה והקיץ שוין בו ממש דהיינו<sup data-n=\"7419\">400</sup> קטנות וגדלות שוין ממש כי קטנות וגדלות או או\"ח ואו\"י אינו שייך רק בהתפשטות דכתר כו'<sup data-n=\"7420\">401</sup> ולא בעצמיות ממש (וכמו ובשכב\"ך",[["7409","390","<b>דוד הוא משיח</b>: ראה ירושלמי ברכות פ\"ב, ה\"ד (ובפני משה). זהר לך פב, ב. פיוט אומץ ישעך (הושענות — להוש\"ר)."],["7410","391","<b>בני</b>: טז: אני."],["7411","392","<b>מהנ\"ל</b>: טזיז: מהכל."],["7412","393","<b>אבן מאסו הבונים</b>: תהלים קיח, כב. ראה גם לעיל פ' בשלח רלד, א ובהערה 778."],["7413","394","<b>אב\"ן הראש\"ה</b>: ראה זכרי' ד, ז. לעיל פ' בא קטו, ג ובהערה 255."],["7414","395","<b>דבע\"ס דאו\"ח המל' בחי' כתר</b>: נסמן לעיל פ' תצוה שעה, ב."],["7415","396","<b>ועד\"ז</b>: טזיז: ועכ\"ז."],["7416","397","<b>מבחי'. . עצמי</b>: טז: כח ואור דמקיף העצמי."],["7417","398","<b>הלב. . מקבל מן המוח</b>: ראה תניא פנ\"א (עא, סע\"ב). מאמרי אדה\"א דברים ח\"ב ע' תצב. וש\"נ."],["7418","399","<b>בלא לב ולב</b>: דהי\"א יב, לג. ראה גם לעיל פ' בשלח קצה, ב. וש\"נ."],["7419","400","<b>דהיינו. . ממש</b>: טז: ליתא. וכנראה נשמט מפני תיבות הדומות ממש. . ממש."],["7420","401","<b>דכתר כו'</b>: טז: ליתא כנ\"ל. יז: העצמיו'. יב כתב ממעל לתיבות אלו: דעצמו' ג\"כ."]]],[2300550677,"ובקומ\"ך<sup data-n=\"7421\">402</sup> שוין וכן אם זכרתי\"ך על יצועי<sup data-n=\"7422\">403</sup> בקטנות באשמורות בק\"ש בגדלות שוין). ואמנם בחי' עצמות זה שאין בו הפרש בין קטנות לגדלות ואו\"ח דשינה לאו\"י דהקיץ זהו בטבעיות הלב בחומר החיצוני דוקא שהוא עצמי וטבעי [ב]תולדתו (שממנו יתפשט טבעיות במוח אח\"כ דבנין החומר קדם לבנין הצורה<sup data-n=\"7423\">404</sup> לכל הדיעות, ותחלת ההתהוות החומר בא מן הלב ובהתהוות הצורה בא במוח<sup data-n=\"7424\">405</sup> תחלה כי בטבעיות וגשמיות הלב גבוה מן המוח וברוחניות ואור וחיות דצורה המוח משפיע ללב וכך הוסכם בס' הרפואה), ולכך גם בשינה במוח ועין ואזן כו' לבי ער כמו בהקיץ ממש. אך עכ\"ז ער זה רק בהעלם דמקיף בנקודת הלב שנק' תעלומות הלב<sup data-n=\"7425\">406</sup> כי הרי אין מחמת זה גילוי הרגשה ותנועה חיצוני' בשינה כלל דאע\"פ שלבו ער נרד\"ם בשינ\"ה כו'. וכך יובן בכנ\"י ברוחני' דנשמות שבחי' הטבע העצמי' בכלי הלב החיצוני' (שנק' נאטו\"ר בחומר הפשו\"ט והיול\"י שלמעלה מן הצורה שכלי' ורצוניות כו') למעשה המצות ואוי\"ר ששייך לזה כמו טבע ראשון עצמ[ו] שמאיר בתעלומות לבם בנקודה הפנימי' בהעלם ממקיף דיחיד' מ\"ם דצלם אף בשינה דגלות בקטנות דמוחי' ומדות בתכלית וכמ\"ש למעלה (דבבחי' או\"ח דשינה דוקא בחי' המל' דנה\"י שבנה\"י ושם הוא בחי' כת\"ר דכת\"ר), וע\"כ מחמת זה שלבו ער בגלות קול דודי דופק להיות כח המעורר העליון להביאו מאו\"ח דשינה לאו\"י דהקיץ שיאיר מהעלם דצל\"ם בנר\"נ בגדלות המוחי' כנ\"ל (כיוסף צ\"ע שהוא פות\"ר חלומות ותופ\"ר<sup data-n=\"7426\">407</sup> והוא משיח בן פור\"ת יוסף שמגדיל האורות בכלים כמו עד דוד הגדי\"ל<sup data-n=\"7427\">408</sup> וכמ\"ש וגבה מא\"ד<sup data-n=\"7428\">409</sup> ). ויובן זה גם בקטנות וגדלות דעיבור ולידה בכנ\"י דבחי' נה\"י דנה\"י (כתלת גו תלת ) כו' שהוא טבעי' המדות [באהוי\"ר למעשה לבד, זהו כמו ולבי ער בשינה שמאיר שם מקיף העליון דיחידה והוא מה שבא אח\"כ מקטנו' לגדלות בלידה דמשיח] שישכיל כו' עד וגבה מא\"ד בגילוי כל העלם דרזי' דאוריי' מתעלומות חכ'<sup data-n=\"7429\">410</sup> הקדומה, וגם למעלה מזה בכת\"ר שבכת\"ר שמשם מקור כל רצה\"ע [ועונג] העצמי דתו\"מ והוא כת\"ר ש\"ט דמשיח כנ\"ל), שכ\"ז יבא לע\"ל רק מבחי' עולה דתו\"מ בקטנות דעיבור בגלות, שזהו בא רק מצד בחי' הטבעי' בחומר הפשוט שיכול לבטל א\"ע לגמרי כאלו אינו מהות בפ\"ע כלל כנ\"ל בענין עובד אלקי' בעול שלמעלה מבן ועבד נאמן כו' וד\"ל.",[["7421","402","<b>ובשכב\"ך ובקומ\"ך</b>: ראה גם לעיל פ' משפטים רפד, ד. וש\"נ."],["7422","403","<b>אם זכרתי\"ך על יצועי</b>: ראה גם לעיל שם. וש\"נ."],["7423","404","<b>דבנין החומר קדם לבנין הצורה</b>: ראה גם לעיל פ' תצוה שלג, א ובהערה 586."],["7424","405","<b>ההתהוות החומר. . הלב ובהתהוות הצורה. . במוח</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תתנט. וראה ביאוה\"ז בלק קו, ב. [נדפס גם במאמרי אדה\"ז תקס\"ח ח\"א ע' רפג]. שע\"ת ח, ד."],["7425","406","<b>תעלומות הלב</b>: תהלים מד, כב. ראה גם לעיל פ' בא קו, ב הערה 411."],["7426","407","<b>פות\"ר. . ותופ\"ר</b>: ראה גם לעיל פ' שמות לט, ג ובהערה 91."],["7427","408","<b>עד דוד הגדי\"ל</b>: שמו\"א כ, מא."],["7428","409","<b>וגבה מא\"ד</b>: ישעי' נב, יג."],["7429","410","<b>מתעלומות חכ'</b>: איוב יא, ו. ראה גם לעיל פ' שמות לג, א. וש\"נ."]]],[2300550682,"<b>וזהו</b> קול דודי דופק פתחי לי לאעלא' בך<sup data-n=\"7430\">411</sup> כו', דהיינו להמשיך אורות ומוחי' העליוני' לבחי' המל' ובאו\"כ גם במדות שיהי' בנין המל' שלם ביח\"ע <span data-k=\"pg\">תרא</span> ּ בזו\"נ כו', והיינו לפי שלב\"י ע\"ר כשינה דגלות מטעם הנ\"ל ע\"כ ממילא מתעורר גם במשפיע מבחי' המקיף שלו להמשיך קול התעוררות לעורר מבחי' השינה דקטנות וכמו עד יערה עלינו רוח ממרום כו' וכמו שבשוב ה' כו' היינו כחולמים כו'. וזהו [ו]עינינו מאירות בבחי' מאור<sup data-n=\"7431\">412</sup> ומשפיע אור ולא בבחי' מוגבל<sup data-n=\"7432\">413</sup> מלמעלה (והוא מ\"ש ולציון יאמר אי\"ש ואי\"ש יולד בה<sup data-n=\"7433\">414</sup> שהוא בחי' לידה דמשיח שנק' איש בדומה למשפיע בחי' איש העליון כו' שנק' אד\"ם אדמ\"ה לעליון ממש), והיינו מה שיהי' בבחי' ראי' ושמיעה והילוך באור העצמי' דא\"ס כמ\"ש ולא יהי' לך השמש<sup data-n=\"7434\">415</sup> כו' שהוא סובב וממלא אלא ה' עצמו יהי' לך לאור עולם) וכמו ונחיה לפניו<sup data-n=\"7435\">416</sup> ממש בעוה\"ב כו'), והיינו בחי' איש ולא אשה כעכשיו שאין הגילוי אור רק לפ\"ע ההתעוררות מלמעלה בלבד כנ\"ל וד\"ל. וזהו ואלה דברי דוד האחרונים מכלל דאיכא ראשונים<sup data-n=\"7436\">417</sup> דהיינו מה שמל' מקבל מחו\"ב שנק' ע' שני' שאולי' מן אדה\"ר<sup data-n=\"7437\">418</sup> ע\"י [המשכות] האור דמוחי' ומדות שבא באו\"י בצמצום לפ\"ע המקבלים אבל באו\"ח דמל' נק' ד\"ד<sup data-n=\"7438\">419</sup> האחרונים דהמל' כת\"ר עד דכת\"ר מל' איהו כ\"ע<sup data-n=\"7439\">420</sup>, ע\"כ אמר הקים על עולה של תורה<sup data-n=\"7440\">421</sup> שהוא היגיעה והילוך מכח בחירת עצמו דוקא בביטול היש לאין בקבלת [עו]מ\"ש לבד שהקים והגביה לבחי' עומ\"ש דכנ\"י שעי\"ז דוקא תאיר אור הפנימי' דכתר מל' דאיהו כ\"ע כו' משום דנתב\"ס דוקא, וזהו משום דלבי ער בנקוד' הפנימי' שבהעלם בלב שמאיר שם מבחי' יחידה דוקא כנ\"ל וד\"ל.\n<b>והנה</b><sup data-n=\"7441\">*422</sup> להבין ביאור זה באופן אחר יש להקדים עוד ענין א' והוא מ\"ש דנה\"ד נגיד ונפיק מקדמוהי<sup data-n=\"7442\">422</sup> כו' ומשמע מפשט הכתוב דנהר של אש נגיד ונמשך מקדמוהי מלפני אור עצמות אלקות כו' שזהו מן קדמוהי ממש, וזהו פלא איך יוכל להיות מציאות נהר של אש גשמי יוצא ונמשך מעצמות אור אלק[י שזהו מ\"ש וע\"י יתיב כורסיי' כו', ו]אע\"פ שנק' אש אוכלה כו' זהו שם המושאל והלא גם ברוח ורעש ואש דמלאכי' דבריאה א' ולא באש הוי'<sup data-n=\"7443\">423</sup> כו' לפי שנבדל בערך ממציאות הנבראים [אף] שנק' אש לוהט<sup data-n=\"7444\">424</sup> כו'. ועוד שהרי ארז\"ל דנהר דינור זה נעשה מזיעתן של חיות<sup data-n=\"7445\">425</sup> הקדש לבד",[["7430","411","<b>פתחי לי לאעלא' בך</b>: שה\"ש ה, ב. ראה זהר אמור צה, א."],["7431","412","<b>[ו]עינינו מאירות בבחי' מאור</b>: ראה גם לעיל פ' בשלח רג, ד. וש\"נ."],["7432","413","<b>מוגבל</b>: טזיז: מקבל."],["7433","414","<b>ולציון יאמר אי\"ש ואי\"ש יולד בה</b>: תהלים פז, ה. ראה גם ש\"א לג, א."],["7434","415","<b>ולא יהי' לך השמש</b>: ראה גם לעיל פ' יתרו רסב, ב. וש\"נ."],["7435","416","<b>ונחי' לפניו</b>: הושע ו, ב."],["7436","417","<b>ואלה. . מכלל דאיכא ראשונים</b>: מועד קטן טז, א. ראה גם מאמרי אדה\"א דברים ח\"א ע' יט. וש\"נ. שמות ח\"ב ע' שסא."],["7437","418","<b>ע' שני' שאולי' מן אדה\"ר</b>: ראה זהר וישלח קסח, א. בראשית נה, סע\"א. לך צא, ב. מאמרי אדה\"א קונטרסים ע' שנא. וש\"נ."],["7438","419","<b>ד\"ד</b>: טז: דברי דוד."],["7439","420","<b>דכת\"ר מל' איהו כ\"ע</b>: ראה ת\"ז בהקדמה (יז, א)."],["7440","421","<b>של תורה</b>: טזיז: דתו\"מ."],["7441","*422","<b>והנה</b>: יב נרשם: ה [ד נרשם לעיל על יד הערה *380. ו נרשם לקמן על יד הערה *464]."],["7442","422","<b>דנה\"ד </b>[טזיז: דנהר דינור]<b> </b>נגיד ונפיק מקדמוהי: דניאל ז, י [ושם: נהר די-נור. . מן קדמוהי]."],["7443","423","<b>ולא באש הוי'</b>: מל\"א יט, יב [ושם: לא]. ראה גם מאמרי אדה\"א נ\"ך ע' יד ואילך (ובהנסמן בריש המאמר שם)."],["7444","424","<b>אש לוהט</b>: תהלים קד, ד."],["7445","425","<b>דנהר דינור. . מזיעתן של חיות</b>: ראה חגיגה יג, ב. לקמן תט, ב."]]],[2300550687,"כידוע וחיות הקדש אינו רק ביצי' או בבריאה<sup data-n=\"7446\">426</sup> כידוע, וגם זה אינו רק מזיעתן של חיות שהוא רק הפסולת שלהם כו'. וגם בס' הקבלה כ\"ז<sup data-n=\"7447\">427</sup> דהנהר דינור הזה הוא בסמוך לגעה\"ע שכאשר הנשמות עולי' מגעה\"ת לגעה\"ע<sup data-n=\"7448\">428</sup> טובלי' בנה\"ד זה הנשמות שיתבטלו מהמציאות שלהם ויוכלו לקבל אור וזיו השכינה בגעה\"ע כו'. אך הנה תחלה י\"ל מהו ענין עונג העליון שבא בגעה\"ע לנשמות שנק' זי\"ו השכינה<sup data-n=\"7449\">429</sup> כידוע, דהנה ידוע בפי' שכינה בכלל שהוא בחי' מל' דאצי' שמתצמצם להיות מלך על עם כו' והוא מה שמל' דאצי' נעשה עתיק וכת\"ר לבריאה<sup data-n=\"7450\">430</sup>, וזהו שנק' זי\"ו השכינה שיוכל להיות מקור למציאות עונג המוגבל לנשמות דבריאה בגעה\"ע שיהיו נהנין ומשיגי' בזיו זה שהוא בחי' בינה דמל' כו'. וזהו ה' מלך גאות לבש בבחי' לבוש <span data-k=\"pg\">1204</span> ּ וצמצום גדול ואין לזה ערך כלל לבחי' המל' כמו שהיא בבחי' אצי' ממש וד\"ל<sup data-n=\"7451\">432</sup> (שזהו בחי' דלי\"ת רבת\"י דאח\"ד<sup data-n=\"7452\">431</sup> ) כמו שהיא בבחי' עצם ההתנשאות שלמעלה הרבה מהיות מתנשא על ימ\"ע בלבד כו' ונק' מלך מרומם לבדו כו' מלך יחיד או מלך הקדוש כידוע. וכך הוא למעלה מן האצי' ממל' דא\"ס בקו\"ח מקור כל ההשתלשלו' דאבי\"ע כמ\"ש אני ראשו\"ן ואני אחרו\"ן<sup data-n=\"7453\">433</sup> כו' לפי שאין ערך אצי' לגבי המאציל<sup data-n=\"7454\">434</sup> עצמו כו' וצריך שיהי' ג\"כ ע\"י צמצום הראשון שנתצמצם מעצם ההתנשאות דמל' דא\"ס עצמו להיות מלכותך מכ\"ע<sup data-n=\"7455\">435</sup> בקו\"ח עד מל' דאצי' בבי\"ע כו', וזהו שנק' מלך יחיד לבדו ואח\"כ נמשך ממל' דא\"ס ע\"י צמצום להיות מכ\"ע שנק' ח\"י העולמים בכללות כידוע וד\"ל.\n<b>והנה</b> אע\"פ שמתצמצם מעצם מדת מל' דא\"ס (שהוא בחי' ההתנשאות שמצד רוממות העצמו' דא\"ס ממש שאין לו שיעור למעלה שזהו מובדל בערך לגמרי מהיות מלך כ\"ע כנ\"ל) בא צמצום זה בב' מדרגות תחלה בכלל ואח\"כ בפרט, דהיינו מה שמתצמצם להיות בבחי' מלך על דבר זולתו זהו עצמו שגרם להיות בחי' התפשטות אור ושפע חוץ מעצמותו ממש, והוא בחי' מחשבה אחת הכללי' שמיד שעלה במח' ורצון הפשוט בבחי' מל' [ל]עולמות זהו בחי' מקור כללי לכללות כל ההשתל' דקו\"ח עד מל' דעשי' שנכללו כולם כא' בהעלם א' במח' זו הכללי' דמל' דא\"ס שנתצמצם מעצמות מדה זו כנ\"ל וד\"ל. ואח\"כ יצא מן ההעלם דמח' זו רצון<sup data-n=\"7456\">436</sup> הכללי דמל' בדרך פרט, שזהו בבחי' המשכה דקו\"ח כו' עד מל' דא\"ק בחי' כת\"ר<sup data-n=\"7457\">437</sup> וע\"י<sup data-n=\"7458\">438</sup> שזהו להאציל ע\"ס באו\"כ בפרט ולברוא עולם הבריאה כו' עד בחי' מל' דעשי' בחי' מקור פרטי לפרטיות דעולם העשי' כידוע. וזהו אני ראשון במח' הכללי' דמל' דא\"ס להאיר בקו\"ח כנ\"ל ואנ\"י זה אחרו\"ן בפרט האחרון יותר כו'<sup data-n=\"7459\">439</sup> בלי שינוי כלל",[["7446","426","<b>וחיות. . ביצי' או בבריאה</b>: ראה לעיל פ' תצוה שמ, ג הערה 760. שכה, ד הערה 265."],["7447","427","<b>כ\"ז</b>: טזיז: נז'."],["7448","428","<b>הנשמות עולי' מגעה\"ת לגעה\"ע</b>: ראה לעיל פ' שמות ה, ד ובהערה 263."],["7449","429","<b>זי\"ו השכינה</b>: ראה ברכות יז, א. ביאוה\"ז אחרי עה, א."],["7450","430","<b>שמל' דאצי' נעשה עתיק וכת\"ר לבריאה</b>: נסמן לעיל פ' משפטים רעט, ד."],["7451","432","<b>וד\"ל</b>: טזיז: ליתא."],["7452","431","<b>המל'. . דלי\"ת רבת\"י דאח\"ד</b>: ראה גם לעיל פ' וארא עה, ב ובהערה 194."],["7453","433","<b>אני ראשו\"ן ואני אחרו\"ן</b>: ישעי' מד, ו."],["7454","434","<b>שאין ערך אצי' לגבי המאציל</b>: ראה גם לעיל פ' תצוה שנו, ד ובהערה 39."],["7455","435","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג. ראה גם לעיל פ' בשלח קמב, ב. וש\"נ."],["7456","436","<b>זו רצון</b>: טז: ורצון. יז: ורצון זו."],["7457","437","<b>מל' דא\"ק בחי' כתר לע\"י</b>: ראה ע\"ח (שער סדר אצי') ש\"ג, פ\"א. לעיל פ' שמות ה, ב. וש\"נ."],["7458","438","<b>וע\"י</b>: יז: לע\"י."],["7459","439","<b>כו'</b>: טז: כנ\"ל. יז: ליתא."]]],[2300550692,"והוא לפי שאין הפרט נבדל מן הכלל, דכל מה שנעשה ונמשך בדרך פרטי הכל הוא בא מכח המח' הכללי' דוקא שאם אין כלל אין פרט כו'. וכידוע במשל אדם שעלה ברצונו לבנות בנין גדול למראה בכמה פרטי' מחולקי' בחדרים ועליות רבות בציור אופן פרטי מוגבל כו', דודאי תחלה בעלות ברצונו יעלה זה הענין במחשבה בדרך כללית דוקא דהיינו שרוצה וחפץ שיהי' לו בנין בציור כזה הכולל שע[ו]לה במח' ומחמת כוונה פנימי' שיש לו בזה שנעלם ברצונו זה, ואמנם פרטי חלקי ציור הבנין הזה שעולה במחשבה אינו מתחלק כאו\"א בפ\"ע כלל אלא הכל נסקר כא' בסקירה כללי' מראש הבנין לסופו כא' ממש [מ]בלי סדר והדרגה בזה אלא כללו' ענין ציורו מראשו לסופו כא', כמו שחושב ומצייר במח' איזה בנין גדול שרואה[ו] שנתפס כולו כא' כו'. אך אח\"כ כאשר חפץ לגלות רצונו לאומן שיבנה הבנין הזה בפ\"מ דוקא אזי בהכרח שיתפשט <span data-k=\"pg\">תרב</span> ּ ויתגלה מהעלם דמח' ורצון הכללי הזה לחלקים פרטי' דוקא בסדר והדרגה דוקא מראש לסוף שמצוה לבנות כך וכך בכל חדר ועלי' בציור אופן פרטי כו'. ונמצא שנתחלק הרצון ומח' הכללי' הנ\"ל לכמה חלקי' פרטי' ובסדר דוקא מה שלא הי' ניכר ונראה כל אלה במח' הכללי' כי הכל ה[י'] שם בהתכללות א' בהעלם א' ולכך נק' מחשבה א' מצומצמת כו', ועכ\"ז ודאי מובן שכל עיקר הגילוי מרצון בכל פרט באופני מעשה הבנין בפ\"מ הכל הוא נמשך ויוצא רק מן המח' הכללי' דוקא שהי' שם בהעלם כל פרט ופרט דוקא, ולזאת רק כפי עצם כוונתו הכללי' במח' הכללי' כך ממש יוצא לגילוי בפרט בפ\"מ לא יוסיף ולא יגרע אפי' כקש\"י כידוע וד\"ל.\n[ט]<b> וכך</b> יובן מזה הנמשל למעלה בבחי' מח' הכללית דמל' דא\"ס כנ\"ל דזהו כמו שעלה ברצונו הפשוט בכללות לבנין כל העולמות כמו כי אמרתי עולם חסד יבנה<sup data-n=\"7460\">440</sup> שאמרתי זה כשעלה במח' כנ\"ל ה\"ז עצמו הי' בחי' מקור כללי לכל מה שיצא אח\"כ לגילוי להיות התהוות כל ההשתל' דאבי\"ע בהתחלקות פרטיות (שהוא ממש כמו קודם שיצא הרצון הפשוט לגילוי והי' בהעלם בעצמו כענין שאמר דגליף גליפו בטה\"ע שזהו מה ששיער בעצמו בכח<sup data-n=\"7461\">441</sup> מה שעתיד להתגלות ברצונו וחכמתו לבנין ההשתל' בפרטי פרטיות), דודאי הגם שמח' זו הכללי' כולל כל ההשתל' מראש לסוף כא' ממש בלי מוקדם ומאוחר ולא הי' התחלקות כל עולם בפ\"ע כמו שלא הי' התחלקות במח' א' ברצונו בכללות הבנין כנ\"ל, מ\"מ כל פרט ופרט שבא בגילוי בהשתלשלו' הי' הכל בהעלם בכללות המח' הנ\"ל ומכח המח' הכללית הוא שנמשך אח\"כ כל פרט בהמשכה דקו\"ח להאציל ולברוא כו' ואין זה רק שיצא מן ההעלם לגילוי",[["7460","440","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["7461","441","<b>דגליף גליפו. . ששיער בעצמו בכח</b>: נסמן לעיל פ' תצוה שכה, ד."]]],[2300550696,"בלבד כמובן ממשל הנ\"ל בבנין בית. וז\"ש בראשית ברא<sup data-n=\"7462\">442</sup> בכללות וכמו שאו' שאמר והיה העולם בכלל בכל ו\"א שנין<sup data-n=\"7463\">444</sup> כו' סוקר הכל כא' ומכללו' ז[ו] הוא שיוצא ונמשך בפרטי פרטית וזהו אומר ועושה<sup data-n=\"7464\">443</sup> כו'. וזהו שא' דבמאמר א' יכול להבראות<sup data-n=\"7465\">445</sup> ונחלק לי\"מ כו', ומבואר למעלה דודאי יש גם במח' הכללית לבנו' בנין וכה\"ג באיזה אופן פרטי שבאותו אופן דוקא יש לו טעם וכוונה פנימית ונעלמת לרצון ולא באופן אחר ולזאת עפ\"י אותו הטעם וכוונה הפנימי' ונעלמת נמשך אופן סדר המעשה כך וכך דוקא. וכך יובן בפרטות דמע\"ב כמ\"ש בראשית ברא כו' במח' כללית הי' בזה כוונה וטעם שהוא הענג העליון הנעלם בזה, ולפי אותו הענג והטעם שהי' במח' הכללית דוקא כך יומשך אח\"כ מן ההעלם לגילוי כל אופני הפרט של הבנין דעולמות בפנימי' וחיצוני' כמו היכלות פנימי' בבית וחצר כו' וכל ציור אופני הבנין יש בכללותו טעם ונמשך לכל פרט ופרט שבו. ואע\"פ שכל מע\"ב נמשך רק עפ\"י חסד א' שא' כי אמרתי עולם חסד יבנה שזהו חסד כללי שהוא מה שיש מטבע הטוב וחסד בעצם להטיב<sup data-n=\"7466\">446</sup> ולגלות חסדו כו', אבל ודאי יש בחסד כללי זה <span data-k=\"pg\">1206</span> ּ לבנין העולמות כוונה ועונג בהעלם שמפני זה נעשה אופן החסד הזה בפרט בציור מדוקדק בכל בריאה ובריאה ממש אח\"כ בי\"מ, כמו במא' יהי אור שיצא מהעלם דמח' הכללית [ב]אותו אופן כזה דוקא ולא במציאות אופן אחר וכן יהי רקיע<sup data-n=\"7467\">447</sup> בציורו ובהרכבתו מאש ומים<sup data-n=\"7468\">448</sup> ולא באופן אחר, וכן ציור דשמש וירח וכו\"מ וציור כל הברואים שיצאו מן הארץ כשור וארי' וכל נפש חיה וגם הצומח בכל חלקיו וכ\"ש המדבר כו', הכל הי' ע\"פ הכוונה וטעם כמו שאדם שמצייר במח' הכללי' כל פרטי אופן הבנין בכל חדריו כו' כנ\"ל וכמ\"ש כי הוא צוה במח' הכללית ונבראו<sup data-n=\"7469\">449</sup> ממילא בדבור די\"מ בפרטי פרטי' בציור באופן פרטי וזהו חק נתן בכל בריא' ולא יעבור<sup data-n=\"7470\">450</sup> כו' לפי הכוונה הפנימי' שהי' ברצון ומח' הכללית דוקא מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> כ\"י אמרת\"י כשעלה ברצונו הפשוט בכוונה ועונג המכוון שעולם בחסד יבנה בדרך פרט דוקא [ב]מאמר קו המדה שמודד כל ציור אופן הבנין שזהו כי ח\"ק נת\"ן כו' ואף במלאכים דבי\"ע וגם באצי' בע\"ס א[ו]\"כ מקיפי' ופנימי' הכל ע\"י הקו\"ח כידוע, והנה הכוונה הפנימי' והעונג הנעלם בכל ההשתלשלו' הי' זה בדרך כלל ובדרך פרט ובבחי' הכלל זהו ענין המכוון הפנימי בכללות שהוא כמ\"ש כל הנק' בשמי<sup data-n=\"7471\">451</sup> ולכבודי בראתיו יצרתיו כו' דמשמע דכל עיקר המכוון הפנימי בכללות הבריאה הוא לכבודי דוקא וא' בזהר בגין דישתמודע[י]ן לי'<sup data-n=\"7472\">452</sup> כו', והוא",[["7462","442","<b>בראשית ברא</b>: בראשית א, א."],["7463","444","<b>ו\"א שנין</b>: ר\"ה לא, א. ראה הנסמן במאמרי אדה\"א בראשית ע' נג."],["7464","443","<b>שאמר והיה העולם. . אומר ועושה</b>: נוסח ברכת ברוך שאמר."],["7465","445","<b>דבמאמר א' יכול להבראות</b>: ראה אבות רפ\"ה."],["7466","446","<b>מטבע הטוב. . להטיב</b>: ראה שער היחוד והאמונה פ\"ד. לקמן תמב, א. לעיל פ' שמות לד, ג. וש\"נ."],["7467","447","<b>יהי רקיע</b>: בראשית א, ו."],["7468","448","<b>רקיע. . מאש ומים</b>: ראה חגיגה יב, סע\"א."],["7469","449","<b>כי הוא צוה. . ונבראו</b>: תהלים קמח, ה."],["7470","450","<b>חק נתן. . ולא יעבור</b>: תהלים שם, ו."],["7471","451","<b>כל הנק' בשמי</b>: ישעי' מג, ז."],["7472","452","<b>לכבודי. . בגין דישתמודע[י]ן לי'</b>: ראה זהר (רע\"מ) בא מב, א ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' רסא. וש\"נ. שה\"א מח, ב הערה 14. לקמן תטז, ב."]]]]});
